window.ARTEMIS_ARCHITECTURE_DATA={"scope":"A conceptual logic map, not every possible real-world metric or failure. Definitions here are not hardware-validated coverage. No live telemetry or model output is displayed. Every selected algorithm is Pending.","failures":[{"id":"gpu.ecc_uncorrectable_contained","domain":"gpu","name":"Uncorrectable memory error, contained (Xid 94)","summary":"An uncorrectable ECC error in GPU memory that error containment limited to one application (A100, H100 and later data-center GPUs). That application is terminated: the training job crashes. Other work on the GPU keeps running and new work can start; the faulty page is offlined and a row remap is recorded, to take effect at the next GPU reset.","job_effect":["crash"],"blast_radius":"gpu","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Xid 94, contained memory error","source":"Kernel log","identifier":"Kernel log line `NVRM: Xid (PCI:\u003cbdf>): 94, pid=\u003cpid>, Contained: ... RST: No, D-RST: No` (grep \"NVRM: Xid\"; a GPU-I field appears with MIG)","detection":"any occurrence; the pid is the terminated application","strength":"definitive","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"name":"Xid 48 with Xid 171 (DRAM) or 172 (SRAM): which memory, not containment","source":"Kernel log","identifier":"Xid 48 (double bit ECC error) followed by Xid 171 (DRAM) or 172 (SRAM) for the same PCI address","detection":"any occurrence: an uncorrectable error happened, and 171 vs 172 says DRAM or SRAM. It does not say whether the error was contained; Xid 94 (contained) or 95 (uncontained) decides that.","strength":"suggestive","ref":"https://docs.nvidia.com/deploy/a100-gpu-mem-error-mgmt/user-visible-statistics.html"},{"name":"Xid 63, row remap recorded","source":"Kernel log","identifier":"Xid 63 (GPU memory remapping event) after the 94/48 for the same PCI address","detection":"present: the repair is recorded and pending (gpu.memory_repair_pending); Xid 64 instead: recording failed (gpu.memory_repair_exhausted)","strength":"definitive","ref":"https://docs.nvidia.com/deploy/a100-gpu-mem-error-mgmt/user-visible-statistics.html"},{"name":"Recovery action Drain and Reset","source":"DCGM","identifier":"DCGM_FI_DEV_GPU_RECOVERY_ACTION (field 1523; values per nvmlDeviceGpuRecoveryAction_t), also `nvidia-smi --query-gpu=gpu_recovery_action` and Xid 154","detection":"value Drain and Reset: no new work on the GPU, let running work finish, then reset. nvidia-smi documents it as asserted only for UCE row remaps, so it makes this entry the leading hypothesis, but says the field is not meant to determine which fault triggered it; Xid 94 or DCGM_FR_CONTAINED_ERROR decides this entry.","strength":"strong","ref":"https://docs.nvidia.com/deploy/a100-gpu-mem-error-mgmt/error-recovery-and-response-flags.html"},{"name":"Volatile double-bit ECC count rises","source":"DCGM","identifier":"DCGM_FI_DEV_ECC_DBE_VOL_TOTAL (field 311; commented out in dcgm-exporter's default CSV)","detection":"any increase over the job's window says an uncorrectable error happened, not whether it was contained (Xid 94/95 decide); volatile counts reset at driver reload, so compare within one driver load","strength":"suggestive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"name":"DCGM memory health watch: contained error","source":"DCGM","identifier":"`dcgmi health -g \u003cgroup> -s m`, then `dcgmi health -g \u003cgroup> -c`: failure condition DCGM_FR_CONTAINED_ERROR (Xid 94 occurred)","detection":"any report","strength":"definitive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/feature-overview.html"},{"name":"New uncorrectable ECC count during the job","source":"Artemis analysis, algorithm pending","identifier":"Uncorrected ECC count read through NVML during the job, compared with the count at job start","detection":"An increase against the count at job start: an uncorrectable error happened, not whether it was contained (Xid 94/95 decide)","strength":"Pending"}],"confounders":[{"failure":"gpu.ecc_uncorrectable_uncontained","how_to_distinguish":"Xid 95 (Uncontained, RST: Yes) instead of 94, or Xid 140; more than one application affected."},{"failure":"gpu.mmu_illegal_address_fault","how_to_distinguish":"Xid 13 or 31 with no Xid 48/94 and no ECC increase points at the application."},{"failure":"Xid 45 (preemptive cleanup)","how_to_distinguish":"NVIDIA's Xid catalog says Xid 45 is seen with 94/95; it follows the fault and is not a second one."}],"diagnosis":"Xid 94 confirms that a contained uncorrectable error terminated the named process. Containment is reported only by Xid 94 (contained) or 95 (uncontained), or by DCGM_FR_CONTAINED_ERROR / DCGM_FR_UNCONTAINED_ERROR, which report those Xids. Xid 48 with 171 or 172 says an uncorrectable error happened and whether it was in DRAM or SRAM, not whether it was contained. A volatile DBE increase (DCGM_FI_DEV_ECC_DBE_VOL_TOTAL) likewise says an uncorrectable error happened; on its own it cannot choose between this entry, where unaffected work continues, and gpu.ecc_uncorrectable_uncontained, where the GPU needs a reset, so read the Xid first. The next Xid decides the follow-up: 63 means a remap is recorded and waits for a reset; 64 means recording failed. Volatile counts reset at driver reload and aggregate counts can predate the job. The training job's crash is explained once the Xid's pid matches one of its ranks.","fixes":[{"fix":"cordon_node","when":"Immediately, before any restart, so the job's restart lands elsewhere and the GPU drains naturally (NVIDIA: other applications can keep running until the reset).","order":1},{"fix":"restart_from_checkpoint","when":"The job crashed; restart it once the node is cordoned, so it lands elsewhere.","order":2},{"fix":"gpu_reset","when":"Once the GPU is idle: applies the recorded row remap.","order":3},{"fix":"run_active_diagnostic","when":"After the reset, before the hold is released.","order":4}],"human_role":"Cluster operator approves the GPU reset and, on Slurm, the release of the node's hold (`State=RESUME`); also acts if the reset or the diagnostic fails, or the row-remap failure flag is set (then gpu.memory_repair_exhausted).","verification":{"remeasure":"After the reset: recovery action None, DCGM_FI_DEV_ROW_REMAP_PENDING 0, row remap failure 0; no new Xid 94/95/48 on the GPU over an observation window (length: Pending); the restarted job's throughput within 2% of its healthy value over at least 3 samples.","post_repair_check":"`dcgmi diag -r 2 -i \u003cgpu ids>` on the reset GPU passes before the node's hold is released (cordon_node's rollback rule)."},"escalation_steps":["Collect the Xid lines for the PCI address in order (94, 48, 171/172, 63 or 64, 154) and the pid each names.","Read `nvidia-smi -q -d ROW_REMAPPER` (remapped rows, pending, failure) and the bank-availability buckets.","For Xid 172 (SRAM), check the SRAM threshold-exceeded flag; if set, run the field diagnostic.","On a repeat contained error on the same GPU (window: Pending), run `dcgmi diag -r 3 -i \u003cgpu ids>` on that GPU once no job is allocated it, and open a vendor ticket with nvidia-bug-report.sh output."],"references":[{"title":"NVIDIA Xid catalogue","url":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"title":"NVIDIA GPU memory error management: error containment","url":"https://docs.nvidia.com/deploy/a100-gpu-mem-error-mgmt/error-containment.html"},{"title":"NVIDIA GPU memory error management: response to uncorrectable contained ECC errors","url":"https://docs.nvidia.com/deploy/a100-gpu-mem-error-mgmt/response-to-uncorrectable-contained-ecc-errors.html"},{"title":"NVIDIA GPU memory error management: user visible statistics","url":"https://docs.nvidia.com/deploy/a100-gpu-mem-error-mgmt/user-visible-statistics.html"},{"title":"NVIDIA GPU debug guidelines: GPU node triage","url":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/gpu-node-triage.html"}]},{"id":"gpu.ecc_uncorrectable_uncontained","domain":"gpu","name":"Uncorrectable memory error, not contained (Xid 95, Xid 140, pre-Ampere Xid 48)","summary":"An uncorrectable ECC error that containment could not limit (Xid 95), one that interrupted the driver's offlining or remapping (Xid 140), or any double-bit error on Volta and earlier, where uncorrectable errors affect every workload on the GPU. Every job on the GPU crashes and the GPU needs a reset (or, with MIG disabled, the node a reboot) before work can restart.","job_effect":["crash","capacity_loss"],"blast_radius":"gpu","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Xid 95, uncontained memory error","source":"Kernel log","identifier":"`NVRM: Xid (PCI:\u003cbdf>): 95, pid=\u003cpid>, Uncontained: ... RST: Yes, D-RST: No`","detection":"any occurrence (Xid catalog bucket RESET_GPU)","strength":"definitive","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"name":"Xid 140, ECC unrecovered error","source":"Kernel log","identifier":"Xid 140 for the GPU's PCI address","detection":"any occurrence: reset; contact the vendor if it persists","strength":"definitive","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"name":"Xid 48 on Volta or earlier","source":"Kernel log","identifier":"`XID 48 An uncorrectable double bit error (DBE) has been detected on GPU (\u003cid>)`","detection":"any occurrence on a GPU without error containment (no Ampere-class containment)","strength":"definitive","ref":"https://docs.nvidia.com/deploy/dynamic-page-retirement/visibility.html"},{"name":"Recovery action Reset or Reboot","source":"DCGM","identifier":"DCGM_FI_DEV_GPU_RECOVERY_ACTION (field 1523), `nvidia-smi --query-gpu=gpu_recovery_action`, Xid 154 text","detection":"Reset (example scenario: uncontained HBM/SRAM UCE) or Node Reboot Required. The field gives the required step, not the fault: the same page's Reboot example is a UVM fatal error. Xid 95 or 140, or DCGM_FR_UNCONTAINED_ERROR, decides this entry.","strength":"suggestive","ref":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"},{"name":"DCGM memory health: uncontained error","source":"DCGM","identifier":"`dcgmi health -c` failure condition DCGM_FR_UNCONTAINED_ERROR ('XID 95 occurred')","detection":"any report","strength":"definitive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/feature-overview.html"},{"name":"DCGM memory health: volatile DBE","source":"DCGM","identifier":"`dcgmi health -c` failure condition DCGM_FR_VOLATILE_DBE_DETECTED (volatile DBEs since the last GPU reset)","detection":"any report: an uncorrectable error happened since the last reset, not whether it was contained; on a GPU with containment, Xid 94 or 95 decides, and on Volta or earlier the Xid 48 signal above confirms","strength":"suggestive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/feature-overview.html"}],"confounders":[{"failure":"gpu.ecc_uncorrectable_contained","how_to_distinguish":"Xid 94 and RST: No: one application affected, no reset needed to continue."},{"failure":"fabric.nvlink_link_down","how_to_distinguish":"NVIDIA's Xid catalog notes a GPU connected to a failed GPU may report Xid 74 only because the link went down; find which GPU logged the memory Xid first."}],"diagnosis":"Xid 95 or 140, or Xid 48 on a GPU without containment, confirms the cause of every crash on that GPU in that window. On a GPU with containment, a volatile DBE count or DCGM_FR_VOLATILE_DBE_DETECTED says an uncorrectable error happened, not that it escaped containment, and Xid 171/172 only say DRAM or SRAM; Xid 95 (or DCGM_FR_UNCONTAINED_ERROR, which reports it) decides. The recovery-action field gives the required step. Whether the GPU is failing (rather than hit once) is decided by recurrence, the remap and retirement counters, and diagnostics after the reset, not by the event itself.","fixes":[{"fix":"cordon_node","when":"Immediately, before any restart.","order":1},{"fix":"restart_from_checkpoint","when":"The affected jobs crashed; restart them once the node is cordoned.","order":2},{"fix":"gpu_reset","when":"MIG enabled or recovery action Reset: drain the other GPU instances, then reset (GPU debug guidelines).","order":3},{"fix":"node_reboot","when":"MIG disabled or recovery action Reboot: the guidelines say reboot the node immediately.","order":3},{"fix":"run_active_diagnostic","when":"After the reset or reboot: `dcgmi diag -r 3 -i \u003cgpu ids>` on the reset GPUs (after a reboot, `-i \u003cnode gpu ids>`).","order":4},{"fix":"rma_replace_hardware","when":"The errors continue after the reset, or the diagnostic fails.","order":5}],"human_role":"Cluster operator approves the GPU reset or node reboot and reviews the diagnostic result before return to service; vendor RMA through the system vendor on recurrence.","verification":{"remeasure":"Recovery action None after the reset or reboot; no new Xid 95/140/48 on the GPU over an observation window (length: Pending); restarted jobs' throughput within 2% of their healthy value.","post_repair_check":"`dcgmi diag -r 3 -i \u003cgpu ids>` on the reset GPUs (after a reboot, `-i \u003cnode gpu ids>`) passes; row remap failure flag 0 (or, pre-Ampere, retired pages below the RMA thresholds)."},"escalation_steps":["Collect the Xid lines with PCI address, pid and order, and the Xid 154 recovery action.","Check whether MIG is enabled (it decides GPU reset versus node reboot).","Read ECC, remapped-row or retired-page counters (`nvidia-smi -q -d ECC,ROW_REMAPPER,PAGE_RETIREMENT`).","If the error recurs after a reset, drain, run the field diagnostic and report to the vendor with nvidia-bug-report.sh output."],"references":[{"title":"NVIDIA Xid catalogue","url":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"title":"NVIDIA GPU debug guidelines: GPU node triage (Xid 95, reset capabilities)","url":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/gpu-node-triage.html"},{"title":"NVIDIA GPU memory error management: error containment","url":"https://docs.nvidia.com/deploy/a100-gpu-mem-error-mgmt/error-containment.html"},{"title":"nvidia-smi documentation (GPU Recovery Action)","url":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"}]},{"id":"gpu.memory_repair_pending","domain":"gpu","name":"Memory repair pending a GPU reset (row remap pending, pending page blacklist)","summary":"A memory repair has been recorded but not applied: on Ampere and later a row remap pending, on earlier GPUs a retired page not yet blacklisted. The GPU keeps working (dynamic page offlining keeps new allocations off a faulty page on supported GPUs), but runs at slightly reduced capacity until a GPU reset, driver reload or reboot applies the repair.","job_effect":["latent","capacity_loss"],"blast_radius":"gpu","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Row remap pending","source":"DCGM","identifier":"DCGM_FI_DEV_ROW_REMAP_PENDING (field 396; not in dcgm-exporter's default CSV)","detection":"value 1","strength":"definitive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"name":"Row remapper status","source":"NVML / nvidia-smi","identifier":"`nvidia-smi -q -d ROW_REMAPPER` (pending and failure booleans, remapped-row counts, bucketized bank counts)","detection":"Pending: Yes","strength":"definitive","ref":"https://docs.nvidia.com/deploy/a100-gpu-mem-error-mgmt/user-visible-statistics.html"},{"name":"Pending page blacklist (Volta and earlier)","source":"NVML / nvidia-smi","identifier":"`nvidia-smi -i \u003cgpu> -q -d PAGE_RETIREMENT` field Pending Page Blacklist; NVML nvmlDeviceGetRetiredPagesPendingStatus; DCGM_FI_DEV_RETIRED_PENDING (exporter name; field 392, DCGM_FI_DEV_PAGE_RETIRED_PENDING on the current field-ID page)","detection":"Yes / 1","strength":"definitive","ref":"https://docs.nvidia.com/deploy/dynamic-page-retirement/visibility.html"},{"name":"Xid 63","source":"Kernel log","identifier":"Xid 63: row-remapping recording event (Ampere+) or `XID 63 Dynamic Page Retirement: New retired page, reload the driver to activate.` (earlier GPUs)","detection":"any occurrence","strength":"definitive","ref":"https://docs.nvidia.com/deploy/dynamic-page-retirement/visibility.html"},{"name":"DCGM memory health: pending retirement","source":"DCGM","identifier":"failure condition DCGM_FR_PENDING_PAGE_RETIREMENTS","detection":"any report","strength":"definitive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/feature-overview.html"}],"confounders":[{"failure":"gpu.memory_repair_exhausted","how_to_distinguish":"Row remap failure flag set or Xid 64: no repair is pending, it failed."},{"failure":"Persistence-mode InfoROM race (Volta and earlier)","how_to_distinguish":"Xid 48 seen without Xid 63: the retirement may not have been written. NVIDIA's caveat: run `nvidia-smi -i \u003cgpu> -pm 0` to flush, then Xid 63 should appear."}],"diagnosis":"The pending flags are definitive: the GPU itself reports a recorded repair waiting for a reset. Nothing is wrong with the running work. The remapped-row count counts InfoROM entries, not rows remapped in hardware, so read the flags, not the count, to decide whether a reset is due.","fixes":[{"fix":"cordon_node","when":"When the flag is seen, so the GPU drains naturally.","order":1},{"fix":"gpu_reset","when":"Once the GPU and any required NVLink peers are idle (pre-Ampere: letting the GPU detach with persistence mode off also works).","order":2},{"fix":"run_active_diagnostic","when":"After the reset, before the hold is released.","order":3}],"human_role":"Cluster operator approves the GPU reset and, on Slurm, the release of the node's hold (`State=RESUME`); also acts if the flag stays set after the reset, or the failure flag appears.","verification":{"remeasure":"Pending flag 0 / Pending Page Blacklist No after the reset; failure flag 0.","post_repair_check":"`dcgmi diag -r 2 -i \u003cgpu ids>` on the reset GPUs passes, then the hold is released under cordon_node's rollback rule."},"escalation_steps":["Read `nvidia-smi -q -d ROW_REMAPPER` or `-d PAGE_RETIREMENT` before and after the reset.","If the flag stays set after a reset, check that no client held the GPU open (`sudo lsof /dev/nvidia*`, persistence daemon), then reboot.","Track the remap or retirement count against gpu.memory_repair_exhausted's thresholds."],"references":[{"title":"NVIDIA GPU memory error management: row remapping","url":"https://docs.nvidia.com/deploy/a100-gpu-mem-error-mgmt/row-remapping.html"},{"title":"NVIDIA GPU memory error management: error recovery and response flags","url":"https://docs.nvidia.com/deploy/a100-gpu-mem-error-mgmt/error-recovery-and-response-flags.html"},{"title":"NVIDIA GPU memory error management: dynamic page offlining","url":"https://docs.nvidia.com/deploy/a100-gpu-mem-error-mgmt/dynamic-page-offlining.html"},{"title":"NVIDIA dynamic page retirement: implementation","url":"https://docs.nvidia.com/deploy/dynamic-page-retirement/implementation.html"},{"title":"NVIDIA dynamic page retirement: blacklisting and ECC error recovery","url":"https://docs.nvidia.com/deploy/dynamic-page-retirement/blacklisting-and-ecc-error-recovery.html"},{"title":"NVIDIA dynamic page retirement: caveats","url":"https://docs.nvidia.com/deploy/dynamic-page-retirement/caveats.html"},{"title":"DCGM dcgm_fields.h: the legacy names dcgm-exporter uses are aliases of the renamed fields, with their field ids","url":"https://github.com/NVIDIA/DCGM/blob/master/dcgmlib/dcgm_fields.h"}]},{"id":"gpu.memory_repair_exhausted","domain":"gpu","name":"Memory repair failed or exhausted (row remap failure, Xid 64, retirement thresholds)","summary":"The GPU can no longer repair its memory: a row-remapping failure (a bank already at eight uncorrectable remaps, a row remapped twice, or 512 remaps in total), a failure to record the repair (Xid 64), no repair resources left (Xid 157), or on pre-Ampere GPUs a retired-page count at the RMA threshold. Further errors in that memory will keep crashing jobs.","job_effect":["crash","capacity_loss"],"blast_radius":"gpu","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Row remap failure flag","source":"DCGM","identifier":"DCGM_FI_DEV_ROW_REMAP_FAILURE (dcgm-exporter default CSV name; field 395, DCGM_FI_DEV_ROW_REMAP_FAILED on the current field-ID page); `nvidia-smi -q -d ROW_REMAPPER` failure boolean","detection":"value 1; the RMA criterion once the field diagnostic validates it","strength":"definitive","ref":"https://docs.nvidia.com/deploy/a100-gpu-mem-error-mgmt/rma-policy-thresholds-for-row-remapping.html"},{"name":"Xid 64, remap or retirement recording failure","source":"Kernel log","identifier":"Xid 64 (GPU memory remapping failure; on earlier GPUs `Dynamic Page Retirement: Fatal error, unable to retire page`)","detection":"any occurrence (bucket RESET_GPU, then CONTACT_SUPPORT)","strength":"definitive","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"name":"Banks with no spare rows","source":"DCGM","identifier":"DCGM_FI_DEV_BANK_REMAP_AVAIL_NONE (field 389: historical marker of memory banks with no available spare memory rows)","detection":"> 0 is a warning sign; NVIDIA states no threshold for it","strength":"strong","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"name":"DCGM memory health: remap failure or retirement limits","source":"DCGM","identifier":"failure conditions DCGM_FR_ROW_REMAP_FAILURE (Xid 64), DCGM_FR_RETIRED_PAGES_LIMIT (63 or more retired pages), DCGM_FR_RETIRED_PAGES_DBE_LIMIT (more than 15 DBE retirements and at least one in the last week)","detection":"any report","strength":"definitive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/feature-overview.html"},{"name":"Retired pages at the RMA threshold (Volta and earlier)","source":"NVML / nvidia-smi","identifier":"`nvidia-smi -q -d PAGE_RETIREMENT` Single Bit ECC + Double Bit ECC; DCGM_FI_DEV_RETIRED_SBE / DCGM_FI_DEV_RETIRED_DBE (exporter names; DCGM_FI_DEV_PAGE_RETIRED_SBE_TOTAL / _DBE_TOTAL on the current field-ID page)","detection":"60 or more retired pages (RMA-eligible; 64 fails the field diagnostic), or 15 or more and still at least one new per week","strength":"definitive","ref":"https://docs.nvidia.com/deploy/dynamic-page-retirement/faq.html"},{"name":"Xid 157, resource retirement failure","source":"Kernel log","identifier":"Xid 157 (Hopper and later)","detection":"any occurrence: no repairs possible for lack of resources","strength":"strong","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"name":"SRAM threshold exceeded","source":"NVML / nvidia-smi","identifier":"`nvidia-smi` sram_threshold_exceeded flag (more than 4 UCE unique-count events in an address bank for parity-protected SRAM, more than 2 for SECDED)","detection":"flag set: run the field diagnostic","strength":"definitive","ref":"https://docs.nvidia.com/deploy/a100-gpu-mem-error-mgmt/sram-uncorrectable-errors.html"}],"confounders":[{"failure":"gpu.memory_repair_pending","how_to_distinguish":"Pending flag set and failure flag 0: a reset finishes the repair."},{"failure":"Xid 48 without 63 in persistence mode","how_to_distinguish":"A recording race, not exhaustion: flush with `nvidia-smi -pm 0` and look for Xid 63."}],"diagnosis":"The failure flag, Xid 64, Xid 157 and the retirement thresholds are vendor-defined end states: no software action restores the memory. The RMA decision belongs to NVIDIA's field diagnostic, which validates the flag. On Blackwell, a third remap in a bank may instead trigger a channel repair (Xid 160, effective after a reboot), so check for Xid 160 before treating a Blackwell GPU as exhausted.","fixes":[{"fix":"cordon_node","when":"Immediately.","order":1},{"fix":"node_reboot","when":"Xid 64 on Ampere-class GPUs: the triage guide says reboot immediately; also applies a Blackwell channel repair.","order":2},{"fix":"run_active_diagnostic","when":"Field diagnostic (through the vendor) and `dcgmi diag -r 3 -i \u003cgpu ids>` on the GPU, with no job allocated it.","order":3},{"fix":"rma_replace_hardware","when":"The field diagnostic validates the flag or the threshold is met.","order":4}],"human_role":"Cluster operator approves the node reboot; vendor RMA through the system vendor; data-center technician replaces the GPU or board.","verification":{"remeasure":"Not applicable before the repair: the GPU stays out of service.","post_repair_check":"The replacement passes the field diagnostic and `dcgmi diag -r 3 -i \u003cgpu ids>` naming the replacement; failure flag 0, pending 0; inventory updated with the new serial and UUID."},"escalation_steps":["Record the failure flag, remapped-row counts and bank buckets (`nvidia-smi -q -d ROW_REMAPPER`), or the retired-page counts and their rate per week.","Collect the Xid history for the PCI address (48, 63, 64, 157, 160) and nvidia-bug-report.sh output.","Run the field diagnostic as the system vendor instructs; open the RMA if it validates.","Keep the node cordoned until the part is replaced and the post-repair check passes."],"references":[{"title":"NVIDIA GPU memory error management: RMA policy","url":"https://docs.nvidia.com/deploy/a100-gpu-mem-error-mgmt/rma-policy-thresholds-for-row-remapping.html"},{"title":"NVIDIA GPU memory error management: RAS repair","url":"https://docs.nvidia.com/deploy/a100-gpu-mem-error-mgmt/hbm-channel-repair.html"},{"title":"NVIDIA dynamic page retirement: FAQ (RMA eligibility)","url":"https://docs.nvidia.com/deploy/dynamic-page-retirement/faq.html"},{"title":"NVIDIA GPU debug guidelines: GPU node triage","url":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/gpu-node-triage.html"},{"title":"DCGM feature overview: health failure conditions","url":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/feature-overview.html"},{"title":"DCGM dcgm_fields.h: the legacy names dcgm-exporter uses are aliases of the renamed fields, with their field ids","url":"https://github.com/NVIDIA/DCGM/blob/master/dcgmlib/dcgm_fields.h"}]},{"id":"gpu.memory_degradation_trend","domain":"gpu","name":"GPU memory degrading (rising correctable errors, shrinking spare rows)","summary":"No failure yet, but the memory is wearing: a high single-bit error rate (Xid 92), correctable remaps accumulating, banks dropping into the low or no-spare buckets, SRAM correctable errors. The job sees nothing today; the GPU is the likeliest next uncorrectable error. No source reviewed for this map shows that memory degradation makes a GPU slower: a slow GPU with rising correctable errors is two findings until a matched test links them.","job_effect":["latent"],"blast_radius":"gpu","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Xid 92, high single-bit ECC error rate","source":"Kernel log","identifier":"Xid 92 (EXCESSIVE_SBE_INTERRUPTS)","detection":"any occurrence (bucket IGNORE, then CONTACT_SUPPORT; triage guide: run the field diagnostic)","strength":"strong","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"name":"Aggregate single-bit ECC count rising","source":"DCGM","identifier":"DCGM_FI_DEV_ECC_SBE_AGG_TOTAL (field 312, monotonically increasing)","detection":"rate over a fixed window; the threshold is site policy, NVIDIA gives no default","strength":"suggestive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"name":"Correctable remapped rows accumulating","source":"DCGM","identifier":"DCGM_FI_DEV_CORRECTABLE_REMAPPED_ROWS (dcgm-exporter name; field 394, DCGM_FI_DEV_ROW_REMAP_CORRECTABLE_TOTAL on the current field-ID page)","detection":"increase over a site-chosen window; site policy, no vendor threshold","strength":"suggestive","ref":"https://github.com/NVIDIA/dcgm-exporter/blob/main/etc/default-counters.csv"},{"name":"Banks in the low or partial spare-row buckets","source":"DCGM","identifier":"DCGM_FI_DEV_BANK_REMAP_AVAIL_LOW, DCGM_FI_DEV_BANK_REMAP_AVAIL_PARTIAL (bucketized bank counts; `nvidia-smi -q -d ROW_REMAPPER`)","detection":"any bank moving out of Max; site policy","strength":"suggestive","ref":"https://docs.nvidia.com/deploy/a100-gpu-mem-error-mgmt/user-visible-statistics.html"},{"name":"Retired pages growing (Volta and earlier)","source":"NVML / nvidia-smi","identifier":"`nvidia-smi -q -d PAGE_RETIREMENT`; `nvidia-smi --query-retired-pages=gpu_uuid,retired_pages.address,retired_pages.cause --format=csv`","detection":"15 or more retired pages with one or more new per week makes the board evaluable for RMA before 60","strength":"strong","ref":"https://docs.nvidia.com/deploy/dynamic-page-retirement/faq.html"},{"name":"SRAM single-bit errors","source":"DCGM","identifier":"DCGM_FI_DEV_ECC_SBE_AGG_SRM (SRAM single-bit aggregate)","detection":"rate; site policy","strength":"suggestive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"}],"confounders":[{"failure":"Counter carried from before the job or the GPU's previous host","how_to_distinguish":"Aggregate counts are lifetime counts: compare rates over a fixed window, not totals."}],"diagnosis":"These signals are a risk ranking, not a cause of anything the job saw. Rank GPUs by rate of new correctable errors, remaps and bank-bucket changes against their class; the field diagnostic decides whether one is failing. Only the pre-Ampere retirement rule (15 pages and one per week) is a vendor threshold.","fixes":[{"fix":"run_active_diagnostic","when":"On Xid 92, or a GPU in the top of its class's error-rate ranking: `dcgmi diag -r 3 -i \u003cgpu ids>` on that GPU once no job is allocated it and, through the vendor, the field diagnostic.","order":1},{"fix":"cordon_node","when":"The diagnostic fails or the vendor threshold is met.","order":2},{"fix":"rma_replace_hardware","when":"The field diagnostic qualifies it.","order":3}],"human_role":"Cluster operator reviews the ranking and schedules diagnostics; vendor RMA if qualified.","verification":{"remeasure":"Error rate back within its class's range after any repair; no Xid 92 over an observation window (length: Pending).","post_repair_check":"Field diagnostic and `dcgmi diag -r 3 -i \u003cgpu ids>` pass."},"escalation_steps":["Plot the GPU's correctable ECC, remap and bank-bucket history against its class.","Run `dcgmi diag -r 3 -i \u003cgpu ids>` on the GPU in a window when no job is allocated it.","Ask the system vendor for the field diagnostic if Xid 92 recurs or the pre-Ampere retirement rate rule is met."],"references":[{"title":"NVIDIA Xid catalogue","url":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"title":"NVIDIA GPU memory error management: user visible statistics","url":"https://docs.nvidia.com/deploy/a100-gpu-mem-error-mgmt/user-visible-statistics.html"},{"title":"NVIDIA dynamic page retirement: FAQ","url":"https://docs.nvidia.com/deploy/dynamic-page-retirement/faq.html"},{"title":"DCGM field identifiers","url":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"title":"DCGM dcgm_fields.h: the legacy names dcgm-exporter uses are aliases of the renamed fields, with their field ids","url":"https://github.com/NVIDIA/DCGM/blob/master/dcgmlib/dcgm_fields.h"}]},{"id":"gpu.inaccessible_fallen_off_bus","domain":"gpu","name":"GPU inaccessible: fallen off the bus or failed to initialize (Xid 79, Xid 143)","summary":"The driver can no longer reach the GPU over PCIe (Xid 79), or the GPU fails to initialize (Xid 143, Hopper and later). Every process on it fails; the job crashes or hangs in a collective; the node runs with one GPU fewer until a reboot, and often until a repair.","job_effect":["crash","hang","capacity_loss"],"blast_radius":"gpu","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Xid 79, GPU has fallen off the bus","source":"Kernel log","identifier":"`NVRM: Xid (PCI:\u003cbdf>): 79, ...`","detection":"any occurrence (bucket RESTART_BM, then CONTACT_SUPPORT)","strength":"definitive","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"name":"DCGM health: fallen off the bus","source":"DCGM","identifier":"failure condition DCGM_FR_FALLEN_OFF_BUS","detection":"any report","strength":"definitive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/feature-overview.html"},{"name":"Xid 143, GPU initialization error","source":"Kernel log","identifier":"Xid 143 (H100, B100, GB200)","detection":"any occurrence (bucket RESET_GPU, then CONTACT_SUPPORT)","strength":"definitive","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"name":"GPU count below inventory","source":"Inventory","identifier":"`nvidia-smi -L` line count versus the node's inventoried GPU count","detection":"fewer GPUs than inventory, at boot or in a prolog","strength":"definitive","ref":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/best-practices.html"},{"name":"NVML reads report the GPU as lost","source":"Artemis analysis, algorithm pending","identifier":"NVML read errors for the rank's GPU, classed as lost","detection":"Any such read error","strength":"Pending"},{"name":"PCIe errors in kernel and BMC logs","source":"Kernel log","identifier":"kernel PCI error-reporting lines for the GPU's address or its upstream bridge; BMC SEL critical-interrupt events (`ipmitool sel list`)","detection":"around the Xid 79 time; NVIDIA says these may show the link failure's source","strength":"suggestive","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"}],"confounders":[{"failure":"host.bmc_psu_fan_sensor_fault","how_to_distinguish":"A power event (PSU fault in the SEL, Xid 54 auxiliary power not connected) at the same time points at power, not the GPU."},{"failure":"gpu.gsp_microcontroller_fault","how_to_distinguish":"Xid 119/120 before the GPU disappears suggests firmware or driver; NVIDIA's Xid catalog says Xid 79 may also come from driver issues."},{"failure":"fabric.pcie_link_degraded","how_to_distinguish":"A link that stays up but trains below its generation or width is a slowdown, not a loss; Meta found PCIe errors co-occur with Xid 79 often, so check both."},{"failure":"fabric.pcie_aer_errors","how_to_distinguish":"Fatal or uncorrectable AER on the GPU's link or its root port before the Xid 79 points at the link (riser, slot, cable); a clean AER history points at the GPU. Boundary: the lost GPU is tracked here; the link's error history in fabric.pcie_aer_errors."}],"diagnosis":"Xid 79 or Xid 143, or a GPU missing from enumeration, confirms the GPU is gone; it does not say why. A single occurrence that a reboot clears and diagnostics pass is a transient; a repeat on the same slot points at the GPU, riser or slot, and SEL power events or PCIe errors at the upstream bridge narrow it.","fixes":[{"fix":"cordon_node","when":"Immediately, before any restart (NVIDIA's node triage for Xid 79 starts by draining the node).","order":1},{"fix":"restart_from_checkpoint","when":"The job crashed or was failed by its NCCL timeout; restart it once the node is cordoned.","order":2},{"fix":"node_reboot","when":"Once idle (RESTART_BM); for Xid 143 try gpu_reset first if the GPU is still enumerated.","order":3},{"fix":"run_active_diagnostic","when":"After the reboot: GPU count, `dcgmi diag -r 3 -i \u003cnode gpu ids>`.","order":4},{"fix":"reseat_or_replace_cable","when":"It recurs on the same slot: check seating and power connections.","order":5},{"fix":"rma_replace_hardware","when":"It recurs after reseating, or the diagnostic fails.","order":6}],"human_role":"Cluster operator approves the node reboot; data-center technician (seating, riser, power), vendor RMA.","verification":{"remeasure":"After the reboot: the GPU count equals inventory and no Xid 79/143 over an observation window (length: Pending).","post_repair_check":"`dcgmi diag -r 3 -i \u003cnode gpu ids>` passes, including its PCIe test."},"escalation_steps":["Collect the Xid 79/143 line, the preceding kernel log (PCI error reporting, other Xids) and nvidia-bug-report.sh output.","Read the BMC SEL for power or critical-interrupt events at that time.","Check how often this slot has lost its GPU before (the same slot again suggests riser or slot).","Reseat the GPU and its power connections; if it recurs, RMA through the system vendor."],"references":[{"title":"NVIDIA Xid catalogue","url":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"title":"NVIDIA GPU debug guidelines: GPU node triage","url":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/gpu-node-triage.html"},{"title":"Kokolis et al., Revisiting Reliability in Large-Scale ML Research Clusters","url":"https://arxiv.org/html/2410.21680v2"}]},{"id":"gpu.gsp_microcontroller_fault","domain":"gpu","name":"GSP or on-GPU microcontroller fault or timeout (Xid 119, 120, 62, 158)","summary":"The GPU System Processor fails or stops answering the driver's RPCs (Xid 119/120), an internal microcontroller halts (Xid 62), or the GPU hits a fatal timeout (Xid 158). The job crashes or hangs; the GPU needs a reset, sometimes a power cycle. Fleet studies trace some of these to driver regressions rather than hardware.","job_effect":["crash","hang"],"blast_radius":"gpu","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Xid 119 GSP RPC timeout / Xid 120 GSP error","source":"Kernel log","identifier":"`NVRM: Xid (PCI:\u003cbdf>): 119, ...` or `120, ...`","detection":"any occurrence (bucket RESET_GPU, then INVESTIGATE_SW; a reset or node power cycle may be needed if it persists)","strength":"definitive","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"name":"Xid 62, internal micro-controller halt","source":"Kernel log","identifier":"Xid 62","detection":"any occurrence (RESET_GPU, then CONTACT_SUPPORT)","strength":"definitive","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"name":"Xid 158, GPU fatal timeout","source":"Kernel log","identifier":"Xid 158","detection":"any occurrence (RESET_GPU, then CONTACT_SUPPORT)","strength":"definitive","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"name":"Xid 154, recovery action changed","source":"Kernel log","identifier":"`Xid 154 GPU recovery action changed from 0x0 (None) to ...` (None, Drain P2P, Drain and Reset, GPU Reset Required, Node Reboot Required)","detection":"the required action for the accompanying Xid. Xid 154 is informational and names the recovery step, not the fault; the accompanying Xid (119, 120, 62, 158) decides this entry.","strength":"suggestive","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"name":"Driver version on the affected nodes","source":"Inventory","identifier":"DCGM_FI_DRIVER_VERSION label (dcgm-exporter; field 1, DCGM_FI_SYSTEM_DRIVER_VERSION on the current field-ID page); `nvidia-smi -q -d GSP_FIRMWARE_VERSION`","detection":"the same Xid on many nodes sharing one driver version","strength":"suggestive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"name":"Hang finding: ranks stopped making progress","source":"Artemis analysis, algorithm pending","identifier":"The ranks behind, and the collective and phase they are in. Mechanism and interval: Pending","detection":"No progress from any rank. Interval: Pending","strength":"Pending"}],"confounders":[{"failure":"gpu.firmware_driver_drift","how_to_distinguish":"Many nodes with the same driver version and the same Xid after a driver change points at the driver; one GPU repeating it after a power cycle points at the GPU."},{"failure":"gpu.inaccessible_fallen_off_bus","how_to_distinguish":"Xid 79 or a missing GPU after the GSP error: the GPU has gone, not just its firmware."}],"diagnosis":"The Xid confirms a firmware-level fault on that GPU; it does not separate a hardware fault from a driver bug, and NVIDIA's Xid catalog sends 119/120 to software investigation. Rank the hypotheses by spread: one GPU that repeats after a power cycle (follow the GPU debug guidelines), or many GPUs on one driver version (driver regression).","fixes":[{"fix":"cordon_node","when":"Immediately, before any restart.","order":1},{"fix":"restart_from_checkpoint","when":"The job crashed or its NCCL timeout fired; restart it once the node is cordoned.","order":2},{"fix":"gpu_reset","when":"Once idle, as the recovery action or bucket says.","order":3},{"fix":"node_reboot","when":"The reset fails or the error persists: power cycle.","order":4},{"fix":"rollback_software_change","when":"The pattern follows a driver version across nodes.","order":5},{"fix":"schedule_firmware_update","when":"NVIDIA or the system vendor names a fixed driver or firmware.","order":5}],"human_role":"Cluster operator approves the GPU reset or node reboot; platform team approves a driver rollback or update; NVIDIA support when one GPU repeats after a power cycle.","verification":{"remeasure":"No Xid 119/120/62/158 on the GPU after the reset, or on the fleet after a driver change, over an observation window (length: Pending); restarted jobs' throughput within 2% of their healthy value.","post_repair_check":"`dcgmi diag -r 2 -i \u003cgpu ids>` on the reset GPU (after a power cycle, `-i \u003cnode gpu ids>`) passes."},"escalation_steps":["Collect the Xid lines with the GPU's PCI address and nvidia-bug-report.sh output.","List which nodes and driver versions show the same Xid over a recent window (length: Pending).","If one GPU repeats it after a power cycle, follow NVIDIA's GPU debug guidelines and open a support case.","If it follows a driver version, ask the platform team to roll back or update."],"references":[{"title":"NVIDIA Xid catalogue","url":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"title":"Kokolis et al., Revisiting Reliability in Large-Scale ML Research Clusters","url":"https://arxiv.org/html/2410.21680v2"},{"title":"Cui et al., NCSA Delta GPU resilience study","url":"https://arxiv.org/html/2503.11901v4"},{"title":"DCGM dcgm_fields.h: the legacy names dcgm-exporter uses are aliases of the renamed fields, with their field ids","url":"https://github.com/NVIDIA/DCGM/blob/master/dcgmlib/dcgm_fields.h"}]},{"id":"gpu.mmu_illegal_address_fault","domain":"gpu","name":"GPU memory page fault or engine exception (Xid 31, Xid 13), usually the application","summary":"The GPU's MMU reports an illegal address access (Xid 31) or the graphics engine an exception (Xid 13: out-of-bounds access, illegal instruction or register). The process is killed and the job crashes. NVIDIA says these are typically application bugs, sometimes driver or hardware; the GPU itself stays usable.","job_effect":["crash"],"blast_radius":"job","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Xid 31, GPU memory page fault","source":"Kernel log","identifier":"`NVRM: Xid (PCI:\u003cbdf>): 31, pid=\u003cpid>, ...`","detection":"any occurrence; Xid catalog workflow: repeated faults on the same GPU (by PCI id) suggest hardware, faults on different GPUs the application","strength":"strong","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"name":"Xid 13, graphics engine exception","source":"Kernel log","identifier":"Xid 13 with its TPC/GPC/SM location","detection":"same TPC and GPC repeating suggests hardware; solo, or not repeating, suggests the application","strength":"strong","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"name":"Xid 43, GPU stopped processing","source":"Kernel log","identifier":"Xid 43","detection":"follows a software-induced fault; the GPU remains healthy (bucket IGNORE)","strength":"suggestive","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"name":"The job's CUDA error","source":"Job telemetry","identifier":"the framework's exception at the failing rank (exact text varies by CUDA and framework version; not verified here)","detection":"an illegal-address or launch error at the same time as the Xid","strength":"suggestive","ref":"https://docs.nvidia.com/deploy/xid-errors/working-with-xid-errors.html"}],"confounders":[{"failure":"gpu.ecc_uncorrectable_contained","how_to_distinguish":"Xid 48/94 or an ECC increase with the fault: memory hardware, not the application."},{"failure":"Hardware fault surfacing as MMU errors","how_to_distinguish":"NCSA Delta found A100 PMU SPI errors led to MMU errors 88% of the time; a preceding PMU or GSP Xid on the same GPU points at hardware."}],"diagnosis":"The Xid confirms a fault on that GPU at that time and names the pid; the cause is decided by pattern. The same code failing on different GPUs is the application (job owner debugs with Compute Sanitizer memcheck or cuda-gdb). The same GPU failing for different code, or the same TPC/GPC repeating, is hardware: run DCGM's diagnostics, then the field diagnostic.","fixes":[{"fix":"restart_from_checkpoint","when":"First occurrence: restart. Stop restarting if the same fault repeats on different nodes (deterministic in the code).","order":1},{"fix":"cordon_node","when":"It repeats on the same GPU.","order":2},{"fix":"run_active_diagnostic","when":"Repeats on the same GPU: `dcgmi diag -r 3 -i \u003cgpu ids>` on that GPU, with no job allocated it, then the field diagnostic.","order":3},{"fix":"rma_replace_hardware","when":"The diagnostics fail.","order":4}],"human_role":"Job owner debugs the application (usual case); data-center technician and vendor RMA when diagnostics implicate the GPU.","verification":{"remeasure":"The restarted job runs past the step that failed without a new Xid 13/31.","post_repair_check":"For a hardware path, `dcgmi diag -r 3 -i \u003cgpu ids>` and the field diagnostic pass."},"escalation_steps":["Match the Xid's pid to the job's rank and collect the job's traceback.","Check whether the same fault happened on other GPUs (application) or other jobs on this GPU (hardware).","Application: hand the job owner the Xid lines; NVIDIA recommends Compute Sanitizer memcheck, cuda-gdb, or CUDA_DEVICE_WAITS_ON_EXCEPTION=1.","Hardware: run DCGM diagnostics and the field diagnostic; file a bug with nvidia-bug-report.sh if inconclusive."],"references":[{"title":"NVIDIA Xid catalogue (WORKFLOW_XID_13, WORKFLOW_XID_31)","url":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"title":"NVIDIA: working with Xid errors","url":"https://docs.nvidia.com/deploy/xid-errors/working-with-xid-errors.html"},{"title":"Cui et al., NCSA Delta GPU resilience study","url":"https://arxiv.org/html/2503.11901v4"}]},{"id":"gpu.thermal_power_throttling","domain":"gpu","name":"GPU thermal or power throttling","summary":"The GPU lowers its clocks because it is too hot (software or hardware thermal slowdown), at its power cap, or under an external power brake from the system. The rank runs slower than its peers and the whole synchronous job waits for it: a straggler. Hardware slowdown cuts core clocks by a factor of 2 or more.","job_effect":["slowdown"],"blast_radius":"gpu","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Clock event reasons","source":"DCGM","identifier":"DCGM_FI_DEV_CLOCKS_EVENT_REASONS (field 112; bitmask of DCGM_CLOCKS_EVENT_REASON_*; DCGM_FI_DEV_CLOCK_THROTTLE_REASONS is its deprecated name)","detection":"thermal, power-cap or power-brake bit set in a meaningful share of samples while the GPU is busy; the share is site policy","strength":"strong","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"name":"Time spent in each slowdown","source":"DCGM","identifier":"DCGM_FI_DEV_CLOCKS_EVENT_REASON_HW_THERM_SLOWDOWN_NS (1423), _HW_POWER_BRAKE_SLOWDOWN_NS (1424), _SW_THERM_SLOWDOWN_NS, _SW_POWER_CAP_NS (ns, current field-ID page); `nvidia-smi --query-gpu=clocks_event_reasons_counters.{sw_power_cap,sw_thermal_slowdown,sync_boost,hw_thermal_slowdown,hw_power_brake_slowdown}`","detection":"increase over the window, compared with the GPU's class peers","strength":"strong","ref":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"},{"name":"Violation counters","source":"DCGM","identifier":"DCGM_FI_DEV_THERMAL_VIOLATION (241), DCGM_FI_DEV_POWER_VIOLATION (240): ns per the field-ID page (DCGM's header marks them deprecated; units are not pinned in the exporter)","detection":"rate > 0 while busy","strength":"strong","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"name":"Temperature against its slowdown threshold","source":"DCGM","identifier":"DCGM_FI_DEV_GPU_TEMP and DCGM_FI_DEV_MEMORY_TEMP (dcgm-exporter names; fields 150 and 140, DCGM_FI_DEV_GPU_TEMP_CELSIUS / DCGM_FI_DEV_MEMORY_TEMP_CELSIUS on the current page) versus DCGM_FI_DEV_GPU_TEMP_SLOWDOWN_CELSIUS (158)","detection":"within a few degrees of slowdown, or hotter than class peers in the same chassis; margin is site policy","strength":"suggestive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"name":"DCGM thermal and power health watches","source":"DCGM","identifier":"`dcgmi health -s t`; failure conditions DCGM_FR_CLOCKS_EVENT_THERMAL, DCGM_FR_THERMAL_VIOLATIONS, DCGM_FR_CLOCKS_EVENT_POWER","detection":"violation in the last minute","strength":"strong","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/feature-overview.html"},{"name":"Likely cause for a flagged rank","source":"Artemis analysis, algorithm pending","identifier":"Thermal, power or hardware-slowdown hypothesis from throttle reasons, temperature and power against peers. Thresholds: Pending","detection":"On a rank flagged slow","strength":"Pending"}],"confounders":[{"failure":"host.node_thermal_power_capping","how_to_distinguish":"Several GPUs or nodes in one rack throttling together, high inlet temperature, or the HW power brake bit (asserted by the system, for example its power supply) point at the node or facility."},{"failure":"gpu.ecc_mig_mode_misconfiguration","how_to_distinguish":"A power limit below its peers' is a configuration, not a fault."},{"failure":"Time-of-day temperature","how_to_distinguish":"Llama 3 saw a diurnal 1-2% throughput variation from mid-day temperatures: fleet-wide and periodic, not one GPU."}],"diagnosis":"Throttle-reason bits and slowdown counters confirm that the GPU slowed and why (thermal, power cap, power brake); they are definitive for the clocks, strong for the job's slowdown once that GPU is the slow rank. Whether the cause is the GPU (thermal interface, sensor), the node (fans, inlet air, PSU brake) or configuration (a lowered cap) needs the confounders' checks.","fixes":[{"fix":"rebalance_work","when":"The job opted in: shift work off the throttled rank while the cause is found.","order":1},{"fix":"power_thermal_mitigation","when":"Restore a lowered power limit or raise cooling; facilities for inlet air.","order":2},{"fix":"cordon_node","when":"Hardware thermal slowdown persists on one GPU across jobs.","order":3},{"fix":"rma_replace_hardware","when":"One GPU runs hotter than its neighbours under the same airflow (thermal interface or sensor).","order":4}],"human_role":"Data-center technician or facilities (cooling, airflow, thermal interface); platform team for power-limit policy.","verification":{"remeasure":"Throttle bits clear and slowdown counters flat over an observation window (length: Pending) while busy; the rank's step time within its class peers; job throughput within 2% of its healthy value.","post_repair_check":"`dcgmi diag -r 3 -i \u003cgpu ids>` (targeted power and stress tests) passes without thermal violations."},"escalation_steps":["Compare the GPU's temperature, clocks and throttle reasons with its neighbours in the same chassis under the same load.","Check fan speeds, inlet temperature and PSU events on the BMC.","Check the power limit against the fleet default.","If one GPU is hotter under identical airflow, schedule a thermal-interface inspection or RMA."],"references":[{"title":"nvidia-smi documentation (clocks event reasons)","url":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"},{"title":"DCGM field identifiers","url":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"title":"NVIDIA GPU debug guidelines: best practices (key metrics, inlet temperature)","url":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/best-practices.html"},{"title":"DCGM dcgm_fields.h: the legacy names dcgm-exporter uses are aliases of the renamed fields, with their field ids","url":"https://github.com/NVIDIA/DCGM/blob/master/dcgmlib/dcgm_fields.h"},{"title":"The Llama 3 Herd of Models, section 3.3.4","url":"https://arxiv.org/html/2407.21783v3"}]},{"id":"gpu.persistent_slow_gpu","domain":"gpu","name":"Persistently slow GPU with no hard error (straggler)","summary":"One GPU runs the same work measurably slower than its class peers, run after run, with no Xid: low clocks without a throttle reason (locked or application clocks), a link below its generation or width, or slower silicon. In a synchronous job every step waits for it.","job_effect":["slowdown"],"blast_radius":"gpu","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Slow-rank finding","source":"Artemis analysis, algorithm pending","identifier":"A rank slow against its island peers. Scoring inputs: Pending","detection":"Pending","strength":"Pending"},{"name":"Matched probe on the idle GPU","source":"Artemis analysis, algorithm pending","identifier":"Matched probe on the idle GPU, against its class's history. Workload: Pending","detection":"Below its class. Threshold: Pending","strength":"Pending"},{"name":"SM clock against its maximum, no throttle reason","source":"DCGM","identifier":"DCGM_FI_DEV_SM_CLOCK / DCGM_FI_DEV_MAX_SM_CLOCK, with DCGM_FI_DEV_CLOCKS_EVENT_REASONS showing no thermal or power reason; application clocks DCGM_FI_DEV_APP_SM_CLOCK","detection":"Below peers' fraction of max while busy. Threshold: Pending","strength":"suggestive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"name":"GPU PCIe link below its maximum under load","source":"DCGM","identifier":"DCGM_FI_DEV_PCIE_LINK_WIDTH/GEN against _MAX_, while the GPU is loaded. Threshold: Pending","detection":"Below maximum while loaded","strength":"suggestive"},{"name":"Locked clocks or lower power limit than peers","source":"NVML / nvidia-smi","identifier":"Per-rank power limit and locked-clock setting. Locked-clock source: Pending","detection":"lower than the peers' median","strength":"strong"}],"confounders":[{"failure":"gpu.thermal_power_throttling","how_to_distinguish":"Throttle-reason bits or violation counters active on the slow GPU."},{"failure":"host.cpu_memory_contention","how_to_distinguish":"The slow rank's GPU is idle a large share of the window and its host CPU, cgroup or memory pressure is high."},{"failure":"fabric.pcie_link_degraded","how_to_distinguish":"The rank's compute time is normal but its collectives are slow, or link error counters rise. A link read under load below its maximum width or generation makes it fabric.pcie_link_degraded; rising NVLink or NIC counters point at fabric.nvlink_link_errors or fabric.ib_roce_physical_errors."},{"failure":"job.dataloader_stall","how_to_distinguish":"High loader wait on the slow rank with normal GPU clocks."},{"failure":"False flag from peer comparison","how_to_distinguish":"A peer comparison can flag a healthy GPU that is only slightly slower: confirm with a matched probe before acting on hardware."},{"failure":"job.straggler_healthy_hardware","how_to_distinguish":"Boundary: this entry is the GPU itself, confirmed when a matched probe on the idle GPU reproduces the gap against its class. A GPU that passes the probe and matches its peers' telemetry, or a slow rank that moves between steps or follows the job to other nodes, is job.straggler_healthy_hardware."},{"failure":"fabric.slow_island_or_bridge_link","how_to_distinguish":"An island or bridge-link finding with compute time flat names a path, not a GPU."}],"diagnosis":"A slow-rank finding localizes the delay to a rank; it is not a cause. Rank hypotheses by evidence: throttling (bits set), configuration (lower limit or locked clocks), link (below max), host (GPU idle, host pressure), and only then the GPU itself. A GPU is confirmed slow when a matched probe on the idle GPU, outside the job, reproduces the gap against its class; MegaScale's equivalent was the same host slower across experiments.","fixes":[{"fix":"rebalance_work","when":"The job opted in: mitigate while the GPU is checked.","order":1},{"fix":"run_active_diagnostic","when":"A matched probe or `dcgmi diag -r 3 -i \u003cgpu ids>` naming only that GPU, when no job is allocated it.","order":2},{"fix":"cordon_node","when":"The probe confirms the GPU slow, or an exclude_and_restart is about to move the job off it (its precondition).","order":3},{"fix":"exclude_and_restart","when":"The job did not opt in to rebalancing and the slowdown costs more than a restart.","order":4},{"fix":"rma_replace_hardware","when":"Confirmed slow with configuration, thermals and links ruled out.","order":5}],"human_role":"Cluster operator confirms with the matched probe; data-center technician or vendor RMA for the GPU.","verification":{"remeasure":"After the mitigation: job throughput (at least 3 samples within 2% of the healthy value). After the repair: the probe on the GPU within its class's range.","post_repair_check":"Matched probe and `dcgmi diag -r 3 -i \u003cgpu ids>` pass; the first job on the GPU shows no slow-rank finding."},"escalation_steps":["Check throttle reasons, power limit, locked or application clocks against the peers.","Check the GPU's PCIe generation and width under load, and NVLink and NIC counters.","Run the matched probe on the idle GPU and compare with its class.","If it is still slow with everything else ruled out, open a vendor ticket with the probe results."],"references":[{"title":"MegaScale: Scaling LLM training to more than 10,000 GPUs","url":"https://arxiv.org/html/2402.15627v1"},{"title":"The Llama 3 Herd of Models, section 3.3.4","url":"https://arxiv.org/html/2407.21783v3"}]},{"id":"gpu.silent_data_corruption","domain":"gpu","name":"Silent data corruption","summary":"The GPU computes wrong results without raising an error. The job keeps running; loss may spike, go NaN or drift, or nothing visible happens and a corrupted model or checkpoint is the result. No device counter reports it.","job_effect":["silent_corruption"],"blast_radius":"job","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Loss or gradient-norm anomaly","source":"Job telemetry","identifier":"the job's logged loss and global gradient norm per step","detection":"a spike or NaN/Inf not explained by data or learning rate; thresholds are the job owner's, no standard","strength":"suggestive","ref":"https://arxiv.org/html/2407.21783v3"},{"name":"Replicas disagree","source":"Job telemetry","identifier":"a checksum of parameters (or of reduced gradients) compared across data-parallel replicas that should be identical","detection":"any mismatch; no maintained tool implementing this was verified for this map","strength":"strong","ref":"https://arxiv.org/html/2407.21783v3"},{"name":"Deterministic replay differs","source":"Other","identifier":"the same batch and weights re-run on the suspect GPU and on another GPU of its class","detection":"results differ beyond the kernel's known nondeterminism","strength":"definitive","ref":"https://arxiv.org/html/2407.21783v3"},{"name":"DCGM diagnostics","source":"DCGM","identifier":"`dcgmi diag -r 3` or `-r 4` with `-i \u003cgpu ids>` (diagnostic, memory and memtest plugins)","detection":"a failure implicates the GPU; a pass does not rule SDC out","strength":"suggestive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/dcgm-diagnostics.html"}],"confounders":[{"failure":"job.nan_loss_spike_or_sdc","how_to_distinguish":"Reproduces on other GPUs from the same checkpoint and batch. Boundary: job.nan_loss_spike_or_sdc is the triage of a visible loss anomaly, numerical until shown otherwise; this entry is the hardware cause, confirmed only when deterministic recomputation of the same step on the suspect GPU disagrees with validated healthy GPUs that agree with each other. A failed thermal, memory, link or other diagnostic routes to the matching hardware entry, not here. SDC with no visible anomaly is only this entry."},{"failure":"gpu.ecc_mig_mode_misconfiguration","how_to_distinguish":"ECC disabled on the GPU means memory errors go undetected: check ECC mode first."},{"failure":"host.pcie_acs_iommu_misconfig","how_to_distinguish":"On a bare-metal node with the IOMMU in translated mode, P2P transfers can corrupt device memory silently (NCCL troubleshooting). That corruption follows the node's P2P paths, not one GPU, and stops with `NCCL_P2P_DISABLE=1`; read the kernel IOMMU mode before blaming the GPU."}],"diagnosis":"Anomalies in the job's numbers only correlate; SDC is confirmed only by reproducing a wrong result on the suspect GPU against a healthy one. Diagnostics passing does not clear the GPU.","fixes":[{"fix":"run_active_diagnostic","when":"A replica mismatch or unexplained anomaly localized to a GPU: replay and `dcgmi diag -r 4 -i \u003cgpu ids>` naming the suspect GPU, with no job allocated it.","order":1},{"fix":"cordon_node","when":"Replay reproduces the wrong result.","order":2},{"fix":"restart_from_checkpoint","when":"From a checkpoint the job owner chooses from before the onset, without the GPU.","order":3},{"fix":"rma_replace_hardware","when":"Confirmed by replay.","order":4}],"human_role":"Job owner (which checkpoint is trustworthy), cluster operator (replay on the GPU), vendor RMA.","verification":{"remeasure":"After the restart without the GPU: no replica mismatch and the loss curve matches the run before the onset.","post_repair_check":"The replacement GPU passes replay against a healthy GPU and `dcgmi diag -r 4 -i \u003cgpu ids>`."},"escalation_steps":["Find the first step whose numbers diverge and which ranks they came from.","Replay that step's batch on the suspect GPU and on a healthy GPU of the same class.","Check ECC mode and memory error counters on the suspect GPU.","Give the job owner the onset step so they can choose a clean checkpoint."],"references":[{"title":"The Llama 3 Herd of Models, section 3.3.4","url":"https://arxiv.org/html/2407.21783v3"},{"title":"DCGM diagnostics","url":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/dcgm-diagnostics.html"}]},{"id":"gpu.ecc_mig_mode_misconfiguration","domain":"gpu","name":"ECC, MIG or persistence mode differs from the fleet baseline","summary":"A GPU's ECC is off (or pending off), MIG is on where the fleet expects it off (or the reverse), or persistence mode differs. With ECC off no new memory errors are detected and no pages are retired; MIG on unexpectedly splits the GPU and a job may get a fraction of it; a pending mode changes at the next reboot.","job_effect":["latent","capacity_loss"],"blast_radius":"gpu","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"ECC mode current and pending","source":"DCGM","identifier":"DCGM_FI_DEV_ECC_MODE (field 300), DCGM_FI_DEV_ECC_PENDING (301); `nvidia-smi -q` Ecc Mode Current / Pending","detection":"differs from the fleet baseline for the class","strength":"definitive","ref":"https://docs.nvidia.com/deploy/dynamic-page-retirement/faq.html"},{"name":"MIG mode","source":"DCGM","identifier":"DCGM_FI_DEV_MIG_MODE (field 67; 0 disabled, 1 enabled)","detection":"differs from the baseline","strength":"definitive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"name":"Persistence mode","source":"DCGM","identifier":"DCGM_FI_DEV_GPU_PERSISTENCE_MODE","detection":"differs from the baseline (NVIDIA recommends the persistence daemon)","strength":"suggestive","ref":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/best-practices.html"},{"name":"Device configuration per rank","source":"Artemis analysis, algorithm pending","identifier":"ECC mode (current, pending), MIG mode and persistence mode per rank, and whether a setting changed","detection":"differs from peers, or changed during the job","strength":"Pending"},{"name":"MIG rank whose telemetry does not name its instance","source":"Artemis analysis, algorithm pending","identifier":"Telemetry for a MIG-enabled rank that does not name its MIG instance","detection":"Any such rank","strength":"Pending"}],"confounders":[{"failure":"Deliberate configuration","how_to_distinguish":"A partition or node pool configured for MIG on purpose: compare with the pool's baseline, not the fleet's."}],"diagnosis":"The mode readback is definitive for the configuration. Its effect is a hypothesis: ECC off raises the risk of undetected corruption but is not evidence of it; MIG explains a capacity shortfall only if the job expected a full GPU.","fixes":[{"fix":"cordon_node","when":"ECC off or MIG on against the baseline.","order":1},{"fix":"rollback_software_change","when":"Set the baseline: `nvidia-smi -i \u003cgpu> -e 1` (after the next reboot) or `nvidia-smi -i \u003cgpu> -mig 0`.","order":2},{"fix":"node_reboot","when":"An ECC change takes effect only after a reboot.","order":3},{"fix":"run_active_diagnostic","when":"After the change.","order":4}],"human_role":"Platform team owns the device-configuration baseline; cluster operator approves the node reboot.","verification":{"remeasure":"Readback equals the baseline (current and pending).","post_repair_check":"`dcgmi diag -r 1 -i \u003cgpu ids>` passes on the corrected GPUs; the first job's GPU memory and throughput match the class."},"escalation_steps":["Read ECC, MIG and persistence modes for every GPU on the node.","Find who changed them and when (settings-change records).","Ask the platform team whether the pool's baseline is the fleet's."],"references":[{"title":"NVIDIA dynamic page retirement: FAQ (ECC mode)","url":"https://docs.nvidia.com/deploy/dynamic-page-retirement/faq.html"},{"title":"nvidia-smi documentation (-e, -mig, -pm)","url":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"}]},{"id":"gpu.firmware_driver_drift","domain":"gpu","name":"GPU driver, VBIOS or firmware drift from the fleet baseline","summary":"A GPU's driver, CUDA driver, VBIOS, InfoROM or GSP firmware version differs from the baseline for its class. Jobs may run slower or hit bugs others don't; a bad driver rollout makes many nodes fail the same way.","job_effect":["latent","slowdown","crash"],"blast_radius":"node","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Driver version","source":"Inventory","identifier":"DCGM_FI_DRIVER_VERSION label (dcgm-exporter; field 1, DCGM_FI_SYSTEM_DRIVER_VERSION on the current page); DCGM_FI_CUDA_DRIVER_VERSION","detection":"differs from the baseline","strength":"definitive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"name":"VBIOS and InfoROM versions","source":"Inventory","identifier":"DCGM_FI_DEV_VBIOS_VERSION (field 85), DCGM_FI_DEV_INFOROM_IMAGE_VERSION (field 82); `nvidia-smi -q`","detection":"differs from the class baseline","strength":"definitive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"name":"GSP firmware version","source":"NVML / nvidia-smi","identifier":"`nvidia-smi -q -d GSP_FIRMWARE_VERSION`","detection":"differs from the baseline","strength":"definitive","ref":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"},{"name":"Driver differs from the slow rank's peers","source":"Artemis analysis, algorithm pending","identifier":"Per-rank driver version against peers, as a corroborating hypothesis","detection":"On a flagged rank. Rule: Pending","strength":"Pending"}],"confounders":[{"failure":"A canary or staged rollout","how_to_distinguish":"The node is in the rollout's canary set."},{"failure":"gpu.gsp_microcontroller_fault","how_to_distinguish":"GSP Xids on many nodes of one driver version: the drift's effect, ranked above hardware."},{"failure":"host.software_firmware_drift","how_to_distinguish":"Boundary: this entry covers the GPU's driver, CUDA driver, VBIOS, InfoROM and GSP firmware. Kernel, OS image, RDMA stack, BIOS, BMC firmware and job-image libraries are host.software_firmware_drift."}],"diagnosis":"Version readback against the baseline is definitive for the drift. A difference is not proof the version caused a symptom; the matched comparison is the same workload on drifted and baseline nodes of one class.","fixes":[{"fix":"cordon_node","when":"The version is known bad.","order":1},{"fix":"schedule_firmware_update","when":"Bring it to the baseline in a window.","order":2},{"fix":"rollback_software_change","when":"A recent driver rollout regressed the fleet.","order":3},{"fix":"run_active_diagnostic","when":"After the update.","order":4}],"human_role":"Platform team owns versions and rollouts.","verification":{"remeasure":"Versions read back as the baseline; a matched benchmark on the node within its class.","post_repair_check":"`dcgmi diag -r 2 -i \u003cnode gpu ids>` passes."},"escalation_steps":["List every version that differs from the class baseline on the node.","Check whether symptoms (Xids, slow-rank findings) cluster by version across the fleet.","Schedule the update with the platform team."],"references":[{"title":"DCGM field identifiers","url":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"title":"NVIDIA GPU debug guidelines: best practices (confirm VBIOS, driver)","url":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/best-practices.html"},{"title":"DCGM dcgm_fields.h: the legacy names dcgm-exporter uses are aliases of the renamed fields, with their field ids","url":"https://github.com/NVIDIA/DCGM/blob/master/dcgmlib/dcgm_fields.h"}]},{"id":"host.node_unresponsive","domain":"host","name":"Node unresponsive: kernel panic, lockup or hang; the scheduler marks it DOWN","summary":"The node's OS panics, locks up or stops answering. Every rank on it stops; the other ranks of the job hang in their next collective until a timeout fails the job; the scheduler marks the node DOWN (Slurm) after its timeout, and the node's capacity is lost until someone or something reboots it.","job_effect":["hang","crash","capacity_loss"],"blast_radius":"node","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Slurm node DOWN or not responding","source":"Scheduler","identifier":"`sinfo` / `scontrol show node \u003cnode>`: state DOWN, or a trailing `*` (not responding); Reason field","detection":"slurmd has not answered for SlurmdTimeout (default 300 s)","strength":"strong","ref":"https://slurm.schedmd.com/slurm.conf.html"},{"name":"BMC reachable, OS not","source":"BMC / Redfish / IPMI","identifier":"`ipmitool -H \u003cbmc> chassis power status` and `ipmitool -H \u003cbmc> sel list`","detection":"power on and the OS unreachable: an OS hang or panic, not a power loss","strength":"strong","ref":"https://linux.die.net/man/1/ipmitool"},{"name":"Soft or hard lockup reports","source":"Kernel log","identifier":"the kernel's softlockup and hardlockup (NMI watchdog) reports with stack trace; sysctl kernel.softlockup_panic makes a soft lockup panic","detection":"any report (a soft lockup is kernel-mode looping for more than 20 seconds)","strength":"strong","ref":"https://docs.kernel.org/admin-guide/lockup-watchdogs.html"},{"name":"Hung tasks","source":"node_exporter / OS","identifier":"node_kernel_hung_tasks_total (node_exporter kernel_hung collector)","detection":"any increase","strength":"suggestive","ref":"https://github.com/prometheus/node_exporter/blob/master/collector/kernel_hung_linux.go"},{"name":"Crash dump after reboot","source":"Kernel log","identifier":"a kdump vmcore saved for the crash","detection":"present: the node panicked","strength":"definitive","ref":"https://docs.kernel.org/admin-guide/kdump/kdump.html"},{"name":"Kubernetes NPD conditions","source":"Scheduler","identifier":"Node Problem Detector condition KernelDeadlock (system log monitor)","detection":"condition true","strength":"strong","ref":"https://github.com/kubernetes/node-problem-detector"},{"name":"Ranks stop reporting","source":"Artemis analysis, algorithm pending","identifier":"Hang finding naming ranks that stopped reporting, all on one host. Mechanism and interval: Pending","detection":"No progress and the silent ranks share a node. Interval: Pending","strength":"Pending"}],"confounders":[{"failure":"Front-end network partition","how_to_distinguish":"The node answers on its BMC console and its jobs still make progress over the back-end fabric; only slurmd's control path is cut."},{"failure":"gpu.inaccessible_fallen_off_bus","how_to_distinguish":"An Xid 79 or GSP Xid just before the hang: a GPU fault hung the job, not the OS."},{"failure":"host.local_disk_filesystem_failure","how_to_distinguish":"Processes stuck in D state on a filesystem (Meta lists drivers in D state under filesystem-mount failures); hung-task count rising while the kernel still answers."}],"diagnosis":"Scheduler DOWN plus a powered-on BMC with an unreachable OS is strong evidence of an OS hang or panic; a vmcore confirms a panic and holds its cause. Silent ranks all on one host localize a job hang to that host. A one-off with a clean reboot and passing checks is a transient; a node that repeats is a lemon node (Meta's term) and goes to repair.","fixes":[{"fix":"restart_from_checkpoint","when":"The job's processes are confirmed stopped (the node fenced through the BMC, or every step's exit reported); the scheduler failing the job after the node went DOWN is not enough, and without confirmation the restart needs approval. Restart it without the node.","order":1},{"fix":"node_reboot","when":"Only with an operator's approval: an unresponsive node cannot be shown to have stopped its work without fencing, and fencing is the power cycle itself (a hard-lockup report is per CPU and a SEL or console record is history, so neither shows the work stopped). Not on a node another owner holds. Power cycle through the BMC; keep the node DOWN until the post-repair check passes.","order":2},{"fix":"run_active_diagnostic","when":"After the reboot: node health check and `dcgmi diag -r 2 -i \u003cnode gpu ids>`.","order":3},{"fix":"rma_replace_hardware","when":"It recurs (a lemon node) or the crash dump implicates hardware.","order":4}],"human_role":"Cluster operator approves the power cycle and reads the crash dump and SEL; data-center technician for hardware.","verification":{"remeasure":"The node registers after the reboot and stays up over an observation window (length: Pending) with no lockup report and no hung-task increase.","post_repair_check":"Node health check (NHC) and `dcgmi diag -r 2 -i \u003cnode gpu ids>` pass, GPU count equals inventory, before the hold is released under cordon_node's rollback rule (`scontrol update NodeName=\u003cnode> State=RESUME`, once a person approves it, only if no other hold or open incident remains)."},"escalation_steps":["Read the BMC SEL and power status for the time the node stopped.","After the reboot, read the vmcore (kdump) or the last kernel log lines (lockups, Xids, machine checks).","Count how often this node has gone DOWN recently (window: Pending); a repeat is a lemon node.","Hand the crash signature to the vendor or kernel owner."],"references":[{"title":"Slurm slurm.conf (SlurmdTimeout, ReturnToService)","url":"https://slurm.schedmd.com/slurm.conf.html"},{"title":"Slurm sinfo (node states)","url":"https://slurm.schedmd.com/sinfo.html"},{"title":"Linux kernel: softlockup and hardlockup detectors","url":"https://docs.kernel.org/admin-guide/lockup-watchdogs.html"},{"title":"Linux kernel: kdump","url":"https://docs.kernel.org/admin-guide/kdump/kdump.html"},{"title":"Kokolis et al., Revisiting Reliability in Large-Scale ML Research Clusters","url":"https://arxiv.org/html/2410.21680v2"}]},{"id":"host.memory_ecc","domain":"host","name":"Host memory errors (EDAC correctable and uncorrectable)","summary":"The node's DRAM reports errors through its memory controllers. Correctable errors are latent warnings; an uncorrectable error can kill the process that touched it or bring the node down, depending on the platform. The training job crashes or its node fails.","job_effect":["crash","latent"],"blast_radius":"node","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"EDAC uncorrectable errors","source":"node_exporter / OS","identifier":"node_edac_uncorrectable_errors_total (per controller; also csrow and channel series) from /sys/devices/system/edac/mc/mc*/ue_count","detection":"any increase","strength":"definitive","ref":"https://github.com/prometheus/node_exporter/blob/master/collector/edac_linux.go"},{"name":"EDAC correctable errors","source":"node_exporter / OS","identifier":"node_edac_correctable_errors_total from /sys/devices/system/edac/mc/mc*/ce_count (dimm_ce_count per DIMM)","detection":"rate above site policy; no kernel default","strength":"suggestive","ref":"https://docs.kernel.org/admin-guide/RAS/main.html"},{"name":"BMC memory events","source":"BMC / Redfish / IPMI","identifier":"`ipmitool sel list` memory entries","detection":"any uncorrectable entry","strength":"strong","ref":"https://linux.die.net/man/1/ipmitool"}],"confounders":[{"failure":"Counter reset or carried over","how_to_distinguish":"EDAC counters can be zeroed through each controller's reset_counters file (seconds_since_reset says when); compare increases over a fixed window, not totals."}],"diagnosis":"An uncorrectable EDAC increase confirms a host memory fault on that controller (csrow, channel and DIMM narrow it). Correctable errors only rank DIMMs for replacement.","fixes":[{"fix":"cordon_node","when":"Any uncorrectable error, or correctable errors above the site's rate.","order":1},{"fix":"restart_from_checkpoint","when":"The job crashed.","order":2},{"fix":"run_active_diagnostic","when":"A memory test on the drained node.","order":3},{"fix":"rma_replace_hardware","when":"Replace the DIMM the counters name.","order":4}],"human_role":"Data-center technician replaces the DIMM.","verification":{"remeasure":"No EDAC increase over an observation window (length: Pending) after the replacement.","post_repair_check":"A memory test passes and the DIMM's counters stay at zero over a soak."},"escalation_steps":["Read the EDAC counts by controller, csrow, channel and DIMM.","Match them with BMC SEL memory events.","Replace the named DIMM and run a memory test before resuming."],"references":[{"title":"Linux kernel RAS and EDAC admin guide","url":"https://docs.kernel.org/admin-guide/RAS/main.html"},{"title":"node_exporter edac collector","url":"https://github.com/prometheus/node_exporter/blob/master/collector/edac_linux.go"}]},{"id":"host.cpu_memory_contention","domain":"host","name":"Host CPU or memory contention starving the rank","summary":"The rank's host side cannot keep its GPU fed: CPU throttled by a cgroup limit, other processes competing for cores, memory pressure and swapping, or threads running off the GPU's NUMA node. The GPU sits idle part of each step; the rank becomes a straggler.","job_effect":["slowdown"],"blast_radius":"node","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Node pressure (PSI)","source":"node_exporter / OS","identifier":"Rates of node_pressure_*_seconds_total (CPU waiting, memory waiting and stalled, I/O waiting and stalled). Window: Pending","detection":"elevated on the slow rank's node against peer nodes; threshold is site policy","strength":"suggestive"},{"name":"Rank's cgroup CPU throttling and run-queue wait","source":"Artemis analysis, algorithm pending","identifier":"Cgroup CPU throttling, run-queue wait and cgroup pressure (PSI) for CPU, memory and I/O","detection":"higher on the slow rank than its peers","strength":"Pending"},{"name":"Rank's CPU busy share against peers","source":"Artemis analysis, algorithm pending","identifier":"Per-rank CPU busy share","detection":"Near saturation on the slow rank, lower on peers. Threshold: Pending","strength":"Pending"},{"name":"NUMA misplacement","source":"Artemis analysis, algorithm pending","identifier":"Placement check: the training thread's NUMA node against its GPU's NUMA node","detection":"the training thread runs off its GPU's NUMA node","strength":"Pending"},{"name":"GPU idle while the rank is slow","source":"Artemis analysis, algorithm pending","identifier":"Likely cause: host, because the GPU looks like its peers","detection":"On a flagged rank. Rule: Pending","strength":"Pending"},{"name":"Other processes on the GPU","source":"Artemis analysis, algorithm pending","identifier":"Count of PIDs the driver lists on the GPU, less the job's own","detection":"Any other process","strength":"Pending"},{"name":"Kernel OOM killer","source":"Kernel log","identifier":"`Out of memory: Killed process \u003cpid> (\u003ccomm>) total-vm:...` (host memory exhausted) or `Memory cgroup out of memory: Killed process \u003cpid> (\u003ccomm>) ...` (a cgroup's limit, such as a Slurm job's), printed by the kernel's mm/oom_kill.c","detection":"A line on the rank's node during the slowdown or before a rank exits; naming a rank's process, it also explains the exit.","strength":"definitive","ref":"https://github.com/torvalds/linux/blob/master/mm/oom_kill.c"},{"name":"OOM kill count","source":"node_exporter / OS","identifier":"node_vmstat_oom_kill (vmstat collector; `oom_kill` is in its default field regex `^(oom_kill|pgpg|pswp|pg.*fault).*`; from /proc/vmstat)","detection":"increases on the rank's node during the slowdown","strength":"strong","ref":"https://github.com/prometheus/node_exporter/blob/master/collector/vmstat_linux.go"}],"confounders":[{"failure":"job.dataloader_stall","how_to_distinguish":"Loader wait high with io pressure but no CPU throttling: the input pipeline waits on storage, not CPU."},{"failure":"gpu.persistent_slow_gpu","how_to_distinguish":"The slow rank's GPU is busy, not idle, and its host values match its peers'."},{"failure":"job.straggler_healthy_hardware","how_to_distinguish":"Boundary: this entry is contention the node imposes on the rank (other processes, a cgroup CPU limit, NUMA misplacement) and stays with the node when the job moves. Imbalance in the job's own work (stages, sequence lengths, GC pauses) follows the job to any node: job.straggler_healthy_hardware."}],"diagnosis":"Host telemetry is context, not cause. A slow rank whose GPU idles while its own cgroup throttles or its CPU share saturates, with peers not, ranks host contention first; node-wide PSI corroborates but belongs to the node, not the run. Confirmation is a matched re-run with the contention removed (exclusive node, larger CPU limit, corrected binding).","fixes":[{"fix":"rebalance_work","when":"The job opted in: shift work while the contention is fixed.","order":1},{"fix":"rollback_software_change","when":"A recent change to CPU binding, cgroup limits or node sharing caused it: restore the job's previous allocation settings.","order":2},{"fix":"exclude_and_restart","when":"A co-tenant can't be moved: restart the job on an exclusive node.","order":3}],"human_role":"Job owner (CPU and memory request, binding); cluster operator (node sharing policy).","verification":{"remeasure":"The rank's throttled share and run-queue wait back to its peers' level, and the job's throughput within 2% of its healthy value over at least 3 samples.","post_repair_check":"Not hardware: the next run on the node shows no host-telemetry gap against peers."},"escalation_steps":["Compare the slow rank's cgroup throttling, run-queue wait, memory pressure and placement with its peers.","List other jobs and processes on the node and their CPU and memory use.","Check the job's CPU request and binding against its GPU's NUMA node."],"references":[{"title":"node_exporter pressure collector","url":"https://github.com/prometheus/node_exporter/blob/master/collector/pressure_linux.go"}]},{"id":"host.local_disk_filesystem_failure","domain":"host","name":"Local disk full, read-only or failing; expected mount missing","summary":"A local filesystem fills up, is remounted read-only after errors, or its disk fails SMART, or a filesystem the jobs expect is not mounted. Checkpoint or log writes fail and the job crashes, or processes stall in I/O and the job hangs; new jobs fail at start.","job_effect":["crash","hang","capacity_loss"],"blast_radius":"node","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Filesystem nearly full","source":"node_exporter / OS","identifier":"node_filesystem_avail_bytes / node_filesystem_size_bytes per mountpoint","detection":"below site policy; no default","strength":"strong","ref":"https://github.com/prometheus/node_exporter/blob/master/collector/filesystem_common.go"},{"name":"Filesystem read-only or erroring","source":"node_exporter / OS","identifier":"node_filesystem_readonly == 1 on a mount expected writable; node_filesystem_device_error == 1","detection":"any","strength":"definitive","ref":"https://github.com/prometheus/node_exporter/blob/master/collector/filesystem_common.go"},{"name":"NPD read-only filesystem","source":"Scheduler","identifier":"Node Problem Detector condition ReadonlyFilesystem","detection":"condition true","strength":"definitive","ref":"https://github.com/kubernetes/node-problem-detector"},{"name":"SMART health failing","source":"Storage","identifier":"`smartctl -H \u003cdevice>`","detection":"failing status: the device has failed or predicts failure within 24 hours","strength":"definitive","ref":"https://linux.die.net/man/8/smartctl"},{"name":"Expected mount missing","source":"node_exporter / OS","identifier":"the node health check's mount checks (NHC), or node_filesystem_size_bytes absent for an expected mountpoint","detection":"any expected mount absent","strength":"definitive","ref":"https://github.com/mej/nhc"}],"confounders":[{"failure":"job.storage_checkpoint_io","how_to_distinguish":"A network filesystem slow or down for many nodes at once is storage, not this node."}],"diagnosis":"The filesystem and SMART readings are definitive for the node's state. A job crash at a checkpoint write on that node, with the mount full or read-only, is explained by it.","fixes":[{"fix":"cordon_node","when":"Any of the signals.","order":1},{"fix":"restart_from_checkpoint","when":"The job crashed; restart elsewhere.","order":2},{"fix":"node_reboot","when":"A read-only remount after errors or a missing mount: reboot runs the filesystem checks and mounts again.","order":3},{"fix":"rma_replace_hardware","when":"SMART failing or errors recur: replace the disk.","order":4}],"human_role":"Cluster operator (approves the reboot; cleanup of a full disk); data-center technician (disk replacement).","verification":{"remeasure":"Free space above policy, mounts writable and present, no device errors over an observation window (length: Pending).","post_repair_check":"`smartctl -H` passes and the node health check passes before resuming."},"escalation_steps":["Find what filled the disk (job scratch, logs, core dumps) and who owns it.","For a read-only remount, read the kernel log's I/O and filesystem errors.","Run `smartctl -a` on the device; replace it if failing."],"references":[{"title":"node_exporter filesystem collector","url":"https://github.com/prometheus/node_exporter/blob/master/collector/filesystem_common.go"},{"title":"smartctl(8)","url":"https://linux.die.net/man/8/smartctl"},{"title":"Slurm slurm.conf (HealthCheckProgram draining example)","url":"https://slurm.schedmd.com/slurm.conf.html"}]},{"id":"host.bmc_psu_fan_sensor_fault","domain":"host","name":"PSU, fan or BMC sensor fault","summary":"A power supply fails or loses redundancy, a fan fails, or a sensor reads out of range. The node may keep running on its remaining supplies, throttle its GPUs (power brake, thermal slowdown), or shut down. A GPU's auxiliary power not connected (Xid 54) belongs here too.","job_effect":["slowdown","crash","latent"],"blast_radius":"node","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"BMC event log","source":"BMC / Redfish / IPMI","identifier":"`ipmitool sel list` power-supply, fan and temperature entries","detection":"any new entry of those types","strength":"strong","ref":"https://linux.die.net/man/1/ipmitool"},{"name":"BMC sensors","source":"BMC / Redfish / IPMI","identifier":"`ipmitool sensor` readings and threshold states (sensor names are vendor-specific)","detection":"a sensor outside its thresholds","strength":"strong","ref":"https://linux.die.net/man/1/ipmitool"},{"name":"Host fan and temperature sensors","source":"node_exporter / OS","identifier":"node_hwmon_fan_rpm, node_hwmon_temp_celsius and their _alarm/_fault series (the collector builds node_hwmon_\u003csensor type>_\u003cunit>; master source, unpinned)","detection":"a fan at 0 rpm or an alarm set","strength":"strong","ref":"https://github.com/prometheus/node_exporter/blob/master/collector/hwmon_linux.go"},{"name":"GPU power brake","source":"DCGM","identifier":"DCGM_FI_DEV_CLOCKS_EVENT_REASON_HW_POWER_BRAKE_SLOWDOWN_NS (field 1424); nvidia-smi HW Power Brake (external power brake assertion, for example by the system power supply)","detection":"any increase on several GPUs of the node","strength":"strong","ref":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"},{"name":"Xid 54, auxiliary power not connected","source":"Kernel log","identifier":"Xid 54","detection":"any occurrence (bucket CHECK_MECHANICALS)","strength":"definitive","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"}],"confounders":[{"failure":"host.node_thermal_power_capping","how_to_distinguish":"Rack- or facility-wide inlet temperature or power capping, not one node's PSU or fan."}],"diagnosis":"SEL and sensor entries confirm the component state; a power brake on all of a node's GPUs at the same time as a PSU event links the job's slowdown to it.","fixes":[{"fix":"cordon_node","when":"Lost PSU redundancy, a failed fan, or a GPU power brake.","order":1},{"fix":"power_thermal_mitigation","when":"Cap GPU power until the part is replaced, if the node must keep running.","order":2},{"fix":"reseat_or_replace_cable","when":"Xid 54 or a PSU cable fault.","order":3},{"fix":"rma_replace_hardware","when":"A failed PSU or fan.","order":3}],"human_role":"Data-center technician.","verification":{"remeasure":"No new SEL entries and all sensors in range over an observation window (length: Pending); power-brake counters flat.","post_repair_check":"`dcgmi diag -r 3 -i \u003cnode gpu ids>` (targeted power) passes without power-brake or thermal violations."},"escalation_steps":["Read the SEL and sensor list.","Identify the PSU or fan by its sensor name and slot.","Replace or reseat it, then run the targeted-power diagnostic."],"references":[{"title":"ipmitool(1)","url":"https://linux.die.net/man/1/ipmitool"},{"title":"NVIDIA GPU debug guidelines: best practices (power, fan and inlet metrics)","url":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/best-practices.html"},{"title":"NVIDIA Xid catalogue","url":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"}]},{"id":"host.node_thermal_power_capping","domain":"host","name":"Node or rack thermal and power limits","summary":"Inlet air too warm, airflow blocked, or the node or rack power-capped: several GPUs (and the CPUs) slow at once. Jobs spanning the node or rack slow down; time-of-day temperature variation shows as a small periodic throughput change.","job_effect":["slowdown"],"blast_radius":"switch_rack","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Inlet temperature","source":"BMC / Redfish / IPMI","identifier":"the BMC's inlet temperature sensor (`ipmitool sensor`; name vendor-specific)","detection":"rising, or above the facility's limit","strength":"strong","ref":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/best-practices.html"},{"name":"Power at the PSU and PDU","source":"BMC / Redfish / IPMI","identifier":"power draw of each power supply and at the PDU (NVIDIA's key metrics; read through the BMC or PDU, names vendor-specific)","detection":"at the configured cap","strength":"suggestive","ref":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/best-practices.html"},{"name":"Many GPUs throttling together","source":"DCGM","identifier":"DCGM_FI_DEV_CLOCKS_EVENT_REASONS thermal or power bits across the node's or rack's GPUs","detection":"most GPUs of a node or rack at once","strength":"strong","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"name":"CPU temperature (Grace systems)","source":"DCGM","identifier":"DCGM_FI_DEV_CPU_TEMP_CELSIUS (field 1110); DCGM thermal health DCGM_FR_FIELD_THRESHOLD_DBL","detection":"above the warning temperature twice a minute apart, or above critical","strength":"strong","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/feature-overview.html"},{"name":"Host temperature sensors","source":"node_exporter / OS","identifier":"node_hwmon_temp_celsius","detection":"rising across the rack's nodes together","strength":"suggestive","ref":"https://github.com/prometheus/node_exporter/blob/master/collector/hwmon_linux.go"}],"confounders":[{"failure":"gpu.thermal_power_throttling","how_to_distinguish":"One GPU hot under the same airflow as its neighbours: the GPU, not the room."},{"failure":"Time-of-day variation","how_to_distinguish":"Llama 3's diurnal 1-2% throughput variation: fleet-wide, periodic, tracking mid-day temperatures."}],"diagnosis":"Throttling spread across a node or rack with high inlet temperature or capped power confirms a facility-level limit; the GPU-level throttle bits say which (thermal or power).","fixes":[{"fix":"power_thermal_mitigation","when":"Facilities fix inlet air or airflow; or the power cap is raised or spread.","order":1},{"fix":"rebalance_work","when":"Only some of a job's ranks are on the affected rack and the job opted in.","order":2},{"fix":"cordon_node","when":"Nodes keep hitting hardware slowdown until facilities act.","order":3}],"human_role":"Facilities or data-center operations.","verification":{"remeasure":"Inlet temperature in range and throttle bits clear across the rack while busy; affected jobs' throughput within 2% of their healthy value.","post_repair_check":"A rack-wide targeted-power diagnostic (`dcgmi diag -r 3 -i \u003cnode gpu ids>` on each node of the rack, none running a job) without thermal violations."},"escalation_steps":["Map the throttling GPUs to racks and rows.","Read inlet temperature, fan speeds and PDU power for those racks.","Open a facilities ticket with the map and the time series."],"references":[{"title":"NVIDIA GPU debug guidelines: best practices","url":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/best-practices.html"},{"title":"The Llama 3 Herd of Models, section 3.3.4","url":"https://arxiv.org/html/2407.21783v3"}]},{"id":"host.software_firmware_drift","domain":"host","name":"Node OS, kernel, library or firmware drift from the fleet baseline","summary":"A node's kernel, OS image, RDMA stack, BIOS or BMC firmware, or the job image's CUDA, NCCL or framework version differs from the baseline. Jobs on it may run slower or fail in ways the rest of the fleet does not; a bad rollout fails many nodes the same way.","job_effect":["latent","slowdown","crash"],"blast_radius":"node","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Node software inventory","source":"Inventory","identifier":"kernel release (`uname -r`), OS image version, RDMA stack version, BIOS and BMC firmware revisions, from the site's inventory (no single standard source)","detection":"differs from the baseline for the node class","strength":"definitive","ref":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/best-practices.html"},{"name":"Job software identity","source":"Artemis analysis, algorithm pending","identifier":"Software versions recorded with each run (torch, CUDA, NCCL, driver, ...)","detection":"differs between the regressed run and its baseline run","strength":"Pending"}],"confounders":[{"failure":"A deliberate canary","how_to_distinguish":"The node is in a rollout's canary set."},{"failure":"gpu.firmware_driver_drift","how_to_distinguish":"The difference is in the GPU's own driver, VBIOS or firmware: gpu.firmware_driver_drift. This entry covers kernel, OS image, RDMA stack, BIOS, BMC firmware and job-image libraries."}],"diagnosis":"Inventory against the baseline is definitive for the drift. Its effect is a hypothesis until a matched run (same workload, same hardware class, baseline versus drifted node or image) shows the difference.","fixes":[{"fix":"cordon_node","when":"The version is known bad.","order":1},{"fix":"schedule_firmware_update","when":"Firmware or OS image: bring the node to the baseline in a window.","order":2},{"fix":"rollback_software_change","when":"A recent rollout or image change regressed jobs.","order":3},{"fix":"run_active_diagnostic","when":"After the change.","order":4}],"human_role":"Platform team (node images and firmware); job owner (job image).","verification":{"remeasure":"Inventory reads the baseline; the matched benchmark within the class baseline.","post_repair_check":"Node health check and `dcgmi diag -r 2 -i \u003cnode gpu ids>` pass."},"escalation_steps":["Diff the node's inventory against its class baseline.","Check whether failures or slow-rank findings cluster by the differing version.","Schedule the update or rollback with the version's owner."],"references":[{"title":"NVIDIA GPU debug guidelines: best practices (confirm software and versions in prolog)","url":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/best-practices.html"}]},{"id":"host.time_sync","domain":"host","name":"Clock not synchronized","summary":"The node's clock drifts or its time service is not synchronized. No source reviewed for this map shows a training slowdown from clock offset; the effect is on correlating events across nodes: logs, traces and wall-time joins of host telemetry and incidents misorder or mismatch.","job_effect":["latent"],"blast_radius":"node","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"chrony tracking","source":"node_exporter / OS","identifier":"`chronyc tracking`: System time offset and Leap status","detection":"System time offset above site policy, or Leap status `Not synchronised`. `Normal`, `Insert second` and `Delete second` are healthy: the last two announce a scheduled leap second.","strength":"definitive","ref":"https://chrony-project.org/doc/4.6/chronyc.html"},{"name":"Kernel time status","source":"node_exporter / OS","identifier":"node_timex_offset_seconds, node_timex_sync_status (node_exporter timex collector)","detection":"sync_status 0, or |offset| above site policy","strength":"definitive","ref":"https://github.com/prometheus/node_exporter/blob/master/collector/timex.go"},{"name":"NPD custom plugin","source":"Scheduler","identifier":"Node Problem Detector custom plugin NTPProblem (the project's example plugin)","detection":"condition true","strength":"strong","ref":"https://github.com/kubernetes/node-problem-detector"}],"confounders":[{"failure":"Time source down for the whole site","how_to_distinguish":"Every node loses sync at once: the time servers, not this node."}],"diagnosis":"The time service's own status is definitive for the offset. Treat cross-node timing evidence from an unsynchronized node as unreliable until it resyncs.","fixes":[{"fix":"restart_system_service","when":"Restart chronyd.","order":1},{"fix":"cordon_node","when":"It does not resync.","order":2},{"fix":"query_health_watches","when":"After it resyncs: read the node's health watches (`dcgmi health -c`) and the site's own NHC result; no active test.","order":3}],"human_role":"Cluster operator.","verification":{"remeasure":"`chronyc tracking` Leap status not `Not synchronised` and the offset within policy over an observation window (length: Pending).","post_repair_check":"node_timex_sync_status 1."},"escalation_steps":["Read `chronyc tracking` and `chronyc sources`.","Check reachability of the configured time servers.","Mark cross-node timing evidence from the node's affected window as unreliable."],"references":[{"title":"chronyc documentation","url":"https://chrony-project.org/doc/4.6/chronyc.html"},{"title":"node_exporter timex collector","url":"https://github.com/prometheus/node_exporter/blob/master/collector/timex.go"}]},{"id":"host.gpu_software_stack_not_ready","domain":"host","name":"Node's GPU software stack not ready","summary":"The node is up but cannot run GPU work correctly: the GPU driver is not loaded, or a module the node's role needs is missing (nvidia-peermem where its GPUDirect RDMA path uses it rather than DMA-BUF, gdrdrv where its workloads use GDRCopy), the persistence daemon or Fabric Manager (HGX) is not running, the DCGM host engine is down, or the GPU count is short. Jobs fail at start or run without GPUDirect.","job_effect":["crash","capacity_loss"],"blast_radius":"node","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Prolog software checks","source":"Inventory","identifier":"GPU driver loaded; nvidia-peermem (nv-peer-mem) loaded only where the node's intended GPUDirect RDMA path uses it (with DMA-BUF on a recent kernel and the open GPU driver, NCCL needs no nvidia-peermem); gdrdrv loaded only where the node's workloads use GDRCopy; Fabric Manager running (HGX); persistence set through the persistence daemon; GPU count, PCIe link speed and VBIOS as expected","detection":"a check that the node's declared role requires (its transport, GDRCopy use, HGX or not, from the node baseline) failing in a prolog or periodic health check; a module the role does not need being absent is not a failure","strength":"definitive","ref":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/best-practices.html"},{"name":"Quick DCGM diagnostic","source":"DCGM","identifier":"`dcgmi diag -r 1 -i \u003cgpu ids>` (software plugin: NVML and CUDA library access, permissions, driver, cgroups)","detection":"any failure","strength":"definitive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/dcgm-diagnostics.html"},{"name":"DCGM exporter target down","source":"Artemis analysis, algorithm pending","identifier":"Exporter targets that are down, and running GPUs with no DCGM series","detection":"Any such target or GPU","strength":"Pending"},{"name":"Kubernetes runtime health","source":"Scheduler","identifier":"Node Problem Detector ContainerRuntimeUnhealthy; GPU Operator validator","detection":"condition true or validator failing","strength":"strong","ref":"https://github.com/kubernetes/node-problem-detector"}],"confounders":[{"failure":"job.container_runtime_start_failure","how_to_distinguish":"One job's image or runtime configuration fails while other jobs on the node run GPU work. Boundary: this entry is the node's stack and fails every job on the node; job.container_runtime_start_failure is one job's image or runtime spec and follows the image to other nodes."},{"failure":"gpu.inaccessible_fallen_off_bus","how_to_distinguish":"An Xid 79/143 or a GPU missing at the PCI level, not just the driver."},{"failure":"fabric.nvswitch_fabric_manager_failure","how_to_distinguish":"Fabric Manager down or the fabric not ready on an NVSwitch system is tracked as fabric.nvswitch_fabric_manager_failure; this entry covers the other stack pieces."}],"diagnosis":"A failing check that the node's role requires names the missing piece; that is definitive. Absence alone is not: a node using DMA-BUF for GPUDirect RDMA needs no nvidia-peermem, and gdrdrv matters only for GDRCopy workloads. A short GPU count with the GPU visible on PCI but not to the driver points at the driver; missing from PCI points at the GPU.","fixes":[{"fix":"cordon_node","when":"A check the node's role requires fails (prolog check or `dcgmi diag -r 1 -i \u003cgpu ids>` on the job's own GPUs). A missing nvidia-peermem on a DMA-BUF node, or a missing gdrdrv on a node without GDRCopy workloads, is not a trigger.","order":1},{"fix":"restart_system_service","when":"A daemon is down (persistence daemon, Fabric Manager, DCGM host engine).","order":2},{"fix":"node_reboot","when":"The driver or modules did not load.","order":3},{"fix":"rollback_software_change","when":"A driver or module install is broken.","order":4}],"human_role":"Cluster operator approves service restarts and the reboot; platform team for a broken install.","verification":{"remeasure":"Every prolog check passes and `dcgmi diag -r 1 -i \u003cgpu ids>` passes on the job's own GPUs.","post_repair_check":"`dcgmi diag -r 2 -i \u003cnode gpu ids>` passes before resuming."},"escalation_steps":["Run the prolog checks and `dcgmi diag -r 1 -i \u003cgpu ids>` on the job's own GPUs; note which fails.","Read the failing service's logs (Fabric Manager log on HGX).","Check the driver and module packages against the baseline."],"references":[{"title":"NVIDIA GPU debug guidelines: best practices (catching errors before they occur)","url":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/best-practices.html"},{"title":"DCGM diagnostics","url":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/dcgm-diagnostics.html"},{"title":"NVIDIA GPU Operator overview","url":"https://docs.nvidia.com/datacenter/cloud-native/gpu-operator/latest/overview.html"},{"title":"NCCL troubleshooting: GPU Direct RDMA (nvidia-peermem or DMA-BUF)","url":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/troubleshooting/gpu_troubleshooting.html"}]},{"id":"host.pcie_acs_iommu_misconfig","domain":"host","name":"PCIe ACS or IOMMU translation breaking GPU peer-to-peer","summary":"PCI Access Control Services (ACS) enabled on PCIe switches or bridges between GPUs, or the IOMMU in translated mode on a bare-metal node, breaks or slows GPU peer-to-peer (P2P) traffic. NVIDIA's NCCL troubleshooting page: IO virtualization redirects all PCI point-to-point traffic to the CPU root complex, \"causing a significant performance reduction or even a hang\"; CUDA does not support IOMMU-enabled PCIe P2P on Linux bare metal, and the IOMMU must be disabled there \"to prevent silent device memory corruption\". Symptoms can look like application or framework bugs rather than a clean NCCL error, and `nvidia-smi topo -p2p p` can still show OK. Usually a BIOS or kernel command-line setting off the site's baseline. Inside a virtual machine ACS is required, so this entry covers bare metal only.","job_effect":["slowdown","hang","silent_corruption"],"blast_radius":"node","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"ACS control on PCI bridges","source":"Inventory","identifier":"`sudo lspci -vvv | grep ACSCtl` (the ACSCtl line of each PCI bridge; `sudo lspci -vvv` shows which bridge)","detection":"`SrcValid+` on a bridge or PCIe switch port between GPUs: NVIDIA says ACS \"might be enabled\" then. Bare metal only.","strength":"strong","ref":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/troubleshooting/gpu_troubleshooting.html"},{"name":"Kernel IOMMU mode","source":"Kernel log","identifier":"`dmesg | grep -i -E \"iommu|dmar|default domain\"`: lines such as `iommu: Default domain type: Translated`, `DMAR: IOMMU enabled`","detection":"A translated default domain on a bare-metal GPU node, which NVIDIA calls \"concerning for Linux bare-metal PCIe P2P\". Kernel messages vary by kernel and platform.","strength":"strong","ref":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/troubleshooting/gpu_troubleshooting.html"},{"name":"Kernel command line","source":"Inventory","identifier":"`cat /proc/cmdline` (IOMMU options)","detection":"Differs from the site's GPU-node baseline. NVIDIA's page names no specific option, so the expected value is site policy; the kernel log shows the mode actually in effect.","strength":"suggestive","ref":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/troubleshooting/gpu_troubleshooting.html"},{"name":"GPU P2P matrix","source":"NVML / nvidia-smi","identifier":"`nvidia-smi topo -p2p p` (PCIe; `n` for NVLink)","detection":"A GPU pair differs from the node class's known-good baseline: a pair that is OK on same-class peer nodes shows as not OK here. P2P support depends on the PCIe and NVLink topology, so a pair that is not OK on a healthy node of the class is not a finding. A matrix matching the baseline does not rule this entry out: NVIDIA calls it \"not a complete system sanity check for this issue\".","strength":"suggestive","ref":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/troubleshooting/gpu_troubleshooting.html"},{"name":"P2P-disabled comparison","source":"NCCL","identifier":"the same collective (or nccl-tests within the node) with `NCCL_P2P_DISABLE=1` or a lower `NCCL_P2P_LEVEL`","detection":"The hang, slowdown or corruption disappears with P2P disabled or restricted: the P2P path is implicated.","strength":"strong","ref":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/troubleshooting/gpu_troubleshooting.html"}],"confounders":[{"failure":"gpu.silent_data_corruption","how_to_distinguish":"IOMMU translation corrupts P2P transfers on the node's PCIe P2P paths, whichever GPU is involved, and stops with translation off or with `NCCL_P2P_DISABLE=1`; a faulty GPU follows that one device in replay, with P2P disabled too. Read the kernel IOMMU mode before blaming a GPU."},{"failure":"fabric.slow_island_or_bridge_link","how_to_distinguish":"ACS routes every PCIe P2P transfer through the root complex, so every GPU pair behind the affected switches is slow at once, ACSCtl shows `SrcValid+`, and the gap closes with ACS disabled or `NCCL_P2P_DISABLE=1`. A degraded bridge or link is one path while the others run at peer speed."},{"failure":"fabric.nic_gpu_affinity_misconfig","how_to_distinguish":"A wrong NIC or rail shows in `nvidia-smi topo -m` and NCCL's init log and slows only inter-node traffic. ACS or IOMMU translation also slows or hangs intra-node GPU-to-GPU P2P, and shows in ACSCtl and the kernel IOMMU mode."},{"failure":"job.collective_hang_watchdog","how_to_distinguish":"An ACS hang recurs on the same node in P2P collectives, run after run, and stops with `NCCL_P2P_DISABLE=1` or ACS disabled; other hangs follow a rank, a link or the job's code."}],"diagnosis":"On a bare-metal node whose intra-node collectives are slow, hang, or produce wrong results: read the ACSCtl lines and the kernel IOMMU mode first (reads, no test). If either is off the site's baseline, compare the collective with P2P disabled or restricted (`NCCL_P2P_DISABLE`, `NCCL_P2P_LEVEL`); a symptom that disappears confirms the P2P path, and the settings name the cause. A node that matches the baseline and still fails the comparison points at the GPU, link or bridge entries instead.","fixes":[{"fix":"cordon_node","when":"ACSCtl shows `SrcValid+` between GPUs, or the kernel IOMMU mode is translated, on a bare-metal GPU node off the site's baseline.","order":1},{"fix":"run_active_diagnostic","when":"Confirm with an approved comparison: nccl-tests all_reduce_perf within the node with and without `NCCL_P2P_DISABLE=1`, on a node with no job.","order":2},{"fix":"schedule_firmware_update","when":"A BIOS setting: disable IO virtualization or VT-d (NVIDIA: \"On some systems this can be done from the BIOS\"), or ACS on the PCIe switches, in a maintenance window with a reboot.","order":3},{"fix":"rollback_software_change","when":"A kernel command-line change put the IOMMU in translated mode: restore the baseline command line and reboot.","order":3}],"human_role":"Cluster operator or platform team (BIOS and kernel command-line baseline); vendor for PCIe switch firmware.","verification":{"remeasure":"nccl-tests all_reduce_perf within the node at the default P2P level returns to the node class's known-good baseline (same-class peer nodes) and no longer differs from the `NCCL_P2P_DISABLE=1` run by more than that baseline does.","post_repair_check":"`sudo lspci -vvv | grep ACSCtl` shows no `SrcValid+` on the bridges between GPUs, the kernel log shows no translated default domain, `nvidia-smi topo -p2p p` matches the node class's known-good baseline pair for pair (P2P support depends on the PCIe and NVLink topology, so not every pair is OK on a healthy node), then a within-node nccl-tests run on a node with no job returns to that baseline."},"escalation_steps":["Read `sudo lspci -vvv | grep ACSCtl` and find which bridges between GPUs show `SrcValid+` (`sudo lspci -vvv` for the full tree).","Read `/proc/cmdline` and `dmesg | grep -i -E \"iommu|dmar|default domain\"` for the IOMMU mode in effect; compare with the site's GPU-node baseline.","Confirm the node is bare metal: virtual machines require ACS, so it is not disabled there.","Disable IO virtualization or VT-d in the BIOS, or restore the baseline kernel command line, in a maintenance window. For Broadcom PLX switches ACS can be cleared from the OS with `setpci`, but NVIDIA notes it must be redone after each reboot.","Rerun the within-node nccl-tests and compare with peer nodes."],"references":[{"title":"NCCL GPU troubleshooting: GPU Direct and peer-to-peer, IOMMU, PCI ACS, BIOS settings","url":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/troubleshooting/gpu_troubleshooting.html"},{"title":"CUDA Programming Guide: multi-GPU systems, peer-to-peer memory access (support depends on PCIe and NVLink topology)","url":"https://docs.nvidia.com/cuda/cuda-programming-guide/03-advanced/multi-gpu-systems.html#peer-to-peer-memory-access"}]},{"id":"fabric.nvlink_link_errors","domain":"fabric","name":"NVLink CRC, replay or recovery errors on a link that is still up","summary":"An NVLink between two GPUs, or between a GPU and an NVSwitch, keeps passing traffic but its error counters climb: CRC errors, replays and link recoveries. Each replay or recovery costs bandwidth and latency, so the job sees slower intra-node collectives on the GPUs behind that link before anything crashes. It can progress to a link-down event (fabric.nvlink_link_down).","job_effect":["slowdown","latent"],"blast_radius":"link","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"NVLink error counters, pre-Hopper GPUs","source":"DCGM","identifier":"DCGM_FI_DEV_NVLINK_CRC_FLIT_ERROR_TOTAL, DCGM_FI_DEV_NVLINK_CRC_DATA_ERROR_TOTAL, DCGM_FI_DEV_NVLINK_REPLAY_ERROR_TOTAL, DCGM_FI_DEV_NVLINK_RECOVERY_ERROR_TOTAL (field ids 409, 419, 429, 439; per-link _L0.._L17 variants exist)","detection":"Any increase on a link, compared with the other links of the same GPU and with the same link's own history. NVIDIA publishes no repair or RMA threshold for these counters. DCGM's NVLink health watch (`dcgmi health -s n`) warns above 100 NVLink CRC errors per second (DCGM feature overview, health monitoring); that is a watch criterion, not a repair or RMA criterion, and the rate that triggers action is site policy. dcgm-exporter's default CSV ships these lines commented out, so they must be enabled.","strength":"strong","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"name":"NVLink data-link error counters, Hopper","source":"DCGM","identifier":"DCGM_FI_DEV_NVLINK_CRC_ERROR_TOTAL (497), DCGM_FI_DEV_NVLINK_RECOVERY_TOTAL (498), DCGM_FI_DEV_NVLINK_REPLAY_TOTAL (499)","detection":"Any increase, as above. Generation mapping (pre-Hopper vs Hopper vs Blackwell fields) is from the comments in dcgm-exporter's etc/default-counters.csv; the DCGM field-ID page gives no description for 497-499. Threshold is site policy.","strength":"strong","ref":"https://github.com/NVIDIA/dcgm-exporter/blob/main/etc/default-counters.csv"},{"name":"NVLink5 recovery and BER fields (Blackwell and later)","source":"DCGM","identifier":"DCGM_FI_DEV_NVLINK_RECOVERY_EVENT_TOTAL (1213), DCGM_FI_DEV_NVLINK_RECOVERY_SUCCESSFUL_TOTAL (1211), DCGM_FI_DEV_NVLINK_RX_SYMBOL_ERROR_TOTAL (1214), DCGM_FI_DEV_NVLINK_SYMBOL_BER_RATIO (1216), DCGM_FI_DEV_NVLINK_EFFECTIVE_BER_RATIO (1218)","detection":"Any increase of recovery events; BER ratio rising against the link's own history. The field page says these are NVLink5+ only and aggregate across all links; it states no BER limit, so the limit is site policy.","strength":"strong","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"name":"Per-link error counters from nvidia-smi","source":"NVML / nvidia-smi","identifier":"nvidia-smi nvlink -e (--errorcounters): for NVLink 4, Replay Errors, Recovery Errors, CRC Errors per link","detection":"Read on demand to find which link of the GPU carries the errors; compare links.","strength":"strong","ref":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"},{"name":"Slow intra-island collectives","source":"Artemis analysis, algorithm pending","identifier":"Island collective time against warmup. Rule: Pending","detection":"Flagged by a communication rule (algorithm Pending); it names an island, not a link. Correlates only: congestion, a slow peer or CPU contention give the same finding.","strength":"Pending"}],"confounders":[{"failure":"fabric.nvlink_link_down","how_to_distinguish":"Link down shows the link Inactive in nvidia-smi nvlink -s, an Xid 74 (A100/H100) or Xid 144-150 (NVLink5) in the kernel log, and usually a crashed or hung job. Here the link stays Active and only counters climb."},{"failure":"gpu domain: a failing GPU at the other end of the link","how_to_distinguish":"The Xid catalogue notes a failing remote GPU can make a healthy link report errors. Check whether the errors concentrate on links to one GPU or NVSwitch (remote end) or on one link only (cable/connector/lane)."},{"failure":"fabric.slow_island_or_bridge_link","how_to_distinguish":"A slow island with zero NVLink error increase points away from the link: check host contention and per-GPU telemetry first."}],"diagnosis":"Rank the link as the cause when its error counters rise while sibling links of the same GPU stay flat, and a slow-island finding (if any) involves GPUs behind that link. Errors on every link of one GPU point at the GPU or its baseboard rather than one link. A slowdown without counter increases is not this failure. Confirmation is a matched re-run of an NVLink bandwidth test (DCGM diag pcie/nvbandwidth or nccl-tests within the node) after reset or repair, with counters flat.","fixes":[{"fix":"cordon_node","when":"Errors keep rising across repeated windows (count and length: Pending); stop new jobs landing on the node while the running job finishes or checkpoints.","order":1},{"fix":"run_active_diagnostic","when":"Before deciding on reset or RMA: run dcgmi diag at level 2 or 3 with -i \u003cnode gpu ids> (pcie and nvbandwidth tests) on the drained node, which runs no job.","order":2},{"fix":"gpu_reset","when":"Node is drained; the Xid catalogue says a GPU reset or node reboot clears an NVLink error state. On Ampere NVSwitch systems Fabric Manager must be running to reset an individual GPU (nvidia-smi documentation).","order":3},{"fix":"rma_replace_hardware","when":"Errors return after reset, or the health check fails on the same link.","order":4}],"human_role":"cluster operator approves the reset; data-center technician or vendor RMA replaces the GPU or baseboard","verification":{"remeasure":"After reset: the same NVLink counters show zero increase over a period of load or an nvbandwidth/nccl-tests run (length: Pending), and intra-node all_reduce bus bandwidth is within site tolerance of identical nodes.","post_repair_check":"dcgmi diag -r 3 -i \u003cnode gpu ids> passes (includes the pcie test, which DCGM documents as PCIe + NVLink); nvidia-smi nvlink -s shows every link Active; nccl-tests all_reduce_perf within the node matches peer nodes."},"escalation_steps":["Identify the link: nvidia-smi nvlink -e per GPU; note which links and which remote GPU/NVSwitch they connect to (nvidia-smi nvlink remote-node query).","Check whether the errors follow one remote device (suspect that device) or one link (suspect the connector, cable or baseboard trace).","Collect nvidia-bug-report and the kernel log for Xids around the error onset.","Reset the GPU on a drained node and re-run the NVLink bandwidth test; if errors return, open a vendor RMA for the GPU or baseboard with the counter history."],"references":[{"title":"DCGM field identifiers","url":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"title":"dcgm-exporter default counters","url":"https://github.com/NVIDIA/dcgm-exporter/blob/main/etc/default-counters.csv"},{"title":"nvidia-smi documentation","url":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"},{"title":"NVIDIA Xid catalog (analyzing Xid errors)","url":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"title":"DCGM diagnostics","url":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/dcgm-diagnostics.html"},{"title":"C4: real-time anomaly detection and communication optimization (Alibaba)","url":"https://arxiv.org/abs/2406.04594"},{"title":"DCGM feature overview: health monitoring","url":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/feature-overview.html"},{"title":"Revisiting Reliability in Large-Scale ML Research Clusters (Meta)","url":"https://arxiv.org/abs/2410.21680"}]},{"id":"fabric.nvlink_link_down","domain":"fabric","name":"NVLink link down or failed training (Xid 74, NVLink5 Xids 144-150, Xid 136)","summary":"An NVLink goes down or fails to train. NVLink traffic is load/store from CUDA kernels, so the job typically stalls inside a kernel without a clear error and is ended by the collective watchdog, or crashes. A GPU reset or node reboot is needed to clear the error state.","job_effect":["hang","crash","capacity_loss"],"blast_radius":"node","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Xid 74 NVLINK_ERROR","source":"Kernel log","identifier":"kernel log line 'NVRM: Xid (PCI:\u003cbdf>): 74, ...' (Xid 74 NVLINK_ERROR; catalogued for A100 and H100)","detection":"Any occurrence. Xid catalog: 'A GPU reset or node reboot is needed to clear this error'; a failing remote GPU can make its peer report Xid 74.","strength":"definitive","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"name":"NVLink5 Xids and link-training failure","source":"Kernel log","identifier":"Xid 144 NVLINK_SAW_ERROR, 145 NVLINK_RLW_ERROR, 146 NVLINK_TLW_ERROR (and through 150; B100/GB200), Xid 136 ALI_TRAINING_FAIL (H100)","detection":"Any occurrence. For 144-150 the Xid catalog's subcode table decides fatal vs non-fatal and the recovery action.","strength":"definitive","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"name":"Link state","source":"NVML / nvidia-smi","identifier":"nvidia-smi nvlink -s (--status): a present link that is not Active shows as Inactive","detection":"Any link that was Active and is now Inactive on a GPU whose peers' links are Active.","strength":"definitive","ref":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"},{"name":"Failed recoveries and NVSwitch port status","source":"DCGM","identifier":"DCGM_FI_DEV_NVLINK_RECOVERY_FAILED_TOTAL (1212, NVLink5+: 'link went from Up to recovery, failed and link was declared down'); DCGM_FI_DEV_NVSWITCH_LINK_STATUS (870: UNKNOWN -1, OFF 0, SAFE 1, ACTIVE 2, ERROR 3)","detection":"Any increase of failed recoveries; switch port status ERROR or OFF on a port that was ACTIVE.","strength":"definitive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"name":"Recovery action required","source":"DCGM","identifier":"Xid 154 GPU_RECOVERY_ACTION_CHANGED; DCGM_FI_DEV_GPU_RECOVERY_ACTION (1523); `nvidia-smi --query-gpu=gpu_recovery_action`","detection":"Recovery action not None ('Drain P2P', 'Drain and Reset', 'GPU Reset Required', 'Node Reboot Required'). The Xid catalog calls Xid 154 informational, always seen with another Xid whose recovery it summarizes: it says a recovery is needed, not that NVLink is down. It picks the reset or reboot step only after link-specific evidence selects this entry.","strength":"suggestive","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"name":"Job hang or watchdog timeout","source":"Artemis analysis, algorithm pending","identifier":"Hang finding naming the collective and the ranks behind","detection":"No progress with a rank inside a collective. Interval: Pending. Correlates only: any hang cause gives this.","strength":"Pending"}],"confounders":[{"failure":"gpu.inaccessible_fallen_off_bus","how_to_distinguish":"The Xid catalogue says a failed GPU can make its NVLink peers log Xid 74. Look for Xid 79 or other GPU Xids on the remote GPU first; if present, the link errors are sympathetic."},{"failure":"fabric.nvswitch_fabric_manager_failure","how_to_distinguish":"If many GPUs lose NVLink at once, or nvidia-smi -q shows Fabric State not Completed, suspect the NVSwitch or Fabric Manager rather than one link."},{"failure":"job.collective_hang_watchdog","how_to_distinguish":"A software hang has no NVLink Xid and all links Active."}],"diagnosis":"An NVLink Xid on the node, with a link Inactive or a failed-recovery increment, confirms the link event. Xid 154 and DCGM_FI_DEV_GPU_RECOVERY_ACTION say a recovery is required for some other Xid, not that a link is down: the exclusion and repair path below needs link-specific evidence first (an NVLink Xid 74, 136 or 144-150, a link Inactive in `nvidia-smi nvlink -s`, a failed-recovery increment, or a switch port in ERROR or OFF), and the recovery action then chooses between reset and reboot. Decide local vs remote: errors logged on both ends of one link with no other GPU Xids point at the link; Xids on one GPU's peers plus a GPU fault on that GPU point at the GPU. A job hang alone only correlates.","fixes":[{"fix":"exclude_and_restart","when":"The job hung or crashed and link-specific evidence (NVLink Xid, link Inactive, failed-recovery increment or switch port ERROR/OFF) points at NVLink; restart from the last checkpoint without the node.","order":1},{"fix":"drain_node","when":"Immediately, so no new job lands on the node.","order":2},{"fix":"gpu_reset","when":"Node drained and the recovery action (Xid 154) is GPU Reset Required or Drain and Reset.","order":3},{"fix":"node_reboot","when":"Reset fails or the recovery action is Node Reboot Required.","order":4},{"fix":"rma_replace_hardware","when":"The error repeats after reset or reboot; NVIDIA's Xid catalog says to contact the hardware vendor.","order":5}],"human_role":"cluster operator for reset/reboot approval; data-center technician or vendor RMA for hardware replacement","verification":{"remeasure":"Restarted job: step time within the job's pre-incident baseline on the replacement nodes (margin and sample count: Pending); no hang report over an observation window (length: Pending).","post_repair_check":"nvidia-smi nvlink -s all Active; no new NVLink Xid after dcgmi diag -r 3 -i \u003cnode gpu ids>; intra-node nccl-tests all_reduce_perf bus bandwidth matches peer nodes."},"escalation_steps":["Collect kernel log Xids for all GPUs on the node around the event, and nvidia-smi nvlink -s / -e output.","Identify which GPU or NVSwitch is at the remote end of the failed link and whether it logged its own Xids.","Follow NVIDIA's resolution bucket for the Xid (WORKFLOW_NVLINK_ERR for 74, WORKFLOW_NVLINK5_ERR for 144-150, RESET_GPU for 136).","If the error persists after GPU reset and node reboot, open a vendor RMA with nvidia-bug-report output."],"references":[{"title":"NVIDIA Xid catalog (analyzing Xid errors)","url":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"title":"nvidia-smi documentation","url":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"},{"title":"DCGM field identifiers","url":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"title":"The Llama 3 Herd of Models, section 3.3.4","url":"https://arxiv.org/abs/2407.21783"},{"title":"C4: real-time anomaly detection and communication optimization (Alibaba)","url":"https://arxiv.org/abs/2406.04594"}]},{"id":"fabric.nvswitch_fabric_manager_failure","domain":"fabric","name":"NVSwitch failure or Fabric Manager not running / failed","summary":"On NVSwitch systems the fabric must be initialized before CUDA can use NVLink peer-to-peer. If Fabric Manager (FM) fails or an NVSwitch, trunk link or access link fails, behaviour depends on the system generation and FM's high-availability config: CUDA launches fail with cudaErrorSystemNotReady (FM aborts and leaves the system uninitialized), the fabric runs at reduced bandwidth (5/6 on HGX A100 degraded modes), or a GPU loses NVLink P2P but stays usable for non-NVLink work. Fatal NVSwitch SXids kill running jobs.","job_effect":["crash","slowdown","capacity_loss"],"blast_radius":"node","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"GPU fabric registration state","source":"NVML / nvidia-smi","identifier":"nvidia-smi -q -i \u003cgpu> | grep -i -A 2 Fabric: 'Fabric State : Completed / Status : Success' when registered; 'In Progress' while registering","detection":"Any GPU not Completed/Success a few minutes after boot (H100 and later, ALI-trained NVLink). The FM guide says a GPU that fails to register loses NVLink P2P.","strength":"definitive","ref":"https://docs.nvidia.com/datacenter/tesla/fabric-manager-user-guide/index.html"},{"name":"Fabric Manager status and fabric health","source":"DCGM","identifier":"DCGM_FI_DEV_FABRIC_MANAGER_STATUS (170), DCGM_FI_DEV_FABRIC_MANAGER_ERROR (171), DCGM_FI_DEV_FABRIC_HEALTH_SUMMARY (175: NOT_SUPPORTED 0, HEALTHY 1, UNHEALTHY 2, LIMITED_CAPACITY 3)","detection":"Health summary 2 or 3, or FM status other than its started/success value (the dcgmFabricManagerStatus_t values are not listed on the field page).","strength":"definitive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"name":"NVSwitch port errors","source":"DCGM","identifier":"DCGM_FI_DEV_NVSWITCH_LINK_FATAL_ERRORS (782), DCGM_FI_DEV_NVSWITCH_LINK_NON_FATAL_ERRORS (783), DCGM_FI_DEV_NVSWITCH_LINK_STATUS (870)","detection":"Any fatal-error increase; status ERROR (3).","strength":"strong","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"name":"Fatal NVSwitch SXid","source":"Kernel log","identifier":"SXid codes in the kernel log, e.g. always-fatal 12020 'egress sequence ID error', 22003 'Minion Halt', 23001-23017; potentially fatal 11001-20034 list (20034 'LTSSM Fault Up': link went down from active)","detection":"Any always-fatal SXid: the guide says the host must be restarted (or switches and GPUs SBR'd).","strength":"definitive","ref":"https://docs.nvidia.com/datacenter/tesla/fabric-manager-user-guide/index.html"},{"name":"CUDA init failure and FM service state","source":"Job telemetry","identifier":"job start error cudaErrorSystemNotReady; systemd unit nvidia-fabricmanager not active; /var/log/fabricmanager.log (default LOG_FILE_NAME)","detection":"Any job start failing with cudaErrorSystemNotReady on the node.","strength":"strong","ref":"https://docs.nvidia.com/datacenter/tesla/fabric-manager-user-guide/index.html"}],"confounders":[{"failure":"gpu.firmware_driver_drift","how_to_distinguish":"fabricmanager.log startup errors after a driver update with no SXid or link errors point at a software/version problem (restart or package fix), not hardware."},{"failure":"fabric.nvlink_link_down","how_to_distinguish":"One GPU's links failing with other GPUs registered and healthy is an access-link or GPU problem; all GPUs unregistered or SXids on a switch point at the switch or FM."},{"failure":"job.container_runtime_start_failure","how_to_distinguish":"cudaErrorSystemNotReady on every container on the node and on bare-metal CUDA samples is the fabric; a failure only inside one image is the image or runtime."},{"failure":"host.gpu_software_stack_not_ready","how_to_distinguish":"Boundary: Fabric Manager not running is one of the node stack checks in host.gpu_software_stack_not_ready. When Fabric Manager or an NVSwitch is the failing piece (fabric state, FM status, SXid), the incident is this entry."}],"diagnosis":"Read the GPU fabric state and FM health first. Unregistered GPUs plus an FM error with no SXid: FM or software (version mismatch, service failed). Fatal SXids or NVSwitch port errors: switch hardware. Reduced-bandwidth modes are only visible as LIMITED_CAPACITY or lower NVLink throughput, so compare nccl-tests bus bandwidth with peer nodes.","fixes":[{"fix":"drain_node","when":"Any unregistered GPU, FM failure or fatal SXid: nothing new should start on the node.","order":1},{"fix":"restart_system_service","when":"FM failed without hardware SXids: stop CUDA apps and GPU services, stop FM, reset GPUs (nvidia-smi -r), restart FM, resume services, per the FM guide's restart sequence.","order":2},{"fix":"node_reboot","when":"Always-fatal SXid, or FM restart does not register the GPUs.","order":3},{"fix":"rma_replace_hardware","when":"SXids or fabric failure persist across reboot.","order":4}],"human_role":"cluster operator approves the FM restart or reboot; vendor RMA if the NVSwitch baseboard is faulty","verification":{"remeasure":"Every GPU reports Fabric State Completed / Status Success; DCGM_FI_DEV_FABRIC_HEALTH_SUMMARY = 1; a CUDA P2P test starts without cudaErrorSystemNotReady.","post_repair_check":"dcgmi diag -r 3 -i \u003cnode gpu ids> passes; nccl-tests all_reduce_perf on all GPUs of the node matches the bus bandwidth of peer nodes (no 5/6 degraded fabric)."},"escalation_steps":["Capture nvidia-smi -q Fabric section for every GPU, systemctl status nvidia-fabricmanager and /var/log/fabricmanager.log.","Grep the kernel log for SXid codes; classify against the FM guide's fatal / always-fatal / non-fatal tables.","Check FM, driver and NVSwitch firmware versions against the supported matrix (driver release 620+ versions FM independently on fourth-generation NVSwitches).","If fatal SXids recur after reboot, open a vendor RMA for the NVSwitch baseboard."],"references":[{"title":"NVIDIA Fabric Manager user guide","url":"https://docs.nvidia.com/datacenter/tesla/fabric-manager-user-guide/index.html"},{"title":"DCGM field identifiers","url":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"title":"nvidia-smi documentation","url":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"}]},{"id":"fabric.pcie_link_degraded","domain":"fabric","name":"PCIe link trained below its maximum width or speed (GPU or NIC)","summary":"A GPU's or NIC's PCIe link comes up narrower (e.g. x8 instead of x16) or at a lower generation than the device and slot support. Host-device copies, GPUDirect RDMA and NIC throughput on that device drop, so its rank becomes a straggler; nothing crashes.","job_effect":["slowdown"],"blast_radius":"gpu","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"GPU PCIe width/generation below maximum, under load","source":"DCGM","identifier":"DCGM_FI_DEV_PCIE_LINK_WIDTH (238) \u003c DCGM_FI_DEV_PCIE_MAX_LINK_WIDTH (236); DCGM_FI_DEV_PCIE_LINK_GEN (237) \u003c DCGM_FI_DEV_PCIE_MAX_LINK_GEN (235)","detection":"Below maximum while the GPU is loaded, so an idle power-saving downshift does not count. Threshold and duration: Pending.","strength":"strong"},{"name":"Any PCI function (NIC, switch port) below maximum","source":"node_exporter / OS","identifier":"node_pcidevice_current_link_width \u003c node_pcidevice_max_link_width; node_pcidevice_current_link_transfers_per_second vs max_link_transfers_per_second (-1 when unknown)","detection":"Current below maximum on a NIC or GPU function; compare with the same slot on identical nodes.","strength":"strong","ref":"https://github.com/prometheus/node_exporter/blob/master/collector/pcidevice_linux.go"},{"name":"PCIe replays","source":"DCGM","identifier":"DCGM_FI_DEV_PCIE_REPLAY_COUNTER (dcgm-exporter CSV name; field 202, DCGM_FI_DEV_PCIE_REPLAY_TOTAL on the current field-ID page)","detection":"Any sustained increase. DCGM's PCIe health watch (`dcgmi health -s p`) warns above 8 PCIe replays per minute (DCGM feature overview, health monitoring), and the `dcgmi diag` PCIe test fails when replays during the test exceed `max_pcie_replays`, default 80 (DCGM diagnostics). These are watch and diagnostic criteria, not repair or RMA criteria; no vendor repair threshold was found.","strength":"suggestive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"name":"Slow rank with its PCIe link below maximum","source":"Artemis analysis, algorithm pending","identifier":"Likely cause: PCIe, because the link is below maximum generation or width","detection":"A flagged rank with the link below maximum. A hint, not a diagnosis. Rule: Pending.","strength":"Pending"}],"confounders":[{"failure":"idle power management downshift","how_to_distinguish":"GPUs lower link speed when idle; only a reading under load counts."},{"failure":"slot or riser wired for fewer lanes by design","how_to_distinguish":"Identical nodes in the same SKU show the same width: it is the platform, not a fault. Compare against peers before ticketing."},{"failure":"fabric.pcie_aer_errors","how_to_distinguish":"A link that retrained down after errors usually shows AER correctable errors or replays first; a link that came up narrow at boot may show none."},{"failure":"gpu.persistent_slow_gpu","how_to_distinguish":"Boundary: a slow GPU whose link, read under load, is below its maximum width or generation is this entry. A slow GPU whose link is at maximum stays gpu.persistent_slow_gpu."}],"diagnosis":"A device whose current width or generation is below both its maximum and identical peers, while loaded, is degraded; that rank being flagged slow raises it to the leading hypothesis. Confirm by measuring host-to-device (or NIC) bandwidth against a peer node. Only a reseat/replace followed by a matched bandwidth test and the link at maximum confirms the repair.","fixes":[{"fix":"rebalance_work","when":"The job opted in to rebalancing and the slow rank is persistent; mitigates the slowdown without repairing the link.","order":1},{"fix":"cordon_node","when":"Degraded link confirmed against peers; keep new jobs off until repaired.","order":2},{"fix":"node_reboot","when":"Drained node; a reboot retrains the link and may restore width if the fault was transient (not verified from a vendor source).","order":3},{"fix":"rma_replace_hardware","when":"Link stays degraded after reboot: reseat or replace the GPU, NIC or riser.","order":4}],"human_role":"cluster operator approves the reboot; data-center technician (reseat card or riser); vendor RMA for a faulty device","verification":{"remeasure":"After rebalance: the job's samples/s over 3 matched windows; after repair: current link width/generation equal maximum under load over an observation window (length: Pending), and the rank's step time back within the peer median.","post_repair_check":"dcgmi diag -r 2 -i \u003cgpu ids> (pcie test, on the affected GPU) passes; host-device bandwidth (DCGM pcie test or nvbandwidth) matches peer nodes; for a NIC, perftest ib_write_bw matches peers."},"escalation_steps":["Record current vs maximum width and generation for the device and its upstream bridge port (lspci or node_pcidevice_*), under load.","Compare with the same slot on identical nodes to rule out platform wiring.","Check the kernel log and aer_dev_* files for errors on the device and its root port.","Reseat the device or riser; if still degraded, swap slots to separate device from slot, then RMA the faulty part."],"references":[{"title":"DCGM field identifiers","url":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"title":"dcgm-exporter default counters","url":"https://github.com/NVIDIA/dcgm-exporter/blob/main/etc/default-counters.csv"},{"title":"node_exporter pcidevice collector","url":"https://github.com/prometheus/node_exporter/blob/master/collector/pcidevice_linux.go"},{"title":"DCGM diagnostics","url":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/dcgm-diagnostics.html"},{"title":"DCGM feature overview: health monitoring","url":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/feature-overview.html"}]},{"id":"fabric.pcie_aer_errors","domain":"fabric","name":"PCIe AER errors on a GPU, NIC or their upstream port","summary":"The PCIe link reports Advanced Error Reporting errors. Correctable errors are fixed in hardware but signal a marginal link; non-fatal uncorrectable errors make a transaction unreliable; fatal errors make the link unreliable and can take the device off the bus (Xid 79 for a GPU), crashing the job.","job_effect":["crash","slowdown","latent"],"blast_radius":"node","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"AER counters per device","source":"node_exporter / OS","identifier":"/sys/bus/pci/devices/\u003cdev>/aer_dev_correctable (TOTAL_ERR_COR), aer_dev_nonfatal (TOTAL_ERR_NONFATAL), aer_dev_fatal (TOTAL_ERR_FATAL)","detection":"Correctable: rising rate against peers (no kernel threshold; site policy). Non-fatal or fatal: any increase. The ABI notes errors may be counted at the link partner (root port), not the faulty endpoint, so read both ends.","strength":"strong","ref":"https://www.kernel.org/doc/Documentation/ABI/testing/sysfs-bus-pci-devices-aer_stats"},{"name":"AER kernel messages","source":"Kernel log","identifier":"'PCIe Bus Error: severity=Corrected|Uncorrectable (Non-Fatal)|Uncorrectable (Fatal), type=..., (Requester ID) \u003cbdf>'","detection":"Any Uncorrectable line; Corrected lines are rate-limited by the kernel (10 events per 5 s by default), so counts from the log undercount.","strength":"strong","ref":"https://docs.kernel.org/PCI/pcieaer-howto.html"},{"name":"GPU fallen off the bus","source":"Kernel log","identifier":"Xid 79 ROBUST_CHANNEL_GPU_HAS_FALLEN_OFF_THE_BUS","detection":"Any occurrence. Shows the GPU was lost from the bus, not that the link caused it: the Xid catalog says 'often caused by hardware failures on the PCI Express link' but also lists GPU hardware and driver causes; resolution bucket RESTART_BM. A link fault is confirmed by fatal or non-fatal AER on the GPU or its upstream port before the loss, a link that retrains below its maximum width or speed, or a fault that follows the slot or riser rather than the GPU in a swap test.","strength":"strong","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"name":"GPU-side PCIe correctable errors","source":"DCGM","identifier":"DCGM_FI_DEV_PCIE_CORRECTABLE_ERROR_TOTAL (1501)","detection":"Rising rate. The field page lists the id without a usable description; treat semantics as unconfirmed.","strength":"suggestive","ref":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"}],"confounders":[{"failure":"gpu.inaccessible_fallen_off_bus","how_to_distinguish":"NVIDIA's Xid catalog says Xid 79 can also come from failing GPU hardware or driver issues. AER errors on the root port before the Xid point at the link; a clean link history points at the GPU. Boundary: the lost GPU is tracked as gpu.inaccessible_fallen_off_bus; this entry is the link's error history."},{"failure":"fabric.pcie_link_degraded","how_to_distinguish":"A link may degrade with or without AER errors; check width and AER together."}],"diagnosis":"Xid 79 alone shows the GPU was lost, not why. Fatal or non-fatal AER on the device or its root port, followed by Xid 79 or a device disappearing, confirms a PCIe link failure as the proximate cause. Correctable-error rates only rank the link as at risk. Which end is faulty needs swap testing; the counters can sit at the partner.","fixes":[{"fix":"exclude_and_restart","when":"The job crashed on the node (Xid 79 or device lost).","order":1},{"fix":"drain_node","when":"Any uncorrectable error, or correctable rate well above peers.","order":2},{"fix":"node_reboot","when":"Xid 79: NVIDIA's Xid catalog resolution is a bare-metal restart.","order":3},{"fix":"schedule_firmware_update","when":"Vendor advisory ties the errors to BIOS, retimer or device firmware.","order":4},{"fix":"rma_replace_hardware","when":"Errors recur after reboot: reseat, swap slot, then replace device, riser or board.","order":5}],"human_role":"cluster operator approves the reboot; data-center technician; vendor RMA","verification":{"remeasure":"After reboot or repair: zero uncorrectable AER and correctable rate at peer level over a period of load (length: Pending); no Xid 79.","post_repair_check":"dcgmi diag -r 3 -i \u003cgpu ids> on the GPUs behind the port passes; aer_dev_* totals unchanged across the diagnostic run; device at full PCIe width and speed."},"escalation_steps":["Read aer_dev_correctable/nonfatal/fatal on the device and on its upstream root/switch port.","Collect the kernel AER lines with the decoded error bits and TLP header.","Check BMC/SEL logs for PCIe or riser events around the same time.","Reseat, then swap the device to another slot to see whether errors follow the device or the slot; RMA the faulty part."],"references":[{"title":"Linux ABI: PCIe device AER statistics","url":"https://www.kernel.org/doc/Documentation/ABI/testing/sysfs-bus-pci-devices-aer_stats"},{"title":"Linux PCIe AER howto","url":"https://docs.kernel.org/PCI/pcieaer-howto.html"},{"title":"NVIDIA Xid catalog (analyzing Xid errors)","url":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"title":"Revisiting Reliability in Large-Scale ML Research Clusters (Meta)","url":"https://arxiv.org/abs/2410.21680"}]},{"id":"fabric.ib_roce_physical_errors","domain":"fabric","name":"IB/RoCE port physical-layer errors: degrading cable or optic, rising BER","summary":"A NIC or switch port keeps its link up but its physical layer degrades: symbol errors, link-error recoveries, receive errors, rising pre-FEC BER, or optic power and temperature drifting (a dirty or failing cable or transceiver). Packets are corrected, retried or dropped, so the job sees slower and noisier inter-node communication, and the link may later flap or go down.","job_effect":["slowdown","latent"],"blast_radius":"link","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"InfiniBand PMA link-integrity counters","source":"InfiniBand counters","identifier":"/sys/class/infiniband/\u003cdev>/ports/\u003cp>/counters/symbol_error, link_error_recovery, port_rcv_errors, port_rcv_remote_physical_errors, local_link_integrity_errors (node_exporter: node_infiniband_symbol_error_total, node_infiniband_link_error_recovery_total, ...)","detection":"Rate against the port's own history and peers. ibqueryerrors' default threshold is 0 and its man page shows 'SymbolErrorCounter=10' and 'LinkErrorRecoveryCounter=10' only as threshold-file examples; there is no vendor default to quote. These PMA counters saturate (symbol_error 16-bit, link_error_recovery 8-bit, per the kernel's sysfs.c) and must be read as deltas. On links running link-level retransmission (LLR), such as FDR links with Mellanox's proprietary LLR, the retransmission masks symbol errors, so symbol_error can show no errors on a degrading link (MLNX_OFED InfiniBand fabric utilities); on those links a flat symbol_error does not clear the port, and the BER check below still applies.","strength":"strong","ref":"https://www.kernel.org/doc/Documentation/ABI/stable/sysfs-class-infiniband"},{"name":"Fabric-wide BER check","source":"Switch / fabric","identifier":"ibdiagnet --get_phy_info (after ibdiagnet --pc --reset_phy_info and a 5-10 minute wait); errors in ibdiagnet2.log ('Symbol BER Check finished with errors') and db_csv section START_ERRORS_SYMBOL_BER_CHECK, event BER_EXCEEDS_THRESHOLD","detection":"Any port reported BER_EXCEEDS_THRESHOLD. The manual's only documented default is 10^-12 for the deprecated --ber_test; the 5e-12 in its sample output is not a documented default.","strength":"strong","ref":"https://networking-docs.nvidia.com/ibdiagnetutilityum/2.26.0/bit-error-rate-ber"},{"name":"RoCE (mlx5) PHY counters","source":"ethtool / netdev","identifier":"ethtool -S \u003cnetdev>: rx_pcs_symbol_err_phy (symbol errors not corrected by FEC), rx_corrected_bits_phy, rx_bits_phy, rx_symbol_err_phy, rx_crc_errors_phy","detection":"Any increase of uncorrected symbol or CRC errors; corrected-bits rate rising against history. mlx5 names; other drivers differ.","strength":"strong","ref":"https://docs.kernel.org/networking/device_drivers/ethernet/mellanox/mlx5/counters.html"},{"name":"Optic diagnostics (DOM)","source":"ethtool / netdev","identifier":"ethtool -m \u003cnetdev> (--module-info): decodes module EEPROM and, where driver and module support it, optical diagnostics","detection":"Rx/Tx power or temperature drifting toward the module's own alarm/warning thresholds read from the same EEPROM; the thresholds are module-specific, not a fixed value. Privileged read.","strength":"suggestive","ref":"https://man7.org/linux/man-pages/man8/ethtool.8.html"},{"name":"Local NIC analysis of link errors","source":"Artemis analysis, algorithm pending","identifier":"Local NIC analysis of these counters. Rule: Pending","detection":"Pending","strength":"Pending"}],"confounders":[{"failure":"fabric.congestion_pfc_ecn","how_to_distinguish":"Congestion raises port_xmit_wait, pause and CNP counters with no symbol or CRC errors; physical errors raise symbol/CRC counters even at low load."},{"failure":"remote end of the link","how_to_distinguish":"port_rcv_remote_physical_errors counts packets already marked bad upstream; errors seen only at one end and not its partner point at that direction's transmitter, cable or receiver. A local collector cannot see the switch side."}],"diagnosis":"Physical-error counters rising on one port while its peers on the same switch stay flat rank the cable/optic/port as the leading hypothesis; a BER check exceeding threshold on that port confirms the link is out of spec. Which component (cable, transceiver, NIC, switch port) is faulty is only confirmed by swapping and re-measuring.","fixes":[{"fix":"reroute_traffic","when":"The bad link is inside the fabric (switch-switch) and adaptive routing or the SM can route around it.","order":1},{"fix":"cordon_node","when":"The bad link is the host's own NIC link; no new jobs until repaired.","order":2},{"fix":"reseat_or_replace_cable","when":"In a maintenance window: clean/reseat, then replace the cable or transceiver.","order":3},{"fix":"rma_replace_hardware","when":"Errors persist with a known-good cable: replace the NIC or switch port module.","order":4}],"human_role":"network engineer (fabric routing); data-center technician (cable and optic work)","verification":{"remeasure":"After repair: zero symbol/CRC error increase and BER below threshold over the ibdiagnet reset-wait-read cycle, then over a period of load (length: Pending).","post_repair_check":"ibdiagnet --get_phy_info reports no BER_EXCEEDS_THRESHOLD on the port; perftest ib_write_bw between the node and a peer reaches line rate; port at full width and speed."},"escalation_steps":["Identify both ends of the link (host NIC port and switch port) from the topology or ibdiagnet output.","Read the PMA counters at both ends and the module DOM (ethtool -m) for power and temperature.","Clean and reseat the connector; re-run the BER check.","Replace the cable/transceiver; if errors persist, move the cable to another switch port to separate NIC from switch port, then replace the faulty component."],"references":[{"title":"Linux ABI: sysfs-class-infiniband","url":"https://www.kernel.org/doc/Documentation/ABI/stable/sysfs-class-infiniband"},{"title":"ibdiagnet: Bit Error Rate (BER)","url":"https://networking-docs.nvidia.com/ibdiagnetutilityum/2.26.0/bit-error-rate-ber"},{"title":"ibqueryerrors(8)","url":"https://man.archlinux.org/man/ibqueryerrors.8.en"},{"title":"MLNX_OFED: InfiniBand fabric utilities (LLR and symbol errors)","url":"https://networking-docs.nvidia.com/mlnxofedswum/24010331/infiniband+fabric+utilities"},{"title":"Linux mlx5 ethtool counters","url":"https://docs.kernel.org/networking/device_drivers/ethernet/mellanox/mlx5/counters.html"},{"title":"ethtool(8)","url":"https://man7.org/linux/man-pages/man8/ethtool.8.html"},{"title":"node_exporter infiniband collector","url":"https://github.com/prometheus/node_exporter/blob/master/collector/infiniband_linux.go"},{"title":"MegaScale: Scaling LLM Training to More Than 10,000 GPUs","url":"https://arxiv.org/abs/2402.15627"},{"title":"Revisiting Reliability in Large-Scale ML Research Clusters (Meta)","url":"https://arxiv.org/abs/2410.21680"}]},{"id":"fabric.link_flapping","domain":"fabric","name":"IB/RoCE link flapping (down and up within seconds)","summary":"A NIC link repeatedly goes down and comes back after a few seconds. Packets in flight are dropped; if the outage outlasts the transport's retry budget NCCL returns a completion error and the job crashes, otherwise the job stalls and slows.","job_effect":["crash","hang","slowdown"],"blast_radius":"link","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Link-down counters","source":"InfiniBand counters","identifier":"/sys/class/infiniband/\u003cdev>/ports/\u003cp>/counters/link_downed ('failed the link error recovery process and downed the link'); RoCE: ethtool -S link_down_events_phy","detection":"Any increase while the port is meant to be up; repeats within a short period are a flap pattern (site policy).","strength":"definitive","ref":"https://www.kernel.org/doc/Documentation/ABI/stable/sysfs-class-infiniband"},{"name":"Port state transitions","source":"Artemis analysis, algorithm pending","identifier":"Local NIC analysis of port state. Rule: Pending","detection":"Pending","strength":"Pending"},{"name":"NCCL network error after retry budget","source":"NCCL","identifier":"NCCL_IB_TIMEOUT (default 20 since NCCL 2.23) and NCCL_IB_RETRY_CNT (default 7): about 30 s of retrying before NCCL raises a network error","detection":"A job error from the IB transport shortly after a link_downed increment. The exact NCCL error text is version-specific and not quoted here.","strength":"strong","ref":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/env.html"}],"confounders":[{"failure":"fabric.switch_failure","how_to_distinguish":"Many hosts' links dropping at the same moment point at the switch; one port flapping repeatedly points at its cable, optic or NIC."},{"failure":"planned maintenance or a reboot of the peer switch","how_to_distinguish":"Check the change calendar and switch logs for reboots before ticketing the cable."}],"diagnosis":"Repeated link_downed or link_down_events_phy increments on one port, with job failures or stalls aligned to them, confirm flapping as the cause of those failures. The root cause (cable, optic, NIC, switch port) needs the physical-error evidence of fabric.ib_roce_physical_errors and swap testing.","fixes":[{"fix":"cordon_node","when":"The flapping port is a host NIC port; before any exclude_and_restart off the host.","order":1},{"fix":"exclude_and_restart","when":"The job failed or keeps stalling on the flapping link.","order":2},{"fix":"tune_job_configuration","when":"Short, rare flaps on otherwise healthy links: raise NCCL_IB_TIMEOUT so the transport outlasts the outage (MegaScale's lesson); this hides, not repairs, the fault.","order":3},{"fix":"reseat_or_replace_cable","when":"Maintenance window; then RMA the NIC or switch port if flapping persists.","order":4}],"human_role":"data-center technician (cable/optic); network engineer (switch side)","verification":{"remeasure":"No link_downed increment over a period of load after repair (length: Pending); the restarted job runs without IB transport errors.","post_repair_check":"ibdiagnet shows the port clean; perftest ib_write_bw sustained at line rate (length: Pending) with no link_downed increment."},"escalation_steps":["List the flap times from link_downed / link_down_events_phy and the switch port log for the same port.","Correlate with physical-error counters and DOM readings on both ends.","Reseat or replace the cable or optic; move to another switch port if flapping continues.","Replace the NIC or switch port module if the fault follows it."],"references":[{"title":"Linux ABI: sysfs-class-infiniband","url":"https://www.kernel.org/doc/Documentation/ABI/stable/sysfs-class-infiniband"},{"title":"Linux mlx5 ethtool counters","url":"https://docs.kernel.org/networking/device_drivers/ethernet/mellanox/mlx5/counters.html"},{"title":"NCCL environment variables","url":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/env.html"},{"title":"MegaScale: Scaling LLM Training to More Than 10,000 GPUs","url":"https://arxiv.org/abs/2402.15627"}]},{"id":"fabric.port_down_or_degraded_rate","domain":"fabric","name":"NIC port down, or up at reduced width or speed","summary":"A NIC port stays down, or trains at a lower width or speed than it should (e.g. 1X instead of 4X, or a lower signalling rate). A down port removes the rail; a degraded port caps that rank's inter-node bandwidth, making it a communication straggler.","job_effect":["slowdown","crash","capacity_loss"],"blast_radius":"link","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Port state and rate","source":"InfiniBand counters","identifier":"/sys/class/infiniband/\u003cdev>/ports/\u003cp>/state (DOWN, INIT, ARMED, ACTIVE, ACTIVE_DEFER), phys_state (Sleep, Polling, LinkUp, ...), rate ('active width * active speed'); ibstat (port state, link width active, physical state)","detection":"State not ACTIVE or phys_state not LinkUp on a cabled port; rate below the value of identical ports.","strength":"definitive","ref":"https://www.kernel.org/doc/Documentation/ABI/stable/sysfs-class-infiniband"},{"name":"Port rate below its own recent maximum","source":"Artemis analysis, algorithm pending","identifier":"Port rate below its own recent maximum","detection":"Window and threshold: Pending","strength":"Pending"},{"name":"Local NIC analysis of port state and rate","source":"Artemis analysis, algorithm pending","identifier":"Local NIC analysis of these counters. Rule: Pending","detection":"Pending","strength":"Pending"}],"confounders":[{"failure":"fabric.subnet_manager_routing_fault","how_to_distinguish":"State INIT with phys_state LinkUp means the physical link trained but the port was not activated; that is the SM's job, not a cable fault."},{"failure":"port administratively disabled or not cabled by design","how_to_distinguish":"Compare against the node's inventory of expected rails; a port that has never been ACTIVE is a build issue."}],"diagnosis":"A down port (phys_state not LinkUp) or a rate below identical ports confirms the condition directly. The cause (cable, optic, NIC, switch port, auto-negotiation) is ranked by physical-error counters and DOM, and confirmed by swap testing.","fixes":[{"fix":"cordon_node","when":"Until the port is restored; before any exclude_and_restart off the host.","order":1},{"fix":"exclude_and_restart","when":"A job depends on the rail (NCCL errors or a communication straggler on that rank).","order":2},{"fix":"reseat_or_replace_cable","when":"Port down or degraded with a physical cause suspected.","order":3},{"fix":"rma_replace_hardware","when":"Still down or degraded with a known-good cable and switch port.","order":4}],"human_role":"data-center technician; network engineer for the switch port","verification":{"remeasure":"Port ACTIVE/LinkUp at the expected width and speed over an observation window (length: Pending); the rank's communication time back within the peer median.","post_repair_check":"ibstat shows expected rate; perftest ib_write_bw to a peer at line rate; nccl-tests all_reduce_perf across two nodes matches peer pairs."},"escalation_steps":["Record state, phys_state and rate for every NIC port; compare with the expected rail count and speed.","Check the switch side of the port for errors, disablement or speed configuration.","Reseat and swap the cable; then swap switch ports; then replace the NIC.","Re-run the bandwidth test before returning the node."],"references":[{"title":"Linux ABI: sysfs-class-infiniband","url":"https://www.kernel.org/doc/Documentation/ABI/stable/sysfs-class-infiniband"},{"title":"ibstat(8)","url":"https://man.archlinux.org/man/ibstat.8.en"}]},{"id":"fabric.switch_failure","domain":"fabric","name":"Leaf or spine switch failure or reboot","summary":"A switch fails, reboots or loses a line card. Every host link on a failed leaf goes down at once; a failed spine removes uplink capacity and forces traffic onto fewer paths. Jobs with ranks under the leaf crash or hang; jobs crossing the spine slow down.","job_effect":["crash","hang","slowdown","capacity_loss"],"blast_radius":"switch_rack","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Simultaneous port loss on many hosts","source":"InfiniBand counters","identifier":"link_downed increments and state DOWN on the ports of all hosts cabled to one switch at the same time (per-host sysfs counters, joined by topology)","detection":"Several hosts sharing one leaf losing their port within the same minute. Needs a host-to-switch-port map.","strength":"strong","ref":"https://www.kernel.org/doc/Documentation/ABI/stable/sysfs-class-infiniband"},{"name":"Fabric-wide error sweep","source":"Switch / fabric","identifier":"ibqueryerrors (port error counters over the threshold, for each port in the fabric) and ibdiagnet","detection":"Errors or missing links concentrated on one switch's ports.","strength":"strong","ref":"https://man.archlinux.org/man/ibqueryerrors.8.en"},{"name":"Correlated scheduler failures","source":"Scheduler","identifier":"Slurm job state NF NODE_FAIL or many jobs failing on nodes under one switch; node state with '*' (not responding) if management also crosses the switch","detection":"Failures clustered by switch rather than by node.","strength":"suggestive","ref":"https://slurm.schedmd.com/squeue.html"}],"confounders":[{"failure":"rack power or cooling event (host domain)","how_to_distinguish":"A rack PDU event takes the hosts down too (BMC/IPMI shows power loss); a switch failure leaves hosts up with their fabric ports down."},{"failure":"fabric.subnet_manager_routing_fault","how_to_distinguish":"SM faults leave links physically up (phys_state LinkUp) but ports not ACTIVE or routes wrong; a dead switch drops the physical links."}],"diagnosis":"Port loss on all hosts of one leaf, at the same moment, with the switch unreachable in ibdiagnet or its management, confirms a switch fault. One host's port alone is not this failure. A spine fault shows as lost uplinks and reduced fabric bandwidth, visible in ibdiagnet and as cross-leaf slowdowns.","fixes":[{"fix":"cordon_node","when":"Hosts under the failed leaf, until the switch is restored; before any exclude_and_restart moves jobs off them.","order":1},{"fix":"exclude_and_restart","when":"Running jobs had ranks under the failed leaf.","order":2},{"fix":"reroute_traffic","when":"A spine or uplink failed and the SM/adaptive routing can rebalance onto remaining paths.","order":3},{"fix":"rma_replace_hardware","when":"Switch, line card or PSU confirmed faulty.","order":4}],"human_role":"network engineer; vendor RMA","verification":{"remeasure":"All host ports under the switch ACTIVE at expected rate; restarted jobs' step time within their pre-incident baseline.","post_repair_check":"ibdiagnet clean for the switch and its links; nccl-tests all_reduce_perf across the leaf matches other leaves."},"escalation_steps":["Map affected hosts to switch ports and confirm they share one switch.","Check the switch's own logs, PSU and fan state through its management interface.","Run ibdiagnet to list missing links and switches.","Replace the failed component; re-run the fabric sweep before the hosts' holds are released."],"references":[{"title":"Linux ABI: sysfs-class-infiniband","url":"https://www.kernel.org/doc/Documentation/ABI/stable/sysfs-class-infiniband"},{"title":"ibqueryerrors(8)","url":"https://man.archlinux.org/man/ibqueryerrors.8.en"},{"title":"Slurm squeue","url":"https://slurm.schedmd.com/squeue.html"},{"title":"The Llama 3 Herd of Models, Table 5","url":"https://arxiv.org/abs/2407.21783"}]},{"id":"fabric.congestion_pfc_ecn","domain":"fabric","name":"Network congestion, PFC pause storms and ECN/CNP marking","summary":"Traffic from this job or other jobs exceeds a link's or switch's capacity. On RoCE, PFC pauses back-pressure senders (and can spread head-of-line blocking); DCQCN marks ECN and NICs send CNPs to slow down. On IB, credit starvation shows as transmit wait. The job's collectives slow down, unevenly across ranks.","job_effect":["slowdown"],"blast_radius":"switch_rack","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"InfiniBand transmit wait","source":"InfiniBand counters","identifier":"/sys/class/infiniband/\u003cdev>/ports/\u003cp>/counters/port_xmit_wait ('ticks during which the port had data to transmit but no data was sent ... insufficient credits or lack of arbitration'); port_xmit_discards ('down or congested')","detection":"Rate against the port's own baseline; tick length is device-defined, so absolute values are not comparable across devices.","strength":"suggestive","ref":"https://www.kernel.org/doc/Documentation/ABI/stable/sysfs-class-infiniband"},{"name":"RoCE PFC pause counters and storm events","source":"ethtool / netdev","identifier":"ethtool -S: rx_prio\u003cp>_pause, tx_prio\u003cp>_pause, rx_prio\u003cp>_pause_duration and tx_prio\u003cp>_pause_duration (microseconds), tx_pause_storm_warning_events, tx_pause_storm_error_events, rx_discards_phy, rx_buffer_passed_thres_phy (receive buffer over 85% full)","detection":"Any tx_pause_storm_error_events (device stopped sending pauses after a timeout); pause duration share of wall time rising against baseline. mlx5 names.","strength":"strong","ref":"https://docs.kernel.org/networking/device_drivers/ethernet/mellanox/mlx5/counters.html"},{"name":"ECN/CNP congestion counters","source":"InfiniBand counters","identifier":"/sys/class/infiniband/\u003cdev>/ports/\u003cp>/hw_counters/np_ecn_marked_roce_packets, np_cnp_sent, rp_cnp_handled, rp_cnp_ignored (mlx5 congestion counters)","detection":"Rate above the port's own baseline. Threshold: Pending. Counter names from the kernel mlx5 driver source; no NVIDIA page defining them was found.","strength":"suggestive","ref":"https://github.com/torvalds/linux/blob/master/drivers/infiniband/hw/mlx5/counters.c"},{"name":"Local NIC congestion analysis","source":"Artemis analysis, algorithm pending","identifier":"Local NIC analysis of these counters. Rule: Pending","detection":"Pending","strength":"Pending"}],"confounders":[{"failure":"slow remote receiver (receiver starvation)","how_to_distinguish":"RNR NAK and out_of_buffer counters rise with a starved receiver; when both congestion and starvation signals appear, the counters alone do not separate them."},{"failure":"another tenant on the same port or switch","how_to_distinguish":"Another job's traffic on the port; congestion follows that job's schedule."},{"failure":"fabric.ib_roce_physical_errors","how_to_distinguish":"Retransmits from a bad link raise symbol/CRC errors; congestion does not."}],"diagnosis":"Transmit-wait, pause or CNP rates above the port's own baseline during the slowdown point at congestion. Attribution rule: Pending. A local NIC view cannot place congestion inside the fabric; confirming it needs switch-side counters or a controlled test that removes the competing traffic.","fixes":[{"fix":"reroute_traffic","when":"Hot paths are identifiable (switch counters, ECMP collisions): adaptive routing, traffic engineering (as in Alibaba C4P) or topology-aware placement.","order":1},{"fix":"correct_fabric_configuration","when":"PFC/ECN thresholds or traffic classes are misconfigured, or pause storms recur.","order":2},{"fix":"tune_job_configuration","when":"The job's own traffic pattern causes it: e.g. NCCL traffic class (NCCL_IB_TC) or adaptive-routing settings (NCCL_IB_ADAPTIVE_ROUTING is on by default on IB and off on RoCE).","order":3}],"human_role":"network engineer","verification":{"remeasure":"Over matched windows before and after: pause duration share, CNP rate and port_xmit_wait back near baseline, and the job's communication time per step back within its pre-incident value.","post_repair_check":"Not a hardware repair: a multi-node nccl-tests all_reduce_perf at the job's scale shows expected bus bandwidth with no pause-storm events."},"escalation_steps":["Collect per-priority pause durations, storm events and CNP counters from the affected hosts, and switch-side buffer and ECN statistics.","Identify which jobs share the congested links (placement map).","Check PFC/ECN configuration consistency across switches and NICs for the RoCE traffic class.","Change routing or placement and re-measure under the same load."],"references":[{"title":"Linux ABI: sysfs-class-infiniband","url":"https://www.kernel.org/doc/Documentation/ABI/stable/sysfs-class-infiniband"},{"title":"Linux mlx5 ethtool counters","url":"https://docs.kernel.org/networking/device_drivers/ethernet/mellanox/mlx5/counters.html"},{"title":"Linux mlx5 RDMA counters (driver source)","url":"https://github.com/torvalds/linux/blob/master/drivers/infiniband/hw/mlx5/counters.c"},{"title":"NCCL environment variables","url":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/env.html"},{"title":"MegaScale: Scaling LLM Training to More Than 10,000 GPUs","url":"https://arxiv.org/abs/2402.15627"},{"title":"C4: real-time anomaly detection and communication optimization (Alibaba)","url":"https://arxiv.org/abs/2406.04594"}]},{"id":"fabric.rdma_transport_retries","domain":"fabric","name":"RDMA transport retries, ACK timeouts and RNR on the job's queue pairs","summary":"The RDMA transport retransmits because acknowledgements time out or the receiver has no buffer posted (RNR). Retries slow the transfer; when the retry budget is exhausted the work request completes with an error (e.g. IBV_WC_RETRY_EXC_ERR) and NCCL fails the job.","job_effect":["slowdown","crash"],"blast_radius":"link","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Retry and timeout counters (mlx5 Q counters)","source":"InfiniBand counters","identifier":"hw_counters/local_ack_timeout_err, req_transport_retries_exceeded, packet_seq_err, out_of_sequence, implied_nak_seq_err, rnr_nak_retry_err, req_rnr_retries_exceeded, out_of_buffer","detection":"Retries exceeded: any increase. Ack timeouts and sequence errors: rate against baseline. Thresholds for sustained retries or a starved receiver: Pending.","strength":"strong","ref":"https://github.com/torvalds/linux/blob/master/drivers/infiniband/hw/mlx5/counters.c"},{"name":"Completion errors","source":"InfiniBand counters","identifier":"hw_counters/req_cqe_error, resp_cqe_error, req_cqe_flush_error, resp_cqe_flush_error, req_remote_access_errors","detection":"Any increase not explained by teardown (flushes during QP teardown are expected).","strength":"suggestive","ref":"https://github.com/prometheus/node_exporter/blob/master/collector/infiniband_linux.go"},{"name":"NCCL retry budget","source":"NCCL","identifier":"NCCL_IB_TIMEOUT (4.096 us * 2^timeout; default 20) and NCCL_IB_RETRY_CNT (default 7)","detection":"Failures arrive about 30 s after the path stops responding at defaults.","strength":"suggestive","ref":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/env.html"},{"name":"Retries, errors or a starved receiver","source":"Artemis analysis, algorithm pending","identifier":"Local NIC analysis of retry, error and starvation counters, and work completions with status IBV_WC_RETRY_EXC_ERR or IBV_WC_RNR_RETRY_EXC_ERR. Rule: Pending","detection":"Pending","strength":"Pending"}],"confounders":[{"failure":"fabric.link_flapping","how_to_distinguish":"Retries that cluster around link_downed increments are the flap, not a transport problem."},{"failure":"a stalled or dead peer process","how_to_distinguish":"A peer that stopped (crash, hang) makes every QP to it time out; NCCL RAS or a hang or missing-rank finding shows the peer process dead or unresponsive."},{"failure":"fabric.congestion_pfc_ecn","how_to_distinguish":"Heavy congestion can cause ack timeouts; check pause/CNP counters for the same windows."}],"diagnosis":"Retries exceeded on the job's port point at the path to the peer (rule: Pending). RNR with out_of_buffer points at this node's receiver, RNR NAK counters at the peer's. Whether the root is a link, a congested fabric or a stalled peer needs the link counters and the peer's state.","fixes":[{"fix":"exclude_and_restart","when":"The job failed with retries exhausted and the counters localize one node's port.","order":1},{"fix":"run_active_diagnostic","when":"Before returning the node: perftest between the node and peers, ibdiagnet on its links.","order":2},{"fix":"tune_job_configuration","when":"Retries are transient (short flaps): raise NCCL_IB_TIMEOUT; a mitigation, not a repair.","order":3}],"human_role":"network engineer","verification":{"remeasure":"After restart: zero req_transport_retries_exceeded and ack-timeout rate at baseline over a period of the job's traffic (length: Pending).","post_repair_check":"perftest ib_write_bw/ib_read_lat between the node and two peers at expected values with no retry-counter increase."},"escalation_steps":["Read retry, RNR and completion-error counters on both ends of the failing peer pair.","Check link counters (symbol errors, link_downed) and pause/CNP counters for the same window.","Check whether the peer process was alive (NCCL RAS status, scheduler state).","Run perftest between the pair; escalate to the physical or congestion entry by what it shows."],"references":[{"title":"Linux mlx5 RDMA counters (driver source)","url":"https://github.com/torvalds/linux/blob/master/drivers/infiniband/hw/mlx5/counters.c"},{"title":"node_exporter infiniband collector","url":"https://github.com/prometheus/node_exporter/blob/master/collector/infiniband_linux.go"},{"title":"NCCL environment variables","url":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/env.html"},{"title":"perftest","url":"https://github.com/linux-rdma/perftest"},{"title":"C4: real-time anomaly detection and communication optimization (Alibaba)","url":"https://arxiv.org/abs/2406.04594"}]},{"id":"fabric.subnet_manager_routing_fault","domain":"fabric","name":"Subnet manager down, failing over, or routing misconfigured","summary":"The InfiniBand subnet manager (SM) is absent, flapping between masters, or programs bad routes. Ports whose links trained stay in INIT and cannot carry traffic; new jobs fail to connect; existing traffic can be rerouted onto congested or broken paths after a sweep.","job_effect":["crash","slowdown","capacity_loss"],"blast_radius":"cluster","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Port physically up but not active","source":"InfiniBand counters","identifier":"ports/\u003cp>/state = INIT with phys_state = LinkUp; ibstat shows SM lid and base lid","detection":"Any cabled port in INIT for more than an SM sweep interval. The kernel ABI lists the states but not their meaning; that INIT means the SM has not yet activated the port is from a third-party knowledge-base page, not an NVIDIA document.","strength":"strong","ref":"https://kb.advancedclustering.com/kb/InfiniBand-Port-States.1074725608.html"},{"name":"SM state","source":"Switch / fabric","identifier":"sminfo (queries the SM listed in the local port info; states 0 not active, 1 discovering, 2 standby, 3 master)","detection":"No master, or the master changing repeatedly. The man page warns that using sminfo for anything but a query can break the SM.","strength":"definitive","ref":"https://man.archlinux.org/man/sminfo.8.en"},{"name":"Fabric routing and configuration sweep","source":"Switch / fabric","identifier":"ibdiagnet run (routing, link and counter checks; ibdiagnet2.log); excessive_buffer_overrun_errors on a port ('possible misconfiguration of a port, either by the Subnet Manager (SM) or by user intervention')","detection":"Routing errors reported by ibdiagnet; overrun errors rising.","strength":"strong","ref":"https://www.kernel.org/doc/Documentation/ABI/stable/sysfs-class-infiniband"}],"confounders":[{"failure":"fabric.port_down_or_degraded_rate","how_to_distinguish":"A cable or optic fault leaves phys_state not LinkUp; an SM fault leaves the physical link up."},{"failure":"fabric.congestion_pfc_ecn","how_to_distinguish":"Bad routing concentrates flows on few links, which looks like congestion; ibdiagnet's routing checks and the SM log separate them."}],"diagnosis":"Ports in INIT with LinkUp across hosts, plus sminfo showing no master or repeated master changes, confirm an SM fault. Routing faults are confirmed by ibdiagnet's routing checks; congestion counters alone only correlate.","fixes":[{"fix":"correct_fabric_configuration","when":"The SM process is down, wedged or flapping: a network engineer restarts it or fails over to a standby SM in a controlled way; or the routing engine or SM configuration is wrong. The SM, UFM, switches and routing are shared fabric, so this never goes through the node-scoped restart_system_service.","order":1},{"fix":"exclude_and_restart","when":"Jobs lost connectivity and the fabric is now stable.","order":2}],"human_role":"network engineer (SM restart, failover and configuration); job owner approves restarts of affected jobs","verification":{"remeasure":"All cabled ports ACTIVE; one stable master SM over an observation window (length: Pending); jobs connect and cross-node bandwidth matches baseline.","post_repair_check":"ibdiagnet clean; nccl-tests all_reduce_perf across racks at expected bus bandwidth."},"escalation_steps":["Check SM state on every SM host (sminfo) and the SM log for errors and master changes.","List ports in INIT with LinkUp across the fabric.","Run ibdiagnet and review routing and duplicate-GUID/LID checks.","Restart or fail over the SM in a controlled way, then re-run the sweep."],"references":[{"title":"Linux ABI: sysfs-class-infiniband","url":"https://www.kernel.org/doc/Documentation/ABI/stable/sysfs-class-infiniband"},{"title":"sminfo(8)","url":"https://man.archlinux.org/man/sminfo.8.en"},{"title":"ibstat(8)","url":"https://man.archlinux.org/man/ibstat.8.en"},{"title":"InfiniBand port states (Advanced Clustering knowledge base, third-party)","url":"https://kb.advancedclustering.com/kb/InfiniBand-Port-States.1074725608.html"}]},{"id":"fabric.nic_gpu_affinity_misconfig","domain":"fabric","name":"Misconfigured rail, NIC selection or NIC-to-GPU affinity","summary":"The job uses the wrong network path: NCCL picks a NIC across the CPU socket from the GPU, uses fewer rails than exist, falls back to TCP sockets on a management interface, or crosses rails on a rail-optimized fabric. Nothing fails; inter-node collectives run well below expected bandwidth, often on every rank.","job_effect":["slowdown"],"blast_radius":"job","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"GPU-NIC topology","source":"NVML / nvidia-smi","identifier":"nvidia-smi topo -m (GPU-NIC matrix: PIX, PXB, PHB, NODE, SYS, NV#)","detection":"The NIC the rank uses is SYS (across the NUMA interconnect) or NODE from its GPU while a PIX/PXB NIC exists.","strength":"strong","ref":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"},{"name":"NCCL's selected devices and topology","source":"NCCL","identifier":"NCCL_DEBUG=INFO initialization log (which transport and NICs were selected); NCCL_TOPO_DUMP_FILE (XML topology as NCCL saw it); NCCL_IB_HCA and NCCL_SOCKET_IFNAME (interface filters); NCCL_CROSS_NIC (rail crossing)","detection":"Selected NICs differ from the intended rail map, or the network transport is sockets where IB was expected. Exact log line formats vary by NCCL version and are not quoted here.","strength":"definitive","ref":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/env.html"},{"name":"Uneven bytes across a node's NICs","source":"InfiniBand counters","identifier":"port_xmit_data / port_rcv_data per port (4-octet words), or per-port bytes per second by direction","detection":"During a job using all GPUs of the node, one port carries most bytes while other rails idle.","strength":"suggestive"}],"confounders":[{"failure":"fabric.port_down_or_degraded_rate","how_to_distinguish":"An idle rail may be down; check its state before blaming configuration."},{"failure":"job.perf_regression_after_change","how_to_distinguish":"A container or NCCL upgrade can change NIC selection; compare NCCL's selected devices before and after the change."},{"failure":"host.pcie_acs_iommu_misconfig","how_to_distinguish":"ACS or IOMMU translation also slows intra-node GPU-to-GPU traffic and shows in `lspci -vvv | grep ACSCtl` and the kernel IOMMU mode; NIC or rail selection affects only inter-node traffic and shows in `nvidia-smi topo -m` and NCCL's init log."}],"diagnosis":"NCCL's own record of selected devices against the node topology confirms the misconfiguration; uneven NIC bytes or a uniform cross-node slowdown only correlate. Confirm by rerunning nccl-tests with the corrected NCCL_IB_HCA/affinity and comparing bus bandwidth.","fixes":[{"fix":"tune_job_configuration","when":"Set NCCL_IB_HCA / NCCL_SOCKET_IFNAME / NCCL_CROSS_NIC and CPU/GPU binding to match the rail map; restart from checkpoint.","order":1},{"fix":"rollback_software_change","when":"A container, launcher or NCCL change introduced the wrong selection.","order":2}],"human_role":"job owner (job environment); cluster operator (site defaults)","verification":{"remeasure":"After restart: NCCL selects the intended NICs; the job's step time and samples/s over 3 matched windows improve against the misconfigured run.","post_repair_check":"Not a hardware repair: multi-node nccl-tests all_reduce_perf with the corrected settings at expected bus bandwidth."},"escalation_steps":["Capture nvidia-smi topo -m and NCCL_DEBUG=INFO output from one rank per node.","Compare selected NICs with the intended rail and NUMA map.","Check site and container defaults for NCCL_IB_HCA, NCCL_SOCKET_IFNAME and CPU binding.","Rerun nccl-tests with the corrected settings before changing the production job."],"references":[{"title":"nvidia-smi documentation","url":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"},{"title":"NCCL environment variables","url":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/env.html"},{"title":"NVIDIA nccl-tests","url":"https://github.com/NVIDIA/nccl-tests"}]},{"id":"fabric.slow_island_or_bridge_link","domain":"fabric","name":"Slow island or slow bridge link","summary":"The time of an island's collectives, or of the bridge between island leaders, rises over its warmup value while compute stays flat. This is a symptom-level finding: the cause may be a degraded NVLink/PCIe/NIC path, congestion, or contention on the hosts. The whole job waits on the slow path.","job_effect":["slowdown"],"blast_radius":"link","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Slow bridge link","source":"Artemis analysis, algorithm pending","identifier":"Bridge phase time between island leaders, against warmup. Scoring choice: Pending","detection":"Pending","strength":"Pending"},{"name":"Slow island collectives","source":"Artemis analysis, algorithm pending","identifier":"Island collective time, against warmup. Scoring choice: Pending","detection":"Pending","strength":"Pending"},{"name":"Slow island (compute and communication)","source":"Artemis analysis, algorithm pending","identifier":"Island pace against its warmup baseline","detection":"Island slowed relative to its warmup and other islands.","strength":"Pending"},{"name":"Local NIC evidence for the finding","source":"Artemis analysis, algorithm pending","identifier":"Pending","detection":"Pending","strength":"Pending"}],"confounders":[{"failure":"host.cpu_memory_contention","how_to_distinguish":"Host contention can look the same. Run-queue wait and throttling for the leader rank support or rule it out."},{"failure":"fabric.congestion_pfc_ecn","how_to_distinguish":"Congestion counters above baseline on the leaders' ports during the finding."},{"failure":"fabric.nvlink_link_errors","how_to_distinguish":"A slow island with NVLink counter increases on the island's GPUs."},{"failure":"job.warmup_imbalance","how_to_distinguish":"A path already slow at warmup shows no rise against warmup."},{"failure":"gpu.persistent_slow_gpu","how_to_distinguish":"A GPU slow in compute is gpu.persistent_slow_gpu; an island or link finding while compute stays flat names a path, not a GPU."},{"failure":"host.pcie_acs_iommu_misconfig","how_to_distinguish":"ACS enabled on the PCIe switches makes every PCIe P2P pair behind them slow at once, with `SrcValid+` in `lspci -vvv | grep ACSCtl`; the gap closes with `NCCL_P2P_DISABLE=1`. A degraded link is one path."}],"diagnosis":"The finding localizes the slowdown to a path (bridge or island) but does not name a cause. Rank causes by the evidence on that path: NVLink or PCIe counters for an island, NIC link/retry/congestion counters for the bridge, host telemetry for the leaders. Confirm with a path-level benchmark (nccl-tests on the island, perftest between leaders) before and after the fix.","fixes":[{"fix":"run_active_diagnostic","when":"First: benchmark the flagged path to separate a slow link from a busy host.","order":1},{"fix":"reroute_traffic","when":"The bridge path is congested or degraded and an alternate path exists.","order":2},{"fix":"exclude_and_restart","when":"A node on the path is confirmed degraded.","order":3}],"human_role":"cluster operator; network engineer for the bridge path","verification":{"remeasure":"The path finding clears and stays clear for several windows; at least 3 samples of throughput within 2% of the healthy value.","post_repair_check":"Path benchmark (nccl-tests within the island, perftest between leaders) matches peer paths."},"escalation_steps":["Read the incident report for the finding and the hosts of the ranks it names.","Pull NVLink/PCIe counters for an island finding, or both leaders' NIC counters for a bridge finding.","Check host telemetry for the leader ranks (run-queue wait, throttling).","Benchmark the path and route the ticket to the matching physical entry."],"references":[{"title":"The Llama 3 Herd of Models, section 3.3.4","url":"https://arxiv.org/abs/2407.21783"},{"title":"NVIDIA nccl-tests","url":"https://github.com/NVIDIA/nccl-tests"}]},{"id":"job.collective_hang_watchdog","domain":"job","name":"Collective hang ending in an NCCL watchdog timeout","summary":"One or more ranks stop making progress inside or before a collective; every other rank waits in the collective. With PyTorch's NCCL backend, the watchdog aborts collectives after the process-group timeout (10 minutes by default for NCCL) and tears the process down, so the job crashes after a long idle period. Causes range from a dead peer, a GPU or NVLink fault and a network failure to a software deadlock or mismatched collectives.","job_effect":["hang","crash"],"blast_radius":"job","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Process-group timeout and async error handling","source":"Job telemetry","identifier":"torch.distributed.init_process_group(timeout=...) (default 10 minutes for NCCL); TORCH_NCCL_ASYNC_ERROR_HANDLING (default 3: tear down the process without aborting the communicator); TORCH_NCCL_ENABLE_MONITORING with TORCH_NCCL_HEARTBEAT_TIMEOUT_SEC (abort when the watchdog itself is stuck)","detection":"A watchdog timeout or heartbeat-monitor abort in any rank's log. Detection latency equals the configured timeout.","strength":"definitive","ref":"https://docs.pytorch.org/docs/2.15/distributed.html"},{"name":"Flight recorder dump","source":"Job telemetry","identifier":"TORCH_NCCL_TRACE_BUFFER_SIZE > 0 with TORCH_NCCL_DUMP_ON_TIMEOUT (dump debug info on watchdog timeout); TORCH_NCCL_DESYNC_DEBUG (find the culprit rank of a collective desync)","detection":"On timeout, compare ranks' last collectives: the rank(s) that never entered the pending collective are the suspects.","strength":"strong","ref":"https://docs.pytorch.org/docs/2.15/torch_nccl_environment_variables.html"},{"name":"NCCL RAS job status","source":"NCCL","identifier":"ncclras client or 'echo verbose status | nc localhost 28028' (NCCL_RAS_ADDR); errors DEAD (process unreachable for 60 s), INCOMPLETE (missing communicator data), TIMEOUT; monitoring event PEER_DEAD","detection":"Any DEAD or INCOMPLETE entry names the process, node and GPU behind it. RAS is enabled by default (NCCL_RAS_ENABLE).","strength":"strong","ref":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/troubleshooting/ras.html"},{"name":"Hang finding: ranks stopped making progress","source":"Artemis analysis, algorithm pending","identifier":"Ranks show no progress, with some rank inside a collective or no longer reporting. Mechanism and interval: Pending","detection":"Intended to report before the NCCL timeout fires, naming the ranks behind and the collective or phase they are in where known.","strength":"Pending"}],"confounders":[{"failure":"fabric.nvlink_link_down","how_to_distinguish":"NVLink Xids (74, 144-150) on the node at the hang onset; Llama 3 notes NVLink failures appear as stalled kernels without a clear error."},{"failure":"fabric.rdma_transport_retries","how_to_distinguish":"Retries-exceeded and completion errors on the hung rank's NIC; NCCL raises a network error rather than waiting for the watchdog."},{"failure":"job.quiet_rank","how_to_distinguish":"A rank whose process died or whose node failed shows as DEAD in NCCL RAS and stops reporting; a software deadlock leaves all processes alive."},{"failure":"slow checkpoint or data stall on one rank","how_to_distinguish":"The rank is still progressing (timing shows a long input or checkpoint wait) and the hang resolves; a true hang has no progress on any rank."},{"failure":"host.pcie_acs_iommu_misconfig","how_to_distinguish":"ACS on bare metal can hang P2P collectives (NCCL troubleshooting); the hang recurs on the same node and stops with `NCCL_P2P_DISABLE=1` or ACS disabled."}],"diagnosis":"The watchdog or a hang finding confirms a hang, not its cause. Use the flight recorder and NCCL RAS to find the rank(s) that did not reach the collective; then look at that rank's node for hardware evidence (Xids, NIC counters, scheduler NODE_FAIL). No hardware evidence and all processes alive points at software (mismatched collectives, deadlock): TORCH_NCCL_DESYNC_DEBUG helps there. Repeated hangs naming the same node are strong evidence against that node.","fixes":[{"fix":"restart_from_checkpoint","when":"First hang with no localized hardware evidence.","order":1},{"fix":"exclude_and_restart","when":"The flight recorder, RAS or hardware signals name one node, or the same node appears in repeated hangs.","order":2},{"fix":"run_active_diagnostic","when":"On the excluded node before it returns to service.","order":3}],"human_role":"job owner (software deadlocks); cluster operator (node evidence)","verification":{"remeasure":"The restarted job passes the step at which it hung and runs past its previous time to hang, over an observation window (length: Pending), with no hang report; step time within its pre-incident baseline.","post_repair_check":"Excluded node: dcgmi diag -r 3 -i \u003cnode gpu ids> and a two-node nccl-tests all_reduce_perf with a known-good peer pass, neither node running a job."},"escalation_steps":["Collect the flight-recorder dumps and NCCL RAS verbose status from the hung job.","Identify ranks that never entered the pending collective and their nodes.","Check those nodes for Xids, NIC link and retry counters, and scheduler state at the hang onset.","If no hardware evidence, hand the dumps to the job owner with the mismatched collective sequence."],"references":[{"title":"PyTorch torch.distributed","url":"https://docs.pytorch.org/docs/2.15/distributed.html"},{"title":"PyTorch ProcessGroupNCCL environment variables","url":"https://docs.pytorch.org/docs/2.15/torch_nccl_environment_variables.html"},{"title":"NCCL RAS","url":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/troubleshooting/ras.html"},{"title":"The Llama 3 Herd of Models, section 3.3.4","url":"https://arxiv.org/abs/2407.21783"},{"title":"C4: real-time anomaly detection and communication optimization (Alibaba)","url":"https://arxiv.org/abs/2406.04594"}]},{"id":"job.straggler_healthy_hardware","domain":"job","name":"Straggler rank with healthy hardware (imbalance, GC pauses, host contention)","summary":"A rank or pipeline stage is consistently slower although its GPU, links and node pass health checks. Causes include uneven work (pipeline stage partitioning, variable sequence lengths per micro-batch), Python garbage-collection pauses that land on different ranks at different steps, and memory-allocator fragmentation. CPU contention or throttling the host imposes is host.cpu_memory_contention, not this entry. Every synchronous step waits for it.","job_effect":["slowdown"],"blast_radius":"job","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Slow rank with no GPU-side cause","source":"Artemis analysis, algorithm pending","identifier":"Likely cause: host, because the GPU looks like its peers, so time is lost off the GPU","detection":"Flagged rank whose telemetry is in line with peers. A hint, not a diagnosis. Rule: Pending.","strength":"Pending"},{"name":"Host contention for the rank","source":"Artemis analysis, algorithm pending","identifier":"Per-rank CPU busy share, cgroup CPU throttling, run-queue wait and cgroup pressure (PSI) for CPU, memory and I/O","detection":"The slow rank's values above its peers' median in the same window.","strength":"Pending"},{"name":"Per-step operation timing","source":"Job telemetry","identifier":"CUDA-event or profiler timelines per rank (forward/backward/optimizer and collective start times)","detection":"The slow rank's compute is longer (imbalance, fragmentation) or its kernel launches start late (GC pause, CPU stall). ByteDance's what-if analysis found most straggling steps share a similar slowdown, i.e. persistent causes.","strength":"strong","ref":"https://arxiv.org/abs/2505.05713"}],"confounders":[{"failure":"gpu.persistent_slow_gpu","how_to_distinguish":"Thermal, power, hardware-slowdown or clock readings that differ from peers point at the GPU; readings in line with peers do not. A GPU slow against its class in a matched probe outside the job is gpu.persistent_slow_gpu (gpu.thermal_power_throttling when throttle bits are set); this entry needs that probe to pass."},{"failure":"fabric.pcie_link_degraded","how_to_distinguish":"The likely cause is PCIe: the link is below maximum."},{"failure":"job.dataloader_stall","how_to_distinguish":"High loader wait share on the slow rank."},{"failure":"a rank that moves around step to step","how_to_distinguish":"Sequence-length imbalance and GC pauses hit different ranks at different steps; a hardware straggler is the same rank every window."},{"failure":"host.cpu_memory_contention","how_to_distinguish":"Contention the node imposes (other processes, a cgroup CPU limit, NUMA misplacement) stays with the node when the job moves: host.cpu_memory_contention. This entry keeps host contention the job causes itself, which follows the job to any node."},{"failure":"fabric.slow_island_or_bridge_link","how_to_distinguish":"Island or link findings with compute time flat point at a path, not a rank."}],"diagnosis":"Healthy-hardware straggling is a diagnosis by elimination: GPU telemetry in line with peers, health checks passing, and the same slowdown on other nodes. Positive evidence comes from timelines (late kernel launches, longer compute on heavier micro-batches or stages) and host telemetry. Confirmation is a controlled change (balance stages or sequences, control GC, remove contention) followed by a matched re-measurement.","fixes":[{"fix":"rebalance_work","when":"The job opted in to rebalancing and the imbalance is persistent and per-rank (batch shares can absorb it).","order":1},{"fix":"tune_job_configuration","when":"Stage repartitioning, sequence-length balancing across micro-batches, synchronized or disabled automatic GC, CPU binding.","order":2}],"human_role":"job owner","verification":{"remeasure":"Samples/s over at least 3 matched windows before vs after the change; the rank finding clears (rebalanced runs must report work done so time per sample is compared).","post_repair_check":"Not a hardware repair: the next run of the same configuration reproduces the improvement."},"escalation_steps":["Confirm the slow rank's GPU and node look healthy (telemetry, health checks).","Check whether the same rank is slow every window or the slow rank moves.","Capture a few profiled steps from the slow and a normal rank and compare compute, launch gaps and GC events.","Hand the job owner the timeline evidence and the candidate change."],"references":[{"title":"Understanding Stragglers in Large Model Training Using What-if Analysis","url":"https://arxiv.org/abs/2505.05713"},{"title":"MegaScale: Scaling LLM Training to More Than 10,000 GPUs","url":"https://arxiv.org/abs/2402.15627"}]},{"id":"job.dataloader_stall","domain":"job","name":"Data-loader or input-pipeline stall","summary":"The training loop waits for its next batch: too few loader workers, slow decoding on the CPU, slow reads from shared storage, or loader workers stalling. GPUs idle between steps; if only some ranks stall, they become stragglers and everyone waits.","job_effect":["slowdown","hang"],"blast_radius":"job","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Loader wait share","source":"Artemis analysis, algorithm pending","identifier":"Time spent waiting for the next batch, as a share of each rank's window","detection":"Wait share rising over the run's own earlier windows, or one rank's above its peers in the same window. Threshold: Pending. A missing measurement means unknown, not zero.","strength":"Pending"},{"name":"DataLoader configuration","source":"Job telemetry","identifier":"torch.utils.data.DataLoader num_workers, prefetch_factor (batches loaded ahead per worker), persistent_workers, timeout (default 0: no batch timeout; worker-death and worker-error checks still apply)","detection":"Context, not a fault: with timeout 0 there is no deadline for a batch, so a worker that stalls without dying or raising blocks the loader; a dead or failing worker still raises. A positive timeout turns a stalled batch into an error.","strength":"suggestive","ref":"https://docs.pytorch.org/docs/2.15/data.html"},{"name":"Node CPU and I/O pressure","source":"node_exporter / OS","identifier":"node_pressure_cpu_waiting_seconds_total, node_pressure_io_waiting_seconds_total, node_pressure_io_stalled_seconds_total","detection":"PSI share rising on the stalled ranks' nodes during the stall. Node-wide, not attributable to one job.","strength":"suggestive"},{"name":"Idle GPU on a flagged rank","source":"Artemis analysis, algorithm pending","identifier":"Likely cause: host (waiting for work), because SM clocks are low while the GPU sits idle","detection":"Flagged rank whose GPU idles between kernels. Rule: Pending","strength":"Pending"}],"confounders":[{"failure":"job.storage_checkpoint_io","how_to_distinguish":"Storage slowness shows on every reader of the filesystem (I/O PSI, mount statistics) and often in checkpoint times too; a CPU-bound loader shows high CPU busy and low I/O wait."},{"failure":"job.straggler_healthy_hardware","how_to_distinguish":"A straggler from compute imbalance has low loader wait."}],"diagnosis":"A measured loader wait share that rose (or exceeds peers) at the slowdown onset ranks the input pipeline first. Separate CPU-bound from I/O-bound with the rank's CPU busy share and the node's I/O PSI. Confirm by changing loader settings (or storage path) and re-measuring the wait share and step time.","fixes":[{"fix":"tune_job_configuration","when":"Raise num_workers or prefetch_factor, set persistent_workers, set a DataLoader timeout so a stuck worker errors instead of hanging.","order":1},{"fix":"exclude_and_restart","when":"Only ranks on one node stall and that node's CPU or local storage is degraded.","order":2}],"human_role":"job owner","verification":{"remeasure":"Loader wait share and step time over 3 matched windows before vs after; wait share back at its earlier level.","post_repair_check":"Not a hardware repair: rerun reproduces the lower wait share."},"escalation_steps":["Read the loader wait share per rank; find whether all ranks or a subset stall.","Check CPU busy share and I/O PSI on the stalled ranks' nodes.","Check the storage the dataset is read from (mount stats, other jobs' I/O).","Give the job owner the evidence and loader settings to change."],"references":[{"title":"PyTorch torch.utils.data","url":"https://docs.pytorch.org/docs/2.15/data.html"},{"title":"MegaScale: Scaling LLM Training to More Than 10,000 GPUs","url":"https://arxiv.org/abs/2402.15627"}]},{"id":"job.storage_checkpoint_io","domain":"job","name":"Storage or checkpoint I/O slow or failing","summary":"Shared storage is slow, a mount is missing or hung on some nodes, or checkpoint writes fail. Synchronous saves block training longer; asynchronous saves silently never complete; a missing mount fails job start; a hung mount leaves processes in uninterruptible I/O and the job stops progressing.","job_effect":["slowdown","hang","crash","latent"],"blast_radius":"cluster","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Checkpoint events","source":"Artemis analysis, algorithm pending","identifier":"Per-save duration and whether it completed durably","detection":"Save time rising over earlier saves of the same run; failed saves; async saves never reported complete. Metric and threshold: Pending.","strength":"Pending"},{"name":"Node I/O pressure and client statistics","source":"node_exporter / OS","identifier":"node_pressure_io_waiting_seconds_total and io_stalled; node_exporter nfs and mountstats collectors","detection":"I/O stall share rising on many nodes at once (backend) or one node (client/mount).","strength":"suggestive"},{"name":"Scheduler launch failures","source":"Scheduler","identifier":"Slurm reason JobLaunchFailure ('may be due to a file system problem, invalid program name, etc.'); reason SystemFailure ('Failure of the Slurm system, a file system, the network, etc.')","detection":"Any occurrence; clustered by node points at the node's mount.","strength":"suggestive","ref":"https://slurm.schedmd.com/squeue.html"},{"name":"Missing mountpoint health check","source":"Storage","identifier":"site health check that the expected filesystems are mounted and responsive (Meta runs 'missing mountpoints' as a high-severity node check)","detection":"Check fails on a node: remove it from scheduling. Check implementation is site-specific.","strength":"definitive","ref":"https://arxiv.org/abs/2410.21680"}],"confounders":[{"failure":"job.dataloader_stall","how_to_distinguish":"Input waits without checkpoint slowdowns and without I/O PSI point at the loader's CPU work."},{"failure":"larger checkpoints by design","how_to_distinguish":"A longer save time from a larger checkpoint is not slower storage. Metric and threshold: Pending."}],"diagnosis":"Many nodes' I/O stall rising together with save time points at the storage backend; one node's missing or hung mount points at that node's client. Metric and threshold: Pending. Confirm with the storage system's own metrics and a direct read/write test from an affected node.","fixes":[{"fix":"cordon_node","when":"One node's mount is missing or hung.","order":1},{"fix":"restart_from_checkpoint","when":"The job hung or failed in I/O; restart from the last checkpoint recorded durable and complete.","order":2},{"fix":"run_active_diagnostic","when":"Before the hold is released: mount and read/write check on the node.","order":3}],"human_role":"storage administrator; cluster operator","verification":{"remeasure":"Save time back to the run's earlier saves (metric and threshold: Pending); every async save reports complete and durable; I/O PSI at baseline.","post_repair_check":"Mount health check passes on the node; a timed write/read of a checkpoint-sized file matches peer nodes."},"escalation_steps":["Determine scope: one node, a rack, or every client of the filesystem.","On an affected node, check the mount table and processes stuck in I/O.","Pull the storage backend's health and latency metrics for the window.","Ticket the storage team with the affected clients and times; keep nodes with broken mounts cordoned."],"references":[{"title":"Revisiting Reliability in Large-Scale ML Research Clusters (Meta)","url":"https://arxiv.org/abs/2410.21680"},{"title":"C4: real-time anomaly detection and communication optimization (Alibaba)","url":"https://arxiv.org/abs/2406.04594"},{"title":"Slurm squeue job reason codes","url":"https://slurm.schedmd.com/squeue.html"}]},{"id":"job.perf_regression_after_change","domain":"job","name":"Performance regression after a code, library, driver or container change","summary":"After a change (training code, PyTorch, CUDA, NCCL, driver, container image, site configuration) the job runs slower on the same hardware. Usually every rank slows similarly, so peer comparison inside the job sees nothing; only a comparison with the run before the change shows it.","job_effect":["slowdown"],"blast_radius":"job","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Before and after regression record","source":"Artemis analysis, algorithm pending","identifier":"Before and after observations, each run's software versions (torch, CUDA, NCCL, driver) and configuration differences as hypotheses","detection":"After value worse than before beyond tolerance; configuration differences are hypotheses, not causes. Ranking rule: Pending.","strength":"Pending"},{"name":"Driver and device configuration snapshot","source":"Inventory","identifier":"Driver and CUDA driver versions, VBIOS, power limits, application clocks, persistence, compute and MIG modes; DCGM_FI_DRIVER_VERSION label on DCGM series","detection":"A field that changed between the before and after runs.","strength":"suggestive"},{"name":"Job throughput history","source":"Job telemetry","identifier":"samples/s or step time per run, with its code revision, image digest and node set","detection":"Step change at the first run with the new revision, persisting across runs and node sets.","strength":"strong"}],"confounders":[{"failure":"job.slower_after_restart_new_nodes","how_to_distinguish":"If the slow run also landed on different nodes, rerun the old revision on the new nodes (or the new revision on the old) to separate software from placement."},{"failure":"fabric.nic_gpu_affinity_misconfig","how_to_distinguish":"An image or NCCL change can alter NIC selection; compare NCCL's selected devices between runs."}],"diagnosis":"A configuration difference that coincides with the slowdown is a corroborating hypothesis, not a cause. The discriminating experiment is an A/B rerun on the same nodes with only that change reverted; a rollback that re-measures as recovered confirms the cause.","fixes":[{"fix":"rollback_software_change","when":"A single identified change and a known-good previous version exist.","order":1},{"fix":"run_active_diagnostic","when":"No software change explains it: probe the nodes to rule out hardware drift.","order":2}],"human_role":"job owner or platform owner of the changed component","verification":{"remeasure":"Recovered when at least 3 samples of throughput are within 2% of the healthy before value.","post_repair_check":"Not a hardware repair: the rolled-back configuration reproduces the earlier throughput on a second run."},"escalation_steps":["List every change between the last good and first slow run (code, image digest, library and driver versions, site config).","Rerun the last good configuration on the same nodes to confirm the regression is the change.","Bisect the change set if several changes landed together.","File the regression with the owning team with the A/B numbers."],"references":[{"title":"Revisiting Reliability in Large-Scale ML Research Clusters (Meta)","url":"https://arxiv.org/abs/2410.21680"},{"title":"The Llama 3 Herd of Models, Table 5","url":"https://arxiv.org/abs/2407.21783"}]},{"id":"job.cuda_oom_fragmentation","domain":"job","name":"CUDA out-of-memory or allocator fragmentation","summary":"A rank's GPU allocation exceeds free device memory and PyTorch raises OutOfMemoryError, ending the job. A milder form: fragmentation in the caching allocator causes extra cudaMalloc/cudaFree calls and slower steps without a crash.","job_effect":["crash","slowdown"],"blast_radius":"job","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"OutOfMemoryError and allocator statistics","source":"Job telemetry","identifier":"torch.cuda.OutOfMemoryError in the rank's log; torch.cuda.memory_stats() / memory_summary(); torch.cuda.memory._record_memory_history() and _dump_snapshot() for a full allocator snapshot","detection":"Any OutOfMemoryError. Fragmentation: large reserved-but-inactive memory in memory_stats while allocations fail or cudaMalloc calls climb.","strength":"definitive","ref":"https://docs.pytorch.org/docs/2.15/notes/cuda.html"},{"name":"Scheduler out-of-memory state","source":"Scheduler","identifier":"Slurm job state OOM OUT_OF_MEMORY ('Job experienced out of memory error')","detection":"Job ends in OUT_OF_MEMORY. The squeue page does not say whether this is host or GPU memory; check the rank's log for the CUDA error.","strength":"suggestive","ref":"https://slurm.schedmd.com/squeue.html"},{"name":"Frame-buffer usage","source":"DCGM","identifier":"DCGM_FI_DEV_FB_USED / DCGM_FI_DEV_FB_FREE (MB)","detection":"FB_USED near the device total on the failing GPU before the crash.","strength":"suggestive"}],"confounders":[{"failure":"host memory OOM (cgroup OOM kill)","how_to_distinguish":"Host OOM kills the process with no CUDA error; host telemetry would show memory cgroup oom and oom_kill events."},{"failure":"another process on the GPU","how_to_distinguish":"Device telemetry would show other compute processes on the rank's GPU (unknown inside a PID namespace)."},{"failure":"job.straggler_healthy_hardware","how_to_distinguish":"Fragmentation slowdown shows as launch delays with high cudaMalloc/cudaFree counts; ByteDance found it uncommon."}],"diagnosis":"OutOfMemoryError in the log confirms GPU OOM. Distinguish true over-subscription (allocated near total) from fragmentation (reserved much larger than allocated) with memory_stats or a snapshot. Rank-specific OOM on a larger micro-batch or sequence points at data-dependent memory.","fixes":[{"fix":"tune_job_configuration","when":"Reduce micro-batch or sequence length, enable activation checkpointing, or set PYTORCH_CUDA_ALLOC_CONF (expandable_segments:True; max_split_size_mb as a last resort per the PyTorch notes).","order":1},{"fix":"restart_from_checkpoint","when":"After the configuration change.","order":2}],"human_role":"job owner","verification":{"remeasure":"The restarted job passes the step that ran out of memory and keeps peak allocated memory below the device total with margin over an observation window (length: Pending); for fragmentation, step time back to its earlier value.","post_repair_check":"Not a hardware repair."},"escalation_steps":["Capture the OutOfMemoryError message and memory_summary from the failing rank.","Check whether other processes held memory on the GPU.","Compare allocated vs reserved memory to separate over-subscription from fragmentation.","Give the job owner the snapshot and the candidate configuration change."],"references":[{"title":"PyTorch CUDA semantics: memory management","url":"https://docs.pytorch.org/docs/2.15/notes/cuda.html"},{"title":"PyTorch: understanding CUDA memory usage","url":"https://docs.pytorch.org/docs/2.15/torch_cuda_memory.html"},{"title":"Slurm squeue job state codes","url":"https://slurm.schedmd.com/squeue.html"},{"title":"Understanding Stragglers in Large Model Training Using What-if Analysis","url":"https://arxiv.org/abs/2505.05713"},{"title":"Revisiting Reliability in Large-Scale ML Research Clusters (Meta)","url":"https://arxiv.org/abs/2410.21680"}]},{"id":"job.nan_loss_spike_or_sdc","domain":"job","name":"NaN/Inf or loss spike, and telling it from silent data corruption","summary":"The loss becomes NaN/Inf or spikes. Usually this is numerical (learning rate, data, precision), but a GPU producing wrong results without any error (silent data corruption, SDC) can also perturb gradients, shift the model to a different optimum, or cause loss spikes. The job may crash on a NaN check or keep training on corrupted weights.","job_effect":["silent_corruption","crash"],"blast_radius":"job","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Loss and gradient-norm series","source":"Job telemetry","identifier":"per-step loss and global gradient norm logged by the training loop; non-finite checks","detection":"Any non-finite value; spikes beyond the run's own recent variation (site/job policy; no standard threshold).","strength":"suggestive","ref":"https://arxiv.org/abs/2502.12340"},{"name":"Replay of the step on other hardware","source":"Job telemetry","identifier":"deterministic re-execution of the same step from the same checkpoint and data on a different node, comparing outputs","detection":"The suspect device's result differs from validated healthy devices that agree with each other for an identical deterministic step. The SDC study used deterministic execution (XLA) and paired each suspect node with a healthy node to isolate SDC effects.","strength":"definitive","ref":"https://arxiv.org/abs/2502.12340"},{"name":"Contained or uncontained memory errors","source":"Kernel log","identifier":"Xid 94 (contained memory error: the application must restart) and Xid 95 (uncontained: GPU reset required)","detection":"Any occurrence on a job's GPU around the event points to a detected (not silent) hardware error.","strength":"strong","ref":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"}],"confounders":[{"failure":"numerical instability or bad data","how_to_distinguish":"Reproduces deterministically on other hardware from the same checkpoint and batch; SDC does not follow to healthy hardware."},{"failure":"gpu.ecc_uncorrectable_contained","how_to_distinguish":"ECC events, row remapping and Xid 94/95 are detected errors and visible in DCGM; SDC by definition leaves no error signal."},{"failure":"gpu.silent_data_corruption","how_to_distinguish":"Boundary: this entry is the triage of a visible loss anomaly. The incident becomes gpu.silent_data_corruption, which carries the hardware repair, only when deterministic recomputation of the same step from the same checkpoint and data on the suspect device disagrees with validated healthy devices that agree with each other. A replay that differs on other hardware is evidence, not confirmation; a failed thermal, memory, link or other diagnostic routes to the matching hardware entry instead."}],"diagnosis":"A loss anomaly is numerical until shown otherwise. Evidence for SDC: the anomaly does not reproduce when the same step is replayed on other hardware, or recurs on runs that include one node. SDC is confirmed only by deterministic recomputation: the same step from the same checkpoint and data, recomputed on the suspect device, disagrees with validated healthy devices that agree with each other (the cited study's method). A failed hardware diagnostic does not confirm SDC; it points at the matching hardware entry instead (for example a memory, thermal or link entry). Correlation of spikes with a node only ranks it.","fixes":[{"fix":"restart_from_checkpoint","when":"Roll back to a checkpoint from before the anomaly.","order":1},{"fix":"exclude_and_restart","when":"Replay or recurrence points at one node.","order":2},{"fix":"run_active_diagnostic","when":"On the suspect node: extended GPU diagnostics (dcgmi diag -r 3 or 4 with -i naming the suspect GPUs, none allocated to a job).","order":3},{"fix":"rma_replace_hardware","when":"Deterministic recomputation confirms wrong results on the device. A failed diagnostic instead routes to the matching hardware entry and its fixes.","order":4}],"human_role":"job owner decides the rollback point; cluster operator or vendor RMA for a confirmed SDC node","verification":{"remeasure":"The rolled-back run passes the anomaly step and its loss tracks the earlier curve over the following window.","post_repair_check":"Suspect node passes extended diagnostics and a deterministic replay of the anomalous step matches a healthy node bit-for-bit (or within the job's tolerance)."},"escalation_steps":["Record the step, loss, gradient norms and the node set of the anomaly.","Replay the step deterministically from the previous checkpoint on the same and on different nodes.","Check Xids and ECC counters on the job's GPUs around the event.","If replay differs by node, quarantine the node and run extended diagnostics; RMA if confirmed."],"references":[{"title":"Understanding Silent Data Corruption in LLM Training","url":"https://arxiv.org/abs/2502.12340"},{"title":"The Llama 3 Herd of Models, Table 5","url":"https://arxiv.org/abs/2407.21783"},{"title":"NVIDIA Xid catalog (analyzing Xid errors)","url":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"title":"DCGM diagnostics","url":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/dcgm-diagnostics.html"}]},{"id":"job.warmup_imbalance","domain":"job","name":"Imbalance already present at warmup (slow-from-start rank or mixed hardware)","summary":"A rank or island is slower from the first steps: a different GPU model or power limit, a GPU already degraded when the job started, or an island of another vendor. Rules that compare each rank with its own warmup see no change, so the slowdown persists for the whole job unless capability differences are measured.","job_effect":["slowdown"],"blast_radius":"job","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Warmup and imbalance notes","source":"Artemis analysis, algorithm pending","identifier":"Notes that islands already differed at warmup, or that a hardware class is slower by design","detection":"Rule: Pending.","strength":"Pending"},{"name":"Job-start health probe","source":"Artemis analysis, algorithm pending","identifier":"A probe on every rank before training. Workload: Pending","detection":"A rank's probe result below its hardware class's history or peers.","strength":"Pending"},{"name":"GPU identity per rank","source":"Inventory","identifier":"Hardware class (vendor, model, memory, power limit) from NVML or AMD SMI identity","detection":"Ranks of different classes within one island.","strength":"suggestive"}],"confounders":[{"failure":"job.straggler_healthy_hardware","how_to_distinguish":"Work imbalance in the model (stage partitioning) is also present at warmup; the health probe separates hardware from workload."},{"failure":"gpu.persistent_slow_gpu","how_to_distinguish":"Fleet history of the GPU's probe results shows a step down before this job."}],"diagnosis":"Different hardware classes explain the gap by capability and need balancing, not repair. Same-class ranks with a slower probe point at a degraded GPU (hand to the gpu entries). The probe and fleet history confirm; a slow warmup alone only correlates.","fixes":[{"fix":"rebalance_work","when":"Capability differences between classes or islands (the case rebalancing is for), job opted in.","order":1},{"fix":"run_active_diagnostic","when":"A same-class rank is slow at warmup.","order":2},{"fix":"exclude_and_restart","when":"The probe confirms a degraded GPU.","order":3}],"human_role":"job owner (opt in to rebalancing); cluster operator (degraded GPU)","verification":{"remeasure":"After rebalancing: samples/s over 3 matched windows vs the unbalanced allocation, with work done reported so per-sample times stay comparable.","post_repair_check":"A replaced or repaired GPU's probe result in line with its class."},"escalation_steps":["Read what the run recorded about warmup and imbalance, and the ranks' hardware classes.","Run the health probe on the slow rank and on a peer of the same class.","If same-class and slower, open a GPU ticket with the probe and telemetry.","If classes differ, recommend rebalancing to the job owner."],"references":[]},{"id":"job.quiet_rank","domain":"job","name":"Quiet or stuck rank: stops reporting while the job may continue","summary":"One rank stops reporting (mechanism and interval: Pending): its process died, its node failed, its training thread is stuck outside a collective, or the telemetry path to it broke. Depending on where it stopped the job hangs at the next collective, crashes, or (for telemetry loss only) keeps training while monitoring loses sight of a rank.","job_effect":["hang","crash","latent"],"blast_radius":"node","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Missing rank","source":"Artemis analysis, algorithm pending","identifier":"No progress reports from the rank. Rule: Pending","detection":"Pending","strength":"Pending"},{"name":"NCCL RAS peer state","source":"NCCL","identifier":"ncclras: DEAD (unreachable for 60 s), INCOMPLETE ('Missing communicator data'), PEER_DEAD monitoring event","detection":"Any DEAD process names node and GPU. DEAD means unreachable over the RAS network (plain TCP/IP on the bootstrap/out-of-band interface, separate from the RDMA training traffic) for 60 s, not that the process exited.","strength":"strong","ref":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/troubleshooting/ras.html"},{"name":"Node not responding to the scheduler","source":"Scheduler","identifier":"sinfo node state suffix '*' ('presently not responding and will not be allocated any new work'); SlurmdTimeout before DOWN; Kubernetes node Ready condition Unknown","detection":"The rank's node carries the flag.","strength":"strong","ref":"https://slurm.schedmd.com/sinfo.html"}],"confounders":[{"failure":"Telemetry loss","how_to_distinguish":"The job keeps stepping (its own logs, NCCL RAS RUNNING with no errors) while only monitoring misses the rank: a monitoring fault, not a job fault."},{"failure":"job.collective_hang_watchdog","how_to_distinguish":"In a collective hang every rank keeps reporting but stops making progress; a quiet rank stops reporting. Mechanism and interval: Pending."}],"diagnosis":"Missing summaries plus NCCL RAS DEAD or a non-responding node make a dead rank (or node) the leading hypothesis, but a network partition can produce all three while training continues: RAS and the scheduler use management or bootstrap networks, and the reporting path is Pending. Confirmation needs process exit (the scheduler's step state ended with an exit code, or the process absent on the node) or no training progress from an independent source (the surviving ranks' step counter stops advancing, or they wait in a collective until the watchdog fires). Missing summaries alone with NCCL healthy point at the monitoring path. The cause of the death comes from the node's logs and scheduler state.","fixes":[{"fix":"exclude_and_restart","when":"The rank's death is confirmed: its process exited (step state or process absent) or the job's other ranks stopped making progress. RAS DEAD or missing summaries alone are not enough.","order":1},{"fix":"restart_from_checkpoint","when":"The node recovered and passes checks.","order":2},{"fix":"run_active_diagnostic","when":"On the node before it returns.","order":3}],"human_role":"cluster operator","verification":{"remeasure":"Restarted job: every rank keeps reporting over an observation window (length: Pending); no missing report.","post_repair_check":"The node passes the site health check and a short multi-GPU job."},"escalation_steps":["Check whether the job is still stepping (job logs, NCCL RAS status).","Check the node's scheduler state, BMC power state and kernel log for the time the rank went quiet.","If the node died, follow the node's ticket; if only telemetry broke, ticket the monitoring path."],"references":[{"title":"NCCL RAS","url":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/troubleshooting/ras.html"},{"title":"Slurm sinfo node state codes","url":"https://slurm.schedmd.com/sinfo.html"},{"title":"Slurm slurm.conf (SlurmdTimeout)","url":"https://slurm.schedmd.com/slurm.conf.html"},{"title":"Kubernetes nodes: node status and controller","url":"https://kubernetes.io/docs/concepts/architecture/nodes/"}]},{"id":"job.stuck_pending","domain":"job","name":"Job stuck pending in the scheduler queue","summary":"The job never starts: it waits for resources or priority, requests nodes that are down or drained, has constraints no node satisfies, or targets a down partition. GPUs it should use sit idle or serve other work; the job owner sees no error, only a queue.","job_effect":["capacity_loss"],"blast_radius":"job","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Slurm pending reason","source":"Scheduler","identifier":"squeue %R for PD PENDING jobs: Resources, Priority, ReqNodeNotAvail, NodeDown, BadConstraints, PartitionDown, PartitionInactive, Dependency, DependencyNeverSatisfied, JobHeldAdmin, JobHeldUser, BeginTime","detection":"Reasons that can never resolve by waiting (BadConstraints, DependencyNeverSatisfied, ReqNodeNotAvail on a drained node, PartitionDown) are actionable immediately; Resources/Priority only past a site-chosen wait.","strength":"definitive","ref":"https://slurm.schedmd.com/squeue.html"},{"name":"Kubernetes pod not scheduled","source":"Scheduler","identifier":"pod phase Pending (includes time waiting to be scheduled and pulling images); condition PodScheduled not True","detection":"Pending past a site-chosen wait with PodScheduled false.","strength":"definitive","ref":"https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/"}],"confounders":[{"failure":"job.container_runtime_start_failure","how_to_distinguish":"Kubernetes Pending also covers image pulls; a scheduled pod (PodScheduled True) waiting on ImagePullBackOff is a start failure, not a queue problem."},{"failure":"host.node_unresponsive","how_to_distinguish":"ReqNodeNotAvail or NodeDown: the cause is the node's state; follow the node's ticket."}],"diagnosis":"The scheduler's own reason is the diagnosis; no inference is needed. Rank actionable reasons (impossible constraints, down nodes or partitions) above capacity waits.","fixes":[{"fix":"tune_job_configuration","when":"Constraints, node list, size or partition make the request unsatisfiable or needlessly narrow.","order":1},{"fix":"abort_and_requeue_job","when":"The job must be resubmitted with a changed request.","order":2}],"human_role":"job owner (request); cluster operator (partition, reservations, down nodes)","verification":{"remeasure":"The job reaches RUNNING within the site's expected wait for its size.","post_repair_check":"Not a hardware repair."},"escalation_steps":["Read the pending reason (squeue %R or kubectl describe pod).","For node or partition reasons, check those nodes' or the partition's state and reason (sinfo -R).","For constraint reasons, compare the request with available node features.","Tell the job owner what to change, or fix the partition or reservation."],"references":[{"title":"Slurm squeue: job reason codes and state codes","url":"https://slurm.schedmd.com/squeue.html"},{"title":"Slurm sinfo","url":"https://slurm.schedmd.com/sinfo.html"},{"title":"Kubernetes pod lifecycle","url":"https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/"}]},{"id":"job.node_fail_requeue_loop","domain":"job","name":"Job ends NODE_FAIL or loops through requeues on a bad node","summary":"The job keeps failing on node failures and is requeued, or keeps landing on a node that fails it without tripping health checks (a 'lemon' node). Each attempt loses the work since the last checkpoint plus startup time; after enough automatic requeues Slurm holds the job.","job_effect":["crash","capacity_loss"],"blast_radius":"node","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Job end state and requeue count","source":"Scheduler","identifier":"Slurm state NF NODE_FAIL ('terminated due to failure of one or more allocated nodes'), RQ REQUEUED; scontrol show job Restarts=; MaxBatchRequeue (default 5) then JobHeldAdmin","detection":"Repeated NODE_FAIL or requeues of one job, or of different jobs on a common node, within a site-chosen window.","strength":"strong","ref":"https://slurm.schedmd.com/slurm.conf.html"},{"name":"Kubernetes node unreachable","source":"Scheduler","identifier":"Node Ready condition Unknown; by default the node controller waits 5 minutes before the first API-initiated eviction; Job .spec.backoffLimit","detection":"Pods evicted from a node whose Ready went Unknown; job retries consumed.","strength":"strong","ref":"https://kubernetes.io/docs/concepts/architecture/nodes/"},{"name":"Failure history per node","source":"Scheduler","identifier":"count of failed or NODE_FAIL jobs per node over days (accounting data), as in Meta's lemon-node detection","detection":"A node with above-average job failures; Meta found such nodes are not caught by health checks alone and need historic data.","strength":"suggestive","ref":"https://arxiv.org/abs/2410.21680"}],"confounders":[{"failure":"job bug that crashes on any node","how_to_distinguish":"A job bug ends FAILED (non-zero exit) on varying nodes; NODE_FAIL and failures concentrated on one node point at the node."},{"failure":"job.preemption","how_to_distinguish":"Preemption ends PREEMPTED and requeues by policy; it is not a node fault."}],"diagnosis":"Repeated failures with a common node rank that node first; health-check failures or hardware logs on it confirm. Without them, a statistically elevated failure rate over time (lemon detection) is the evidence, and needs history to separate from chance.","fixes":[{"fix":"exclude_and_restart","when":"A common node is identified across failures.","order":1},{"fix":"drain_node","when":"The node fails a health check or exceeds the site's failure-rate rule.","order":2},{"fix":"run_active_diagnostic","when":"Extended diagnostics on the drained node.","order":3},{"fix":"rma_replace_hardware","when":"Diagnostics find the faulty part.","order":4}],"human_role":"cluster operator; data-center technician or vendor RMA","verification":{"remeasure":"The job runs past its previous failure point without the node; the node's job-failure rate after repair at fleet average over an observation window (length: Pending).","post_repair_check":"Extended node diagnostics (dcgmi diag -r 3 -i \u003cnode gpu ids>, IB and storage checks) pass before undraining."},"escalation_steps":["List the nodes of every failed attempt and find common nodes.","Pull those nodes' health-check history, Xids and kernel logs at each failure.","Drain the common node and run extended diagnostics.","Replace the faulty part; watch the node's failure rate after return."],"references":[{"title":"Slurm squeue job state codes","url":"https://slurm.schedmd.com/squeue.html"},{"title":"Slurm slurm.conf (MaxBatchRequeue, JobRequeue)","url":"https://slurm.schedmd.com/slurm.conf.html"},{"title":"Slurm scontrol","url":"https://slurm.schedmd.com/scontrol.html"},{"title":"Kubernetes nodes","url":"https://kubernetes.io/docs/concepts/architecture/nodes/"},{"title":"Kubernetes Jobs","url":"https://kubernetes.io/docs/concepts/workloads/controllers/job/"},{"title":"Revisiting Reliability in Large-Scale ML Research Clusters (Meta)","url":"https://arxiv.org/abs/2410.21680"}]},{"id":"job.preemption","domain":"job","name":"Job preempted by higher-priority work","summary":"The scheduler stops the job to run higher-priority work, per site policy. The job loses the work since its last checkpoint and waits in the queue again. Not a fault, but a recurring source of lost GPU time that the job and operator must plan for.","job_effect":["capacity_loss"],"blast_radius":"job","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Preempted state","source":"Scheduler","identifier":"Slurm state PR PREEMPTED ('Job terminated due to preemption'); PreemptMode (e.g. REQUEUE); GraceTime (default 0: no delay between selection and preemption)","detection":"Any PREEMPTED end state. Slurm cannot tell an exit caused by the preemption signal from an unrelated exit within GraceTime.","strength":"definitive","ref":"https://slurm.schedmd.com/preempt.html"},{"name":"Work lost since last checkpoint","source":"Artemis analysis, algorithm pending","identifier":"Time since the last checkpoint recorded durable and complete","detection":"Lost work per preemption above the site's target.","strength":"Pending"}],"confounders":[{"failure":"job.node_fail_requeue_loop","how_to_distinguish":"Requeues after NODE_FAIL are faults; requeues after PREEMPTED are policy."}],"diagnosis":"The scheduler state is the diagnosis. The operational question is how much work each preemption loses, which depends on checkpoint interval and GraceTime.","fixes":[{"fix":"restart_from_checkpoint","when":"On requeue, resume from the last durable checkpoint automatically. PREEMPTED is a stop the scheduler initiated and slurmd reported, so it meets restart_from_checkpoint's confirmed-termination precondition; if the node is not responding (sinfo `*`), it does not, and the restart needs approval.","order":1}],"human_role":"Usually none; an operator approves the restart if the node is not responding.","verification":{"remeasure":"After the requeued job starts, it resumes from the last durable checkpoint and its step time matches the pre-preemption baseline within tolerance.","post_repair_check":"Not a hardware repair."},"escalation_steps":["If preemptions repeatedly lose more work than the site target, ask the job owner to checkpoint on the preemption signal within GraceTime, or the operator to adjust GraceTime."],"references":[{"title":"Slurm preemption","url":"https://slurm.schedmd.com/preempt.html"},{"title":"Slurm squeue job state codes","url":"https://slurm.schedmd.com/squeue.html"},{"title":"Revisiting Reliability in Large-Scale ML Research Clusters (Meta)","url":"https://arxiv.org/abs/2410.21680"}]},{"id":"job.container_runtime_start_failure","domain":"job","name":"Container image or runtime start failure","summary":"The job's containers never start or crash at start: the image cannot be pulled, the container exits immediately and restarts in a loop, the GPU runtime cannot initialize (driver/library mismatch, or the NVSwitch fabric not ready), or the launch fails on a node. The job makes no progress.","job_effect":["crash","capacity_loss"],"blast_radius":"job","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Image pull back-off","source":"Scheduler","identifier":"container Waiting reason ImagePullBackOff (image could not be pulled; back-off up to 300 s)","detection":"Any pod in ImagePullBackOff beyond one back-off cycle.","strength":"definitive","ref":"https://kubernetes.io/docs/concepts/containers/images/"},{"name":"Crash loop","source":"Scheduler","identifier":"kubectl STATUS CrashLoopBackOff (exponential restart back-off in effect) with RESTARTS climbing","detection":"CrashLoopBackOff on the job's pods; read the container's last termination reason and log.","strength":"strong","ref":"https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/"},{"name":"Slurm launch failure","source":"Scheduler","identifier":"reason JobLaunchFailure; state BF BOOT_FAIL ('launch failure, typically due to a hardware failure')","detection":"Any occurrence; clustered by node points at the node.","strength":"strong","ref":"https://slurm.schedmd.com/squeue.html"},{"name":"CUDA initialization failure","source":"Job telemetry","identifier":"cudaErrorSystemNotReady at CUDA init (NVSwitch systems before Fabric Manager initializes the fabric or when it fails)","detection":"Any job start failing with it on the node.","strength":"strong","ref":"https://docs.nvidia.com/datacenter/tesla/fabric-manager-user-guide/index.html"},{"name":"NCCL shared memory too small","source":"NCCL","identifier":"`NCCL WARN Error: failed to extend /dev/shm/nccl-\u003cid> to \u003cn> bytes` (shown with `NCCL_DEBUG=WARN`)","detection":"Communicator initialization fails with it in a container: /dev/shm is too small for NCCL's segments. NCCL suggests `--shm-size=1g --ulimit memlock=-1` on the docker command. NCCL 2.24 and later use cuMem host allocations by default where the driver and runtime allow, and 2.26.5 and later fall back to /dev/shm automatically if those fail.","strength":"definitive","ref":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/troubleshooting/runtime_and_mpi_issues.html"}],"confounders":[{"failure":"fabric.nvswitch_fabric_manager_failure","how_to_distinguish":"cudaErrorSystemNotReady for every image on the node is the fabric, not the container."},{"failure":"job.stuck_pending","how_to_distinguish":"A pod not yet scheduled (PodScheduled false) is a queue issue; a scheduled pod failing to pull or start is this entry."},{"failure":"job.perf_regression_after_change","how_to_distinguish":"A new image that starts but runs slower is a regression; one that cannot start is this entry."},{"failure":"host.gpu_software_stack_not_ready","how_to_distinguish":"Failure with every image on one node, a driver or module not loaded, or the GPU Operator validator failing is the node's stack: host.gpu_software_stack_not_ready. This entry is one job's image or runtime spec."}],"diagnosis":"The scheduler or runtime reason names the stage that failed (pull, start, GPU init). Failures on every node with one image point at the image; failures with every image on one node point at that node's runtime, driver or fabric.","fixes":[{"fix":"rollback_software_change","when":"A new image tag or digest fails where the previous one started.","order":1},{"fix":"tune_job_configuration","when":"NCCL cannot extend /dev/shm (the shared-memory signal): raise the container's shared memory in the job spec, for example Docker `--shm-size` (NCCL suggests `--shm-size=1g --ulimit memlock=-1`) or, on Kubernetes, an `emptyDir` volume with `medium: Memory` and a `sizeLimit` mounted at `/dev/shm` (it counts against the container's memory limit), then relaunch. Requeueing the unchanged spec repeats the failure.","order":1},{"fix":"cordon_node","when":"Start failures are confined to one node.","order":2},{"fix":"restart_system_service","when":"The node's container runtime, device plugin or Fabric Manager is wedged.","order":3},{"fix":"abort_and_requeue_job","when":"After the image or node fix, so the job starts on healthy nodes.","order":4}],"human_role":"job owner (image, container spec); cluster operator (node runtime)","verification":{"remeasure":"All pods or tasks reach running and the job completes its first steps.","post_repair_check":"A GPU smoke test container (CUDA device query or a short dcgmi diag -r 1 -i naming the container's own GPUs) starts on the repaired node."},"escalation_steps":["Read the runtime reason and the container's last log for each failing pod or task.","Check whether failures follow the image (all nodes) or the node (all images).","On a suspect node, check the container runtime, GPU device plugin, driver and Fabric Manager state.","Roll back the image or repair the node runtime."],"references":[{"title":"Kubernetes images: ImagePullBackOff","url":"https://kubernetes.io/docs/concepts/containers/images/"},{"title":"Kubernetes pod lifecycle","url":"https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/"},{"title":"Slurm squeue","url":"https://slurm.schedmd.com/squeue.html"},{"title":"NVIDIA Fabric Manager user guide","url":"https://docs.nvidia.com/datacenter/tesla/fabric-manager-user-guide/index.html"},{"title":"DCGM diagnostics","url":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/dcgm-diagnostics.html"}]},{"id":"job.slower_after_restart_new_nodes","domain":"job","name":"Job silently slower after restarting on different nodes","summary":"After a restart (failure, preemption, requeue) the job lands on a different node set and runs slower: a degraded node, a slower hardware class, a worse network placement (more switch hops, a congested or degraded rail). If every rank slows alike, or the slow node was slow from the first step, in-job peer and warmup comparisons see nothing.","job_effect":["slowdown"],"blast_radius":"job","algorithm":"Pending","family_routing":"Pending","signals":[{"name":"Throughput across restarts","source":"Job telemetry","identifier":"samples/s or step time per job attempt, with the attempt's node list (Slurm NodeList from scontrol show job; Restarts=)","detection":"Attempt N slower than attempt N-1 beyond tolerance with the same code and configuration.","strength":"strong","ref":"https://slurm.schedmd.com/scontrol.html"},{"name":"Restart boundary in a run's report","source":"Artemis analysis, algorithm pending","identifier":"A marker where a run's windows start over after a restart. Format: Pending","detection":"Marks the boundary only. Comparison across it: Pending.","strength":"Pending"},{"name":"Node probe history","source":"Artemis analysis, algorithm pending","identifier":"Earlier probe results for each GPU, against its class","detection":"A new node's GPUs below their class in the fleet history.","strength":"Pending"}],"confounders":[{"failure":"job.perf_regression_after_change","how_to_distinguish":"Check whether code, image or configuration also changed at the restart."},{"failure":"job.warmup_imbalance","how_to_distinguish":"If the new placement mixes hardware classes, the slowdown is capability, not a fault."},{"failure":"fabric.congestion_pfc_ecn","how_to_distinguish":"Other tenants on the new placement's links: communication time rose while compute stayed flat."}],"diagnosis":"A slowdown that tracks the node set, not the software, ranks placement or a node first. Split compute from communication time: compute slower points at node hardware (probe the new nodes); communication slower points at network placement. Confirm by restarting on the old node set or by excluding the suspect node and re-measuring.","fixes":[{"fix":"run_active_diagnostic","when":"Probe the new nodes against their class history.","order":1},{"fix":"exclude_and_restart","when":"A probed node is below its class.","order":2},{"fix":"rebalance_work","when":"The new set mixes hardware classes and the job opted in.","order":3}],"human_role":"job owner; cluster operator for node exclusion","verification":{"remeasure":"Samples/s of the next attempt within tolerance of the pre-restart attempt over at least 3 matched windows.","post_repair_check":"Excluded node passes its probe and diagnostics before return."},"escalation_steps":["Compare node lists and throughput of the attempts before and after the restart.","Confirm code, image and configuration are unchanged.","Probe the new nodes and compare with their class; check the network placement (switches spanned).","Exclude the slow node or request placement closer to the old one."],"references":[{"title":"Slurm scontrol","url":"https://slurm.schedmd.com/scontrol.html"},{"title":"MegaScale: Scaling LLM Training to More Than 10,000 GPUs","url":"https://arxiv.org/abs/2402.15627"},{"title":"PyTorch torchrun (elastic restarts)","url":"https://docs.pytorch.org/docs/2.15/elastic/run.html"}]}],"fixes":[{"id":"rebalance_work","name":"Rebalance work away from a slow rank","description":"Move part of a slow participant's per-step batch to its peers inside a running job, so the job stops waiting on it. A mitigation, not a repair: the slow GPU or host is still slow, so the failure still gets a ticket.","mechanism":"Opt-in at launch. At a step boundary every rank runs one agreement collective and all ranks commit the new per-rank batches or none do. No scheduler, node or device state changes.","tier":"automatic","preconditions":["The job opted in at launch.","A slow rank or island is flagged, not a hang, a missing rank or a link.","The proposed allocation stays inside the training's own bounds and conserves the global batch.","No other intervention (restart, drain, reset) is in flight for the job.","The job's model and optimizer are of a kind the numerical checks cover, or the owner has accepted the risk."],"verification":"Matched re-measurement: job samples/s in the windows after the commit against the regressed value and the healthy value; recovered needs at least 3 samples within 2% of the healthy value. Record that the slow component is still slow after the rebalance.","rollback":"Send a plan back to even allocation; it commits at the next step boundary through the same agreement.","references":[{"title":"MegaScale (ByteDance) handles straggler hosts by isolating and removing them","url":"https://arxiv.org/html/2402.15627v1"}]},{"id":"cordon_node","name":"Cordon a node (no new work)","description":"Stop the scheduler placing new work on a node while work already running there continues. In Slurm the state that does this is called DRAIN; in Kubernetes it is cordon. This map calls it cordon and keeps drain_node for actively moving running work off.","mechanism":"Slurm: first read `scontrol show node \u003cnode>`. If the node already carries any hold (a DRAIN, DOWN or FAIL state, whatever its Reason, or a maintenance reservation), do not write: `scontrol update ... Reason=` would replace that hold's Reason. Attach the incident to the existing hold and open a ticket naming it. Otherwise `scontrol update NodeName=\u003cnode> State=DRAIN Reason=\"\u003cincident> \u003csignal>\"` (no new jobs; running jobs complete and the node becomes DRAINED). The read and the write are separate, so another writer can drain the node between them; with slurmdbd, `sacctmgr show event Nodes=\u003cnode>` lists drain events with their Reason. Kubernetes: add a taint with effect NoSchedule whose key names the holder and whose value names the incident; adding it overwrites no other taint. A taint keeps off only pods that do not tolerate it, and a pod bound with `spec.nodeName` bypasses the scheduler, so the cordon reduces new arrivals but cannot exclude them. Read back with `scontrol show node \u003cnode>` / `kubectl get node \u003cnode>`.","tier":"automatic","preconditions":["The trigger is a definitive or strong signal named in the failure entry, read fresh (not a stale exporter value).","Slurm: the node carries no hold (any DRAIN, DOWN or FAIL state, whatever its Reason, or a maintenance reservation); otherwise attach the incident to the existing hold and open a ticket. Kubernetes: add only a dedicated taint, which overwrites nothing.","Kubernetes: no non-DaemonSet workload may tolerate that taint, including a blanket `operator: Exists` toleration, since the taint does not keep such pods off. Where that is not guaranteed, the cordon falls back to approval and a person cordons the node.","The circuit breaker is closed: correlated-trip and capacity limits are not exceeded.","The incident id and signal are written into the scheduler's reason, so the state explains itself."],"verification":"Readback shows DRAIN/DRAINED with the incident's Reason (Slurm; where the node already carried a hold, that hold unchanged and the incident attached to it) or the incident's taint (Kubernetes). On Kubernetes, no new non-DaemonSet pod lands on the node after the taint: compare `kubectl get pods -A --field-selector spec.nodeName=\u003cnode>` with the list taken when the taint went on; any new pod not managed by a DaemonSet, static (mirror) pods included, means the exclusion failed, and a person is paged. The node returns to service only after its fix and post-repair check pass, and then only through the release in rollback.","rollback":"Release only the hold placed for this incident, and only when nothing else holds the node. Slurm: only if `scontrol show node \u003cnode>` still shows the incident's Reason, the node is in no maintenance reservation and not DOWN or FAIL for another reason, and no other open incident names the node or its GPUs; then, after a person approves, `scontrol update NodeName=\u003cnode> State=RESUME` (or `State=UNDRAIN`). The release needs approval because Slurm has no conditional state update: another writer can drain the node between the read and the RESUME. Kubernetes: only if the taint still names this incident and no other open incident names the node, remove that taint; other taints and `spec.unschedulable` stay as they are. Otherwise leave the node held and tell the owner of the remaining hold.","references":[{"title":"Slurm scontrol (node states DRAIN, RESUME, UNDRAIN)","url":"https://slurm.schedmd.com/scontrol.html"},{"title":"Slurm sacctmgr (show event: node events with Reason and User)","url":"https://slurm.schedmd.com/sacctmgr.html"},{"title":"Slurm slurmdbd.conf (PurgeEventAfter)","url":"https://slurm.schedmd.com/slurmdbd.conf.html"},{"title":"kubectl cordon","url":"https://kubernetes.io/docs/reference/kubectl/generated/kubectl_cordon/"},{"title":"Kubernetes taints and tolerations","url":"https://kubernetes.io/docs/concepts/scheduling-eviction/taint-and-toleration/"},{"title":"NVIDIA GPU debug guidelines: GPU node triage","url":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/gpu-node-triage.html"},{"title":"Kokolis et al., Revisiting Reliability in Large-Scale ML Research Clusters","url":"https://arxiv.org/html/2410.21680v2"},{"title":"Slurm HealthCheckProgram (the program must drain the node itself)","url":"https://slurm.schedmd.com/slurm.conf.html"},{"title":"LBNL Node Health Check (NHC), which offlines with `scontrol update State=DRAIN` by default","url":"https://github.com/mej/nhc"},{"title":"NVIDIA NVSentinel fault quarantine (opt-in; cordons on CEL rules with a circuit breaker)","url":"https://docs.nvidia.com/nvsentinel/getting-started/overview"},{"title":"Kubernetes Node Problem Detector, which reports conditions for remedy systems (it does not cordon itself)","url":"https://github.com/kubernetes/node-problem-detector"}]},{"id":"drain_node","name":"Drain a node (move running work off)","description":"Cordon the node, then evict or requeue the jobs still running on it, so a repair can start now rather than when they finish.","mechanism":"Kubernetes: the approved drain is `kubectl drain \u003cnode> --ignore-daemonsets` with its guards on. It evicts through the Eviction API, so PodDisruptionBudgets are respected (never `--disable-eviction`). Without `--force` it refuses pods that no controller manages, which nothing would recreate. Without `--delete-emptydir-data` it refuses pods using emptyDir, and that flag is added only when the approver explicitly accepts the loss of that pod's local data. A refused pod stops the drain with the node cordoned, and the list goes back to the approver; DaemonSet and static (mirror) pods stay. `kubectl drain` first cordons the node, setting `spec.unschedulable`; because the drain is approved, that cordon belongs to the approving person and is recorded under their name in the incident. Slurm: after State=DRAIN, list jobs with `squeue -w \u003cnode>` and requeue those that allow it with `scontrol requeue \u003cjobid>`; `scontrol update NodeName=\u003cnode> State=DOWN Reason=...` instead terminates every running and suspended job on the node. NVSentinel's node drainer can evict only the pods using an unhealthy GPU when a GPU reset will do.","tier":"approval","preconditions":["The node is cordoned first.","Each affected job is listed with its owner and last checkpoint age, and the owners are notified.","Requeue is allowed for the jobs (Slurm --requeue / JobRequeue) or their PodDisruptionBudgets permit the eviction.","Kubernetes: every pod to be moved has a controller that recreates it (no `--force`), and a pod using emptyDir is drained only if the approver accepts the loss of its local data (`--delete-emptydir-data`).","Kubernetes: cordon_node's toleration guarantee holds, or the approver has checked that no workload that could land on the node tolerates the taint; a blanket `operator: Exists` toleration also tolerates the `node.kubernetes.io/unschedulable` taint of the cordon, so a replacement pod could be scheduled straight back onto the node.","The capacity guard of cordon_node still holds after the drain."],"verification":"Only DaemonSet and static (mirror) pods (Kubernetes) or no job steps (`squeue -w \u003cnode>` empty) remain on the node, and on Kubernetes no new non-DaemonSet pod lands there afterwards; every pod `kubectl drain` refused is resolved by the approver; the evicted jobs restart elsewhere and their throughput returns to their pre-incident baseline (at least 3 samples within 2%).","rollback":"Not reversible for the evicted work, which restarts from its checkpoint. The node returns in separate steps, each by its owner, after its post-repair check. The incident's own hold is released through cordon_node's rollback, with nothing else holding the node; on Slurm a person approves that release. On Kubernetes the `spec.unschedulable` cordon that `kubectl drain` set belongs to the approving person: only that person, or a separately approved release, clears it.","references":[{"title":"Kubernetes: Safely drain a node","url":"https://kubernetes.io/docs/tasks/administer-cluster/safely-drain-node/"},{"title":"kubectl drain (--ignore-daemonsets, --force, --delete-emptydir-data)","url":"https://kubernetes.io/docs/reference/kubectl/generated/kubectl_drain/"},{"title":"Kubernetes taints and tolerations","url":"https://kubernetes.io/docs/concepts/scheduling-eviction/taint-and-toleration/"},{"title":"Slurm scontrol","url":"https://slurm.schedmd.com/scontrol.html"},{"title":"Slurm sbatch (--requeue)","url":"https://slurm.schedmd.com/sbatch.html"},{"title":"kubectl drain","url":"https://kubernetes.io/docs/tasks/administer-cluster/safely-drain-node/"},{"title":"Slurm scontrol (requeue, State=DOWN)","url":"https://slurm.schedmd.com/scontrol.html"},{"title":"NVIDIA NVSentinel node drainer (opt-in)","url":"https://docs.nvidia.com/nvsentinel/getting-started/overview"}]},{"id":"gpu_reset","name":"Reset a GPU on an idle, cordoned node","description":"Clear a GPU's hardware and software state without rebooting the node: applies pending row remaps, blacklists pending retired pages, and clears faults whose recovery action is Reset.","mechanism":"`nvidia-smi -r -i \u003cgpu>` as root, with no process on the device (including monitoring clients). The nvidia-smi documentation states this as a requirement of `-r` (no CUDA, graphics or monitoring application, such as another nvidia-smi, may be using the device) but does not say the command refuses when one is, so the scheduler must keep work off the GPU until the reset is done. Proposed policy: a person approves every reset, on every scheduler. The node is held first (cordon_node), so no new job is scheduled there. The request lists the node's holds; the jobs allocated the target GPU or any NVLink peer reset with it (Slurm: `GresUsed` in `scontrol show node \u003cnode>`, `scontrol show job -d` for jobs still on the node; Kubernetes: the pods on the node, `kubectl get pods -A --field-selector spec.nodeName=\u003cnode>`); and the processes `nvidia-smi` shows on those GPUs. Immediately before the reset, `nvidia-smi` is re-checked for processes on the GPU and those peers, as an additional guard (it also catches node-local clients such as monitoring agents, which the scheduler does not track); the check alone cannot exclude a process that starts after it. Before Ampere, or with Fabric Manager not running, every GPU NVLink-connected to it must be reset in the same command; on Ampere NVSwitch systems Fabric Manager must be running; from Hopper the Fabric Manager dependency is removed. In a VM, GPU reset depends on the hypervisor; otherwise restart the VM. Read the required action first from the NVML recovery action (DCGM_FI_DEV_GPU_RECOVERY_ACTION, field 1523; `nvidia-smi --query-gpu=gpu_recovery_action`). For pre-Ampere page retirement the cheaper equivalents, in order, are: let the GPU detach (persistence mode off), reset, reload nvidia.ko, reboot.","tier":"approval","preconditions":["Proposed policy: a person approves the reset, on every scheduler, with the node held and the request listing the jobs (Slurm) or pods (Kubernetes) allocated the target GPU or any NVLink peer reset with it, and the processes `nvidia-smi` shows on them; `nvidia-smi` is re-checked immediately before the reset as an additional guard.","The recovery action reads Reset or Drain and Reset, or the triggering Xid's catalogue bucket is RESET_GPU, or a row remap or page retirement is pending.","On Ampere NVSwitch systems Fabric Manager is running; on bare metal, not a VM (else restart the VM through its API).","With MIG enabled, every GPU instance on the device is idle.","A node also held by someone else (a person's drain Reason, a maintenance reservation, another system's taint) is reset only with that holder's approval; the evidence goes to them."],"verification":"After the reset: recovery action None; row remap pending 0 (DCGM_FI_DEV_ROW_REMAP_PENDING) or Pending Page Blacklist No (`nvidia-smi -q -d PAGE_RETIREMENT`); row remap failure 0; `dcgmi diag -r 2 -i \u003cgpu ids>` passes, naming only the GPUs just reset (the target and any peers reset with it; unqualified, it runs on every GPU of the node, including any a job is using); then only the incident's own hold is released, under cordon_node's rollback rule (no other hold or open incident on the node); on Slurm a person approves that release; otherwise the node stays held for whoever holds it. The first job afterwards should show the GPU's step time in line with its class peers.","rollback":"Not reversible (state is cleared by design). If the GPU does not come back (Xid 79, or it is missing from `nvidia-smi`), escalate to node_reboot and then rma_replace_hardware.","references":[{"title":"nvidia-smi documentation (-r, --gpu-reset; GPU Recovery Action)","url":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"},{"title":"NVIDIA GPU debug guidelines: GPU node triage (reset capabilities and limitations)","url":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/gpu-node-triage.html"},{"title":"NVIDIA GPU memory error management: error recovery and response flags","url":"https://docs.nvidia.com/deploy/a100-gpu-mem-error-mgmt/error-recovery-and-response-flags.html"},{"title":"NVIDIA dynamic page retirement: blacklisting and ECC error recovery","url":"https://docs.nvidia.com/deploy/dynamic-page-retirement/blacklisting-and-ecc-error-recovery.html"},{"title":"DCGM field identifiers","url":"https://docs.nvidia.com/datacenter/dcgm/latest/dcgm-api/dcgm-api-field-ids.html"},{"title":"nvidia-smi --gpu-reset","url":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"},{"title":"NVIDIA NVSentinel fault remediation and janitor (opt-in GPU reset)","url":"https://docs.nvidia.com/nvsentinel/getting-started/overview"}]},{"id":"restart_from_checkpoint","name":"Restart a stopped job from its last checkpoint","description":"Relaunch a job that has already stopped (crash, NCCL timeout abort, node failure) from its latest checkpoint, with the failed node excluded.","mechanism":"Slurm: a job submitted with `sbatch --requeue` is requeued after node failure and restarts its batch script with the same job id; otherwise `scontrol requeue \u003cjobid>`. Slurm's own requeue on node failure does not check that the processes stopped, so it does not count as confirmation. With the suspect node already DRAIN it is not placed back there; or resubmit with `--exclude=\u003cnode>`. torchrun `--max-restarts=N`: on a worker failure all workers are stopped and restarted, and the script must load its checkpoint itself. Kubernetes training operators have their own restart policies (not verified here).","tier":"automatic","preconditions":["The job's processes are confirmed stopped: every step's exit was reported by a node that still responds (Slurm job state FAILED, CANCELLED, TIMEOUT, OUT_OF_MEMORY or PREEMPTED with exit codes from slurmd; Kubernetes pods Terminated with exit codes from a Ready kubelet), or every node that lost contact was fenced before the relaunch (BMC chassis power off, or rebooted with a new boot id). NODE_FAIL, a node DOWN after SlurmdTimeout, a trailing `*` in sinfo or Ready Unknown alone is not proof; then the relaunch needs operator approval. A merely slow job uses rebalance_work or exclude_and_restart.","The owner's policy allows restarts (sbatch --requeue or JobRequeue, torchrun --max-restarts) and its budget is not used up.","A readable checkpoint exists.","The suspect node or GPU is cordoned or excluded.","The failure signature is not deterministic in the application: the same Xid 13/31 or the same traceback on different nodes twice stops automatic restarts and tickets the job owner."],"verification":"The job resumes at the checkpoint's step and, over at least 3 samples, its throughput is within 2% of its pre-failure healthy value; the triggering signal does not recur.","rollback":"Not applicable; the job can be cancelled (`scancel \u003cjobid>`).","references":[{"title":"Slurm sbatch","url":"https://slurm.schedmd.com/sbatch.html"},{"title":"PyTorch torchrun (elastic launch)","url":"https://docs.pytorch.org/docs/2.15/elastic/run.html"},{"title":"The Llama 3 Herd of Models, section 3.3.4","url":"https://arxiv.org/html/2407.21783v3"},{"title":"Kokolis et al., Revisiting Reliability in Large-Scale ML Research Clusters","url":"https://arxiv.org/html/2410.21680v2"},{"title":"Slurm sbatch --requeue and scontrol requeue","url":"https://slurm.schedmd.com/sbatch.html"},{"title":"torchrun --max-restarts (PyTorch elastic)","url":"https://docs.pytorch.org/docs/2.15/elastic/run.html"},{"title":"MegaScale robust training driver (evicts faulty nodes, resumes from the latest checkpoint)","url":"https://arxiv.org/html/2402.15627v1"}]},{"id":"exclude_and_restart","name":"Stop a running job and restart it without a suspect node","description":"For a job still running but degraded by one node or GPU: stop it, exclude the node, restart from checkpoint.","mechanism":"Slurm: `scontrol update NodeName=\u003cnode> State=DRAIN Reason=\"\u003cincident> \u003csignal>\"` unless another owner already holds the node (the same check as cordon_node; the node is then already excluded and is not re-tagged), then `scontrol requeue \u003cjobid>` (or cancel and resubmit with `sbatch --exclude=\u003cnode>`). torchrun elastic: a membership change stops and restarts all workers. MegaScale's driver does the equivalent: suspend training, run self-checks, have Kubernetes evict the faulty nodes and add healthy ones, resume from the latest checkpoint.","tier":"approval","preconditions":["A spare node is available or the job accepts a smaller world size.","The latest checkpoint is recent enough that the restart costs less than the expected slowdown.","The job owner approves.","The suspect node is cordoned."],"verification":"After the restart, at least 3 samples of throughput within 2% of the pre-incident healthy value, and no rank is flagged.","rollback":"Not reversible for the job. The excluded node returns only through cordon_node's rollback after its post-repair check; on Slurm a person approves that release.","references":[{"title":"Slurm sbatch (--exclude, --requeue)","url":"https://slurm.schedmd.com/sbatch.html"},{"title":"MegaScale: Scaling LLM training to more than 10,000 GPUs","url":"https://arxiv.org/html/2402.15627v1"},{"title":"Slurm scontrol requeue and sbatch --exclude","url":"https://slurm.schedmd.com/sbatch.html"},{"title":"MegaScale robust training driver","url":"https://arxiv.org/html/2402.15627v1"},{"title":"torchrun elastic membership changes","url":"https://docs.pytorch.org/docs/2.15/elastic/run.html"}]},{"id":"reroute_traffic","name":"Route collective traffic around a bad port, cable or link","description":"Take a failing NIC port, cable or switch link out of the path, either for one job (NCCL interface selection) or for the fabric (disable the switch port so routing avoids it).","mechanism":"Per job (needs a restart): set `NCCL_IB_HCA=^mlx5_3` (a leading ^ makes the list an exclude list) so NCCL stops using that HCA. Fabric: disable the switch port with `ibportstate \u003clid> \u003cport> disable` (enable, disable and reset are allowed on switch ports only) so the subnet manager routes around it; UFM and RoCE/ECMP equivalents exist but were not verified for this map.","tier":"approval","preconditions":["The failing port is identified from counters on both ends of the link, not from one job's slowness alone.","A redundant path exists and the remaining capacity is acceptable.","A network engineer approves the change and its window."],"verification":"Error counters stop rising on the remaining path; NCCL tests (all_reduce_perf) between the affected nodes match the pairwise baseline, run on idle nodes the approved window reserves for them, not on nodes where the job is still running; the job's throughput returns within 2% of its healthy value.","rollback":"`ibportstate \u003clid> \u003cport> enable`; remove the NCCL_IB_HCA override at the next restart.","references":[{"title":"NCCL environment variables","url":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/env.html"},{"title":"ibportstate(8)","url":"https://linux.die.net/man/8/ibportstate"},{"title":"NVIDIA GPU debug guidelines: network testing","url":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/gpu-node-triage.html"},{"title":"NCCL environment variables (NCCL_IB_HCA)","url":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/env.html"},{"title":"infiniband-diags ibportstate","url":"https://linux.die.net/man/8/ibportstate"}]},{"id":"schedule_firmware_update","name":"Schedule a firmware or driver update to the fleet baseline","description":"Bring a node's GPU VBIOS/firmware, driver, NIC firmware or BIOS/BMC back to the fleet baseline in a maintenance window, canary first.","mechanism":"Reserve the nodes: `scontrol create reservation ReservationName=fw-\u003cid> Nodes=\u003cnodes> StartTime=\u003ct> Duration=\u003cd> Flags=MAINT` (the MAINT flag marks a maintenance reservation; IGNORE_JOBS ignores running jobs when creating it). Then run the vendor's update tool, reboot, run_active_diagnostic, and return to service. On Kubernetes, the GPU Operator's driver manager handles driver versions (its upgrade procedure was not read for this map).","tier":"approval","preconditions":["The target versions are the approved fleet baseline, and that baseline has passed on a canary.","The nodes are in a maintenance reservation and drained.","The vendor's update and downgrade path for this part is known."],"verification":"Inventory reads the target versions (DCGM_FI_DEV_VBIOS_VERSION, the driver version, `nvidia-smi -q`); `dcgmi diag -r 3 -i \u003cnode gpu ids>` passes on the drained node; a matched benchmark on the canary is within the class baseline.","rollback":"Re-flash the previous version where the vendor supports a downgrade; otherwise not reversible.","references":[{"title":"Slurm scontrol (reservations)","url":"https://slurm.schedmd.com/scontrol.html"},{"title":"Kokolis et al., Revisiting Reliability in Large-Scale ML Research Clusters","url":"https://arxiv.org/html/2410.21680v2"},{"title":"Slurm maintenance reservations (scontrol create reservation, Flags=MAINT)","url":"https://slurm.schedmd.com/scontrol.html"},{"title":"NVIDIA GPU Operator (driver and component lifecycle on Kubernetes)","url":"https://docs.nvidia.com/datacenter/cloud-native/gpu-operator/latest/overview.html"}]},{"id":"node_reboot","name":"Reboot a node once it is idle","description":"Reboot a node whose fault needs it (recovery action Reboot, Xid bucket RESTART_BM, an unresponsive OS), without killing work still running on it.","mechanism":"Proposed policy: a person approves every reboot, on every scheduler. Slurm: first read `scontrol show node \u003cnode>`; if another owner holds the node (a DRAIN, DOWN or FAIL state whose Reason does not name this incident, or a maintenance reservation), the request goes to that holder and the node is not re-tagged, because the reboot's `reason=` replaces the Reason and would erase that hold. After approval, `scontrol reboot ASAP nextstate=DOWN reason=\"\u003cincident>\" \u003cnode>`. ASAP adds DRAIN, so the scheduler itself starts no new job on the node and runs the reboot only once no job is allocated there; after slurmd starts the HealthCheckProgram runs once; nextstate=DOWN keeps the node out until the post-repair check passes; a node that does not register within ResumeTimeout is marked DOWN. ASAP waits only for jobs, not for processes started outside Slurm (SSH sessions, cron, at, systemd user services), so the request lists every non-system user's process on the node that sits outside a Slurm job cgroup (`/proc/\u003cpid>/cgroup`). An unresponsive OS: out-of-band power cycle, `ipmitool -H \u003cbmc> chassis power cycle`. Kubernetes: with the incident's taint in place and the pods then on the node (`kubectl get pods -A --field-selector spec.nodeName=\u003cnode>`) listed in the request, reboot through the node's management (NVSentinel's janitor does this through cloud APIs or node commands). A pod's controller type does not show that its work is idle (a progressing worker can run as a DaemonSet or static pod), and pods bound with `spec.nodeName` bypass taints and cordons, so the approver reads that list.","tier":"approval","preconditions":["The trigger is the recovery action Node Reboot Required, an Xid in the RESTART_BM bucket, or the node is unresponsive.","Proposed policy: a person approves the reboot, on every scheduler. The request lists the jobs on the node and, on Slurm, every non-system user's process outside a Slurm job cgroup, which `scontrol reboot ASAP` does not wait for; on Kubernetes, the pods on the node, with the incident's taint in place. An unresponsive node is never rebooted automatically: a scheduler DOWN or NODE_FAIL, a trailing `*` in sinfo or Kubernetes Ready Unknown does not show that its processes stopped, since they may still run behind a management-network partition; neither does a hard-lockup report (the kernel's check works per CPU), nor a serial-over-LAN console line or SEL entry (history, not current state). Fencing it is the power cycle itself, so an operator approves it.","No other owner holds the node: no DRAIN, DOWN or FAIL state whose Reason does not name this incident, no maintenance reservation, no other system's taint. Otherwise the reboot needs the holder's approval and the node is not re-tagged.","The circuit breaker of cordon_node is closed."],"verification":"The node registers; its GPU count equals inventory; the boot log has no new Xid; `dcgmi diag -r 2 -i \u003cnode gpu ids>` (every GPU of the node, which runs no job) and the node health check pass; only then is the incident's own hold released under cordon_node's rollback rule (no other hold or open incident on the node), with `scontrol update NodeName=\u003cnode> State=RESUME` once a person approves it or by removing the incident's taint.","rollback":"Not reversible; nothing to undo. `scontrol cancel_reboot \u003cnode>` cancels a reboot that has not run yet.","references":[{"title":"Slurm scontrol (reboot ASAP, nextstate)","url":"https://slurm.schedmd.com/scontrol.html"},{"title":"NVIDIA Xid catalogue (resolution buckets)","url":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"title":"NVIDIA GPU debug guidelines: GPU node triage","url":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/gpu-node-triage.html"},{"title":"ipmitool(1)","url":"https://linux.die.net/man/1/ipmitool"},{"title":"Slurm scontrol reboot and RebootProgram","url":"https://slurm.schedmd.com/scontrol.html"},{"title":"ipmitool chassis power","url":"https://linux.die.net/man/1/ipmitool"},{"title":"NVIDIA NVSentinel janitor (opt-in)","url":"https://docs.nvidia.com/nvsentinel/getting-started/overview"}]},{"id":"rollback_software_change","name":"Roll back a software, driver or configuration change","description":"Return a job's or node's software (container image, framework, NCCL, driver) or a device setting (power limit, locked clocks, ECC mode, MIG mode) to the known-good baseline.","mechanism":"Job: relaunch with the previous image tag or library versions. Node: reinstall the pinned driver package (or the GPU Operator's pinned driver). Device settings: `nvidia-smi -i \u003cgpu> -pl \u003cdefault W>` (power limit), `nvidia-smi -i \u003cgpu> -rgc` (reset locked GPU clocks), `nvidia-smi -i \u003cgpu> -e 1` (ECC on; takes effect after the next reboot and persists), `nvidia-smi -i \u003cgpu> -mig 0` (MIG off).","tier":"approval","preconditions":["The change and its time are identified (a settings change record, an image or package diff) and precede the regression.","The baseline to return to is known and was healthy on the same workload.","The change's owner approves."],"verification":"A matched before/after on the same workload and hardware class: throughput back within 2% of the pre-change baseline, and the setting or version reads back as the baseline.","rollback":"Re-apply the change.","references":[{"title":"nvidia-smi documentation","url":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"},{"title":"nvidia-smi (power limit, clocks, ECC and MIG modes)","url":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"},{"title":"NVIDIA GPU Operator (pinned driver versions on Kubernetes)","url":"https://docs.nvidia.com/datacenter/cloud-native/gpu-operator/latest/overview.html"}]},{"id":"restart_system_service","name":"Restart a node daemon the GPU stack depends on","description":"Restart a daemon that serves only this node: nvidia-persistenced, nvidia-fabricmanager, the DCGM host engine (nv-hostengine) or dcgm-exporter, slurmd, chronyd, or the container runtime and kubelet. Shared-fabric services are excluded (see preconditions).","mechanism":"`systemctl restart \u003cunit>` and `systemctl is-active \u003cunit>`; on Kubernetes with the GPU Operator these run as pods: delete the pod and let its DaemonSet recreate it. Fabric Manager on NVSwitch systems: restart only with no GPU jobs on the node.","tier":"approval","preconditions":["The service is identified as down or failing by its own health check, not inferred from a job symptom.","The service serves only this node. Shared-fabric services are excluded even when hosted on a compute node: the InfiniBand subnet manager (for example opensm) and its failover, UFM, switch management, routing engines, and any Fabric Manager instance that serves NVLink across several nodes. Restarting or failing them over goes through correct_fabric_configuration (human only).","For Fabric Manager, the persistence daemon or the container runtime: no GPU jobs on the node.","An operator approves."],"verification":"The unit is active and the dependent check passes: DCGM fields update again, `nvidia-smi` answers, the Fabric Manager log shows the fabric up, `chronyc tracking` shows a normal leap status.","rollback":"Not needed; stop the unit or restart it again.","references":[{"title":"NVIDIA GPU debug guidelines: best practices (software that must be loaded)","url":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/best-practices.html"},{"title":"NVIDIA Xid catalogue (WORKFLOW_XID_45)","url":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"title":"LBNL NHC check_ps_service (checks a daemon is running)","url":"https://github.com/mej/nhc"},{"title":"NVIDIA GPU Operator (manages driver, toolkit, device plugin and DCGM as pods)","url":"https://docs.nvidia.com/datacenter/cloud-native/gpu-operator/latest/overview.html"}]},{"id":"power_thermal_mitigation","name":"Mitigate power or thermal stress","description":"Restore a GPU's power limit to the fleet default, cap a GPU's power to keep it out of hardware slowdown, raise cooling through the BMC, or ask facilities to fix inlet temperature or airflow.","mechanism":"`nvidia-smi -i \u003cgpu> -pl \u003cW>` (root; between the GPU's min and max limits); read back the enforced limit (DCGM_FI_DEV_ENFORCED_POWER_LIMIT in dcgm-exporter's CSV; DCGM_FI_DEV_BOARD_POWER_LIMIT_ENFORCED_WATTS, field 164, on the current DCGM field-ID page). Fan and cooling policy through the BMC is vendor-specific and not verified here. Inlet temperature and rack power are facilities tickets.","tier":"approval","preconditions":["The throttle reason is identified (thermal, power cap, power brake) from clock-event reasons or violation counters, not inferred from low clocks alone.","The facility or platform owner approves caps and cooling changes."],"verification":"The throttle-reason bits clear (HW thermal slowdown, HW power brake), the violation counters stop rising, the temperature stays below the slowdown temperature, and the rank's step time returns within its class peers.","rollback":"`nvidia-smi -i \u003cgpu> -pl \u003cprevious W>`.","references":[{"title":"nvidia-smi documentation (-pl, clocks event reasons)","url":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"},{"title":"The Llama 3 Herd of Models, section 3.3.4","url":"https://arxiv.org/html/2407.21783v3"},{"title":"nvidia-smi --power-limit","url":"https://docs.nvidia.com/deploy/nvidia-smi/index.html"},{"title":"DCGM thermal and power health watches (dcgmi health -s t)","url":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/feature-overview.html"}]},{"id":"abort_and_requeue_job","name":"Abort a hung job and requeue it","description":"Kill a job that makes no progress (all ranks stuck in or before a collective) and requeue it from its checkpoint, before the framework's own timeout would.","mechanism":"`scancel \u003cjobid>`, or `scontrol requeue \u003cjobid>` for a job that allows requeue; under torchrun the restart policy relaunches. In PyTorch a NCCL timeout fires when a collective has not completed within several minutes (Meta's study), and the job then stops; this fix acts earlier, on a hang finding.","tier":"approval","preconditions":["A hang finding that names the ranks behind and the collective, with no rank's progress changing for the configured interval.","No checkpoint write or evaluation is known to be running.","The job owner or operator approves."],"verification":"After the requeue the step counter advances and every rank reports again (mechanism and interval: Pending); no hang finding at the same collective over an observation window (length: Pending).","rollback":"Not reversible.","references":[{"title":"Slurm scontrol (requeue)","url":"https://slurm.schedmd.com/scontrol.html"},{"title":"Kokolis et al., Revisiting Reliability in Large-Scale ML Research Clusters (NCCL timeouts)","url":"https://arxiv.org/html/2410.21680v2"},{"title":"Slurm scancel and scontrol requeue","url":"https://slurm.schedmd.com/scontrol.html"},{"title":"torchrun restart policy","url":"https://docs.pytorch.org/docs/2.15/elastic/run.html"}]},{"id":"query_health_watches","name":"Query health watches","description":"Read the health watches already running on a node, and the results of the site's own node health checks, to support or rule out a suspected fault. It starts no test.","mechanism":"`dcgmi health -g \u003cgroup> -c` queries the background health watches already set with `dcgmi health -s`; it enables no watch and starts no diagnostic (non-invasive). The group names the GPUs to read. The results of the site's own LBNL NHC runs (for example a node Reason starting `NHC:`) are read as a passive signal. Proposed policy: NHC is not run automatically: its configuration (including detached mode, which re-executes `nhc` without its command-line arguments) can re-enable node marking, whose `node-mark-online` helper runs `scontrol update State=RESUME` for an `NHC:` hold. Running NHC, and every active test, is run_active_diagnostic.","tier":"automatic","preconditions":["Reads only: `dcgmi health -g \u003cgroup> -c` against watches the site already set with `dcgmi health -s`, and the results of the site's own NHC runs (such as a Reason starting `NHC:`). It never sets a watch, runs `dcgmi diag` or runs NHC.","The DCGM version matches the installed driver.","Results are recorded with GPU UUIDs and the incident id."],"verification":"The health watches show no Warning or Error on the GPUs read. A clean read does not return hardware to service: that needs run_active_diagnostic's checks and cordon_node's release rule.","rollback":"Not applicable.","references":[{"title":"DCGM feature overview: health and diagnostics (active health checks are invasive and need exclusive GPU access)","url":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/feature-overview.html#health-and-diagnostics"},{"title":"DCGM dcgmi/Health.cpp (`dcgmi health -c` queries existing health watches; it enables none)","url":"https://github.com/NVIDIA/DCGM/blob/master/dcgmi/Health.cpp"},{"title":"LBNL NHC main script (node marking; detached mode re-executes nhc without its arguments)","url":"https://github.com/mej/nhc/blob/master/nhc"},{"title":"LBNL NHC node-mark-online (Slurm State=RESUME for an NHC: hold)","url":"https://github.com/mej/nhc/blob/master/helpers/node-mark-online"},{"title":"NVIDIA DCGM health watches (dcgmi health)","url":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/feature-overview.html#health-and-diagnostics"},{"title":"LBNL Node Health Check (NHC), results read only","url":"https://github.com/mej/nhc"}]},{"id":"run_active_diagnostic","name":"Run active diagnostics","description":"Run a diagnostic on an idle node or GPU to confirm a suspected fault, or as the gate before returning hardware to service.","mechanism":"Covers every active test: `dcgmi diag` at every level, `-r 1` included, memtest, NCCL tests, perftest, ibdiagnet and other active probes (matched benchmarks, mount read/write checks), and running LBNL NHC, whose configuration can re-enable node marking (the passive read of the site's own NHC results is query_health_watches). These are active diagnostics: NVIDIA's DCGM feature overview calls even the quick prologue checks invasive, requiring exclusive access to the target GPUs. They occupy the GPUs and nodes they test. Proposed policy: a person approves each run on every scheduler. Every `dcgmi diag` names its targets: `-i \u003cgpu ids>` (`--entity-id`, a comma-separated entity list such as `gpu:0,gpu:1`) or `-g \u003cgroup>` (`--group`, a persistent DCGM group; not combined with `-i`). Without either it runs on all GPUs and all NVIDIA CPUs of the node (`*,cpu:*`), including GPUs a running job is using, so it is never run unqualified. The targets are exactly the GPUs the run is protected for: in a job's prolog or epilogue, the GPUs Slurm allocates to that job; on a held node, GPUs no job is allocated (the GPU under repair and any NVLink peers reset with it). `\u003cnode gpu ids>` in this map means every GPU of the node and is used only on a node with no job at all. `dcgmi diag -r 1 -i \u003cgpu ids>` (readiness, under 2.5 s), `-r 2` (epilogue on failure), `-r 3` / `-r 4` (post-mortem: up to 35 min / 2.25 h on 8-GPU Hopper systems), each with the same `-i` or `-g`. Node checks: the site's own LBNL NHC as Slurm's HealthCheckProgram. Network: NCCL tests all_reduce_perf between node pairs, and perftest (`ib_write_bw`, `ib_read_lat`), only between nodes with no job at all; `ibdiagnet` on the node's links. A job-start probe would run on every rank (workload: Pending). NVIDIA's field diagnostic is the authoritative test and is usually required before an RMA.","tier":"approval","preconditions":["Proposed policy: `dcgmi diag` at every level (`-r 1` included), memtest, NCCL tests, perftest, ibdiagnet and other active probes, and running NHC, need a person's approval on every scheduler; the request names the GPUs or nodes under test and lists the jobs (Slurm) or pods (Kubernetes) on them.","Every `dcgmi diag` names explicit targets with `-i \u003cgpu ids>` or `-g \u003cgroup>`, exactly the GPUs protected above (the job's own allocation in a prolog or epilogue; GPUs no job is allocated on a held node); without them it runs on all GPUs and NVIDIA CPUs of the node. Node-level and NCCL tests run only on nodes with no job at all.","The DCGM version matches the installed driver.","Results are recorded with GPU UUIDs and the incident id."],"verification":"Every test passes on the targets it named; the health watches (query_health_watches) show no Warning or Error; a matched benchmark is within the GPU class's baseline. A pass makes the node eligible to return but does not release it: the release follows cordon_node's rollback rule (only the incident's own hold, nothing else holding the node; on Slurm a person approves the `State=RESUME`).","rollback":"Not applicable.","references":[{"title":"DCGM diagnostics","url":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/dcgm-diagnostics.html"},{"title":"DCGM feature overview: health and diagnostics (active health checks are invasive and need exclusive GPU access)","url":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/feature-overview.html#health-and-diagnostics"},{"title":"NVIDIA GPU debug guidelines: GPU node triage","url":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/gpu-node-triage.html"},{"title":"LBNL NHC main script (node marking; detached mode re-executes nhc without its arguments)","url":"https://github.com/mej/nhc/blob/master/nhc"},{"title":"LBNL NHC node-mark-online (Slurm State=RESUME for an NHC: hold)","url":"https://github.com/mej/nhc/blob/master/helpers/node-mark-online"},{"title":"NVIDIA DCGM diagnostics (dcgmi diag)","url":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/dcgm-diagnostics.html"},{"title":"LBNL Node Health Check (NHC)","url":"https://github.com/mej/nhc"},{"title":"IBM Autopilot (PCIe bandwidth, remapped rows, power slowdown, DCGM diag, ping, iperf3)","url":"https://github.com/IBM/autopilot"},{"title":"Microsoft SuperBench (proactive validation)","url":"https://www.usenix.org/conference/atc24/presentation/xiong"}]},{"id":"rma_replace_hardware","name":"Replace hardware (RMA)","description":"Replace a failed or failing GPU, board, DIMM, PSU or other part through the vendor's RMA process.","mechanism":"Collect `nvidia-bug-report.sh` output, DCGM diagnostics logs, Fabric Manager logs (HGX) and the key kernel log lines; run NVIDIA's field diagnostic (the vendor says when and how); open the RMA with the system vendor; a technician replaces the part; update inventory with the new serial and UUID.","tier":"human_only","preconditions":["The node is cordoned and drained.","The vendor's RMA criterion is met (for example the row-remapping failure flag validated by the field diagnostic, or 60 or more retired pages on pre-Ampere GPUs)."],"verification":"The replacement passes the field diagnostic and `dcgmi diag -r 3 -i \u003cgpu ids>` naming the replacement GPUs (`-i \u003cnode gpu ids>` after a board or node replacement), then a matched benchmark within the class baseline before the node is resumed; the person resuming it first checks that no other hold or open incident remains (cordon_node's rollback rule, under which a Slurm release needs approval).","rollback":"Not reversible.","references":[{"title":"NVIDIA GPU debug guidelines: reporting a GPU issue, running field diagnostics","url":"https://docs.nvidia.com/deploy/gpu-debug-guidelines/gpu-node-triage.html"},{"title":"NVIDIA GPU memory error management: RMA policy","url":"https://docs.nvidia.com/deploy/a100-gpu-mem-error-mgmt/rma-policy-thresholds-for-row-remapping.html"},{"title":"nvidia-bug-report.sh and the field diagnostic (via the system vendor)","url":"https://docs.nvidia.com/deploy/xid-errors/working-with-xid-errors.html"}]},{"id":"reseat_or_replace_cable","name":"Reseat or replace a cable, transceiver or riser","description":"A technician reseats or replaces the cable, optic, riser or connector at an identified port or slot.","mechanism":"From the ticket's port or slot: reseat, clean or replace the cable or transceiver; for a GPU, check its seating and every power and data connection (the Xid catalogue's CHECK_MECHANICALS bucket, for example Xid 54, auxiliary power not connected); for NVLink, check the link's mechanical connections and reseat (Xid 74 workflow).","tier":"human_only","preconditions":["The port or slot is identified from counters on both ends or from the Xid's PCI address.","The node is cordoned and drained."],"verification":"The link trains at its expected speed and width; its error counters stay flat over a soak; NCCL tests between the affected nodes match the pairwise baseline.","rollback":"Not applicable.","references":[{"title":"NVIDIA Xid catalogue (CHECK_MECHANICALS, WORKFLOW_NVLINK_ERR)","url":"https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html"},{"title":"infiniband-diags ibportstate (query link speed and width)","url":"https://linux.die.net/man/8/ibportstate"}]},{"id":"tune_job_configuration","name":"Change the job's own configuration and restart it","description":"Change settings that belong to the job rather than the fleet: data-loader workers and prefetch, micro-batch or sequence length, allocator settings, garbage-collection control, NCCL network selection and timeouts, CPU/GPU binding, or the scheduler request (constraints, node list, size). Then restart from the last checkpoint, or launch fresh when the job has no training state yet. No other response here covers a change to the job's own settings: rollback_software_change reverts a change, rebalance_work changes batch shares only.","mechanism":"Job environment and arguments, for example: torch.utils.data.DataLoader(num_workers=, prefetch_factor=, persistent_workers=, timeout=); PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True (max_split_size_mb only as a last resort); NCCL_IB_HCA, NCCL_SOCKET_IFNAME, NCCL_CROSS_NIC, NCCL_IB_TIMEOUT, NCCL_IB_RETRY_CNT, NCCL_IB_TC; scheduler request edits (sbatch/scontrol update of constraints, partition, node list) or a resubmission.","tier":"approval","preconditions":["The job owner, or a policy the owner set, approves the specific change.","When the job resumes from training state, a durable, complete checkpoint exists to restart from. A job with no training state yet (for example a first submission stuck pending, job.stuck_pending) is launched fresh with the changed request.","The change is recorded with the run (before and after values) so a regression incident can compare runs.","A change that only masks a hardware symptom (e.g. raising NCCL_IB_TIMEOUT) is paired with a ticket for the underlying fault."],"verification":"Matched re-measurement of the metric that motivated the change (loader wait share, step time, samples/s, OOM recurrence, NCCL device selection) after the restart, against the run before it; throughput counts as recovered when at least 3 samples are within 2% of the healthy value.","rollback":"Restore the previous settings and restart from checkpoint.","references":[{"title":"PyTorch torch.utils.data","url":"https://docs.pytorch.org/docs/2.15/data.html"},{"title":"PyTorch CUDA semantics: memory management","url":"https://docs.pytorch.org/docs/2.15/notes/cuda.html"},{"title":"NCCL environment variables","url":"https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/env.html"},{"title":"MegaScale: Scaling LLM Training to More Than 10,000 GPUs","url":"https://arxiv.org/abs/2402.15627"},{"title":"PyTorch DataLoader options","url":"https://docs.pytorch.org/docs/2.15/data.html"},{"title":"PyTorch CUDA caching allocator configuration","url":"https://docs.pytorch.org/docs/2.15/notes/cuda.html"},{"title":"Slurm scontrol update / sbatch","url":"https://slurm.schedmd.com/scontrol.html"}]},{"id":"correct_fabric_configuration","name":"Correct network fabric configuration (QoS, PFC/ECN, routing, subnet manager)","description":"Fix a configuration error in the network itself: PFC/ECN thresholds or traffic-class mapping inconsistent between NICs and switches, a subnet-manager or routing-engine setting that produces bad routes, or adaptive-routing settings. Distinct from reroute_traffic (moving flows off a bad path) because it changes fabric-wide settings that every tenant depends on. It is also the action for restarting or failing over the subnet manager, UFM or other shared-fabric services, which restart_system_service excludes.","mechanism":"Switch QoS/PFC/ECN configuration through the switch OS or fabric manager; SM configuration and controlled restart or failover (verify with sminfo); validation with ibdiagnet before and after; NIC-side settings through the vendor's configuration tools.","tier":"human_only","preconditions":["A network engineer has identified the fault with ibdiagnet output, switch-side counters, or sminfo and the SM log.","The change is tested on a non-production segment or applied in a maintenance window.","A standby SM exists before restarting or reconfiguring the master SM.","The previous configuration is saved for rollback."],"verification":"ibdiagnet sweep clean after the change; pause, CNP and transmit-wait rates back to baseline on affected ports; multi-node nccl-tests all_reduce_perf at expected bus bandwidth across the changed segment.","rollback":"Restore the saved switch and SM configuration; re-run the sweep.","references":[{"title":"sminfo(8)","url":"https://man.archlinux.org/man/sminfo.8.en"},{"title":"ibdiagnet: Bit Error Rate (BER)","url":"https://networking-docs.nvidia.com/ibdiagnetutilityum/2.26.0/bit-error-rate-ber"},{"title":"MegaScale: Scaling LLM Training to More Than 10,000 GPUs","url":"https://arxiv.org/abs/2402.15627"},{"title":"Linux mlx5 ethtool counters","url":"https://docs.kernel.org/networking/device_drivers/ethernet/mellanox/mlx5/counters.html"},{"title":"ibdiagnet","url":"https://networking-docs.nvidia.com/ibdiagnetutilityum/2.26.0/bit-error-rate-ber"},{"title":"sminfo (infiniband-diags)","url":"https://man.archlinux.org/man/sminfo.8.en"},{"title":"NVIDIA nccl-tests","url":"https://github.com/NVIDIA/nccl-tests"}]}],"families":[{"id":"scalar_histories","name":"Single-metric histories","statistical_shape":"Ordered (time, value) sequence, often irregular and context-conditioned","examples":["Step-time history","Per-device health/probe speed history","A link rate over time"],"measurement_requirements":["Record whether values are kept per step or per window","Keep each value's direction and unit: raw latency and transformed health scores point in different directions","Global and shared slowdowns need own-history or external controls, not only peers"],"candidate_algorithm_families":["CUSUM as a comparison baseline","Offline PELT with an appropriate cost model","Online mean/residual-change candidates such as ADWIN","Simple robust residual/persistence baselines"],"selection_cautions":["Offline segmentation may use future data: do not report it as online detection delay","Autocorrelation, warmup, workload changes and threshold calibration must be measured","A CUSUM baseline is not presumed correct"],"algorithm":"Pending"},{"id":"multivariate_windows","name":"Multivariate telemetry windows","statistical_shape":"time x features per entity, with masks and aggregation metadata","examples":["Clock/power/temperature/throttle/PCIe/ECC relationships","Per-rank step-timing feature vectors"],"measurement_requirements":["Retain raw readings, or state what median, max and fraction summaries discard","Include node CPU, memory and input features alongside GPU readings","Align differing rates without treating interpolation or missing values as measured data"],"candidate_algorithm_families":["Isolation Forest on context-normalized feature windows","PCA/reconstruction residuals as a linear baseline","Robust covariance where distribution assumptions and dimension/sample ratio permit"],"selection_cautions":["These methods do not automatically model time or causality","Low clocks can be healthy during idle periods; condition on workload/state","Fit scaling/imputation and thresholds on training data only, retaining missingness masks"],"algorithm":"Pending"},{"id":"peer_panels","name":"Peer/cohort panels and tensors","statistical_shape":"entity x time x metric; optional workload/communicator/message-size dimensions","examples":["Matched rank/GPU pace comparisons","One node versus comparable nodes","One link against comparable paths"],"measurement_requirements":["Stable time, run, rank, device and port joins, and compatible-peer membership","Capture whole-cohort and fleet-wide changes as well as isolated outliers","Track batch, work, parallelism and topology changes before normalizing"],"candidate_algorithm_families":["Matched-cohort median/MAD residual baselines","Per-entity and common-mode change detection together","Low-rank/PCA residual experiments after panel alignment"],"selection_cautions":["Do not pool unlike GPU generations/power caps/workloads or arbitrarily match collective positions","A whole cohort regressing can disappear under peer-only normalization","Peer flags are not ground-truth labels"],"algorithm":"Pending"},{"id":"latency_distributions","name":"Latency distributions and ragged sample arrays","statistical_shape":"Comparable-cell bags of durations and time-ordered variable-length step arrays","examples":["Collective latency tails by operation and exact bytes","Step-time variance/burstiness","Per-step lists of collective durations"],"measurement_requirements":["Preserve sample counts, aggregation rule, missing or timed-out operations and the exact measurement cell","Retain samples or adequate, explicitly defined sketches; a median or a low percentile cannot reconstruct p99 or the full distribution"],"candidate_algorithm_families":["Two-sample distribution comparisons such as KS under appropriate assumptions","Tail/variance-effect monitoring with dependence-aware confirmation","PELT with a distribution-sensitive cost as an offline candidate"],"selection_cautions":["KS assumes independent continuous samples; autocorrelation/ties invalidate naive use of its p-value","A distribution change can be an improvement or workload change, not a regression","Correct for repeated comparisons and require practical performance impact"],"algorithm":"Pending"},{"id":"counters_rates","name":"Counters, rates and sparse numeric events","statistical_shape":"Cumulative counts plus reset-aware increments/exposure-normalized rates","examples":["NIC errors/retries/bytes and link-state transitions","ECC increments","Dropped telemetry windows"],"measurement_requirements":["Retain reset, wrap, saturation and readability flags and physical counter units","Record elapsed observation time and relevant traffic exposure","Attributing a shared port to a job needs supporting evidence"],"candidate_algorithm_families":["Change detection on valid rates/residuals","Count-distribution models only after dispersion/exposure assumptions are checked","Deterministic reset/dropout handling as a required baseline"],"selection_cautions":["Never interpret a reset or missing counter as a negative spike or zero traffic","Rare errors and zero-inflated/bursty traffic do not automatically follow a Poisson model","A port-wide increase alone does not identify a job or remote failing component"],"algorithm":"Pending"},{"id":"operation_sequences","name":"Operation/trace sequences","statistical_shape":"Time-ordered events and bounded spans, potentially irregular, asynchronous and partially observed","examples":["Collective operation/phase sequences","Repeated stalls or unexpected phase order","A duration subsequence with an unfamiliar shape"],"measurement_requirements":["Record bounded-buffer overwrites, continuity and drop markers","Preserve stream and communicator order and clock-domain semantics; device timestamps are not automatically milliseconds","State where host, GPU and communication dependency evidence is incomplete"],"candidate_algorithm_families":["Matrix-profile/subsequence-distance experiments on comparable numeric timing sequences","State/transition likelihood or HMM candidates on meaningfully encoded event sequences","Critical-path/residual analysis only where actual dependency evidence exists"],"selection_cautions":["Matrix profiles operate on numeric subsequences, not arbitrary JSON tokens","Z-normalizing subsequences can hide amplitude shifts; retain level-sensitive detectors","Do not invent causality/order across clock domains or gaps in a bounded trace"],"algorithm":"Pending"},{"id":"topology_graphs","name":"Topology and dependency graphs","statistical_shape":"Attributed nodes/edges with validity intervals; optionally graph-valued time series","examples":["Job/rank to GPU/node mapping","GPU-to-PCIe/NIC/port relations","Known link endpoints and changing placement"],"measurement_requirements":["Time-valid entity and edge mapping, with where each mapping came from","Switch, rail, cable and remote-path identities only when actually observed","Dependencies beyond connectivity need measured or declared semantics"],"candidate_algorithm_families":["Topology-conditioned peer/residual baselines","Graph-localization and graph-aware model research after a trustworthy graph dataset exists"],"selection_cautions":["A physical connectivity graph is not automatically a causal graph","Graph neural networks are not selected or justified merely because the topology can be drawn","Unknown routes must stay unknown"],"algorithm":"Pending"},{"id":"state_change_events","name":"Categorical state and configuration-change events","statistical_shape":"Timestamped state transitions and versioned before/after context","examples":["Port up/down, hotplug, throttle reason changes","Driver/library/configuration revision changes","Placement/resource-limit/concurrent-job changes"],"measurement_requirements":["Actor or source, timestamp and its uncertainty, affected scope, and before and after values","Distinguish an observed change from an inferred change","Version history rather than only the latest identity snapshot"],"candidate_algorithm_families":["State-transition and sequence-likelihood baselines","Context-conditioned performance residuals around changes","Matched before/after confirmation; causal tests separate from anomaly scoring"],"selection_cautions":["A software update or port-state change is not inherently a performance anomaly","Correlation with an event is not proof the event caused the regression","Rare legitimate maintenance/compilation phases need contextual controls"],"algorithm":"Pending"},{"id":"run_context_rows","name":"Run/probe context and feature tables","statistical_shape":"Mixed numeric/categorical rows with nested provenance; repeated measures per device/workload","examples":["One matched probe run and its measurements","Workload/batch/dtype/message-size/topology descriptors","Run-level feature views derived from raw evidence"],"measurement_requirements":["Explicit feature definitions, units and immutable transforms","Represent repeated observations by the same entity and workload; avoid accidental IID assumptions","Retain protocol, execution and instrumentation identity"],"candidate_algorithm_families":["Isolation Forest as an unsupervised tabular baseline","Contextual prediction/residual models where comparable training data permits","Robust cohort baselines before more complex models"],"selection_cautions":["JSON/CSV/Parquet/SQLite are containers, not different statistical problem types","Do not train on arbitrary entity IDs as if they were useful causal features","Separate same-device/repeated-run leakage from true held-out generalization"],"algorithm":"Pending"},{"id":"incident_outcomes","name":"Incident, cause and intervention/outcome records","statistical_shape":"Hierarchical incident objects linked to time series, evidence and verified outcome labels","examples":["One incident: detection, alternatives, confirmation and recovery","Healthy controls, false flags and known missed faults","Operator-confirmed or experiment-confirmed causes"],"measurement_requirements":["Real, controlled or synthetic origin, and the method of confirmation","Healthy and negative controls alongside faults","Outcome verification, and the evidence available at each prediction time"],"candidate_algorithm_families":["Supervised cause-ranking/classification research only after independently verified labels","Separate anomaly detection, cause ranking, probe selection and recovery verification evaluations","Calibrated abstention/unknown rather than compulsory diagnosis"],"selection_cautions":["Rule-generated hypotheses are not verified cause labels","Confirmed causes/future recovery/after-intervention signals are targets or post-event evidence, not pre-detection model inputs","Recovery after an intervention alone may still leave confounding; preserve confirmation limits"],"algorithm":"Pending"}]};
